/* This file is generated by scripts/tea-reference-markdown/build-pages.mjs from
 * data/tea-reference/entries/: approved composed entries only, keyed by product id. */
import type { ComposedEntry } from './composedEntry';

export const GENERATED_ENTRIES: Readonly<Record<string, ComposedEntry>> = {
  "00537dab-952d-46a7-a808-68a6a3ac506e": {"productId":"00537dab-952d-46a7-a808-68a6a3ac506e","paragraphs":[{"layer":"place","text":"The leaf comes from [Da Xue Shan](da-xue-shan:where-it-is), Big Snow Mountain, a name Yunnan gives to more than one mountain; Lincang alone has four. When the trade uses the name on its own it most often means the [Mengku peak](da-xue-shan:which-one), the main summit of the Bangma ridge on the border of Shuangjiang and Gengma counties, but the name by itself does not settle which mountain a tea is from. [Wild tree tea](da-xue-shan:wild-and-old), ancient garden tea and plantation tea are three different things, and all three are sold under this name."},{"layer":"age","text":"This is a cake of [raw pu’er](sheng:identity) from 2005. After the wok, raw pu’er is [dried in the sun](sheng:making) and never with hot air, so some of the leaf’s own activity survives, and that is what lets it keep changing for years. At twenty-one years it is past both points the trade gives for when [aged](sheng:ageing) begins: ten years for some, twenty or more for many. How far it has come depends on its [storage](sheng:storage), because the change is partly slow oxidation and partly the work of microbes, so heat and humidity set the pace."}],"brewing":{"layer":"brewing","text":"Pry the leaf off a cake or brick in chunks with a pick or knife, from the surface and toward the centre, rather than crumbling it. A mix of larger pieces and smaller ones brews evenly. Young raw pu’er takes water a little off the boil, about 85 to 95°C, because hotter water draws out more of its bitterness; an aged one takes 95°C to boiling. A common start is about 7 grams to 100 ml and a quick rinse of a few seconds, then a first steep of ten to fifteen seconds, adding a few seconds each round. A good raw tea gives eight to ten cups or more."},"notice":{"layer":"notice","styleName":"aged Sheng Pu’er","text":"A smoother, thicker, sweeter cup with woody, herbal and camphor notes and something of dried dates or dark fruit."},"missing":[]},
  "00ae378f-9474-4b71-8091-e7f41b75b4c0": {"productId":"00ae378f-9474-4b71-8091-e7f41b75b4c0","paragraphs":[{"layer":"type","text":"A rolled [oolong](oolong:definition) from Taiwan, made medium oxidised and given a moderate roast. That sets it near the middle of the type. Oolong is the partly oxidised tea, standing between green tea, which is not oxidised, and red tea, which is oxidised all the way."},{"layer":"type","text":"Like the rest of [Taiwan oolong](taiwan-oolong:definition), its plants and craft came over from Fujian, and the leaves are rolled tight, as most of the island's oolong is. [Oolong reached Taiwan](taiwan-oolong:history) with settlers from Fujian, and from the 1860s it was sold abroad as Formosa Oolong."}],"brewing":{"layer":"brewing","text":"Ball-rolled Taiwan oolong takes hot water, about 90 to 100°C, a fairly generous amount of leaf and short steeps; the balls open slowly and give many infusions. Roasted Dong Ding takes water from about 95°C to a full boil. Aged oolong takes very hot water, in a pot that holds its heat, clay above all. Oriental Beauty is the exception and takes cooler water, about 80 to 95°C."},"notice":{"layer":"notice","styleName":"Taiwan oolong","text":"In light high mountain tea: a sweet, floral cup, often creamy or buttery, with little bitterness and a long sweet aftertaste. In roasted Dong Ding: caramel, ripe fruit, nuts and a toasted aroma. In Baozhong: floral notes and a clear, bright liquor. In Oriental Beauty: ripe fruit and honey, with little bitterness."},"missing":[]},
  "00b13369-8aa6-40e9-9d9a-0f26a28bc7ff": {"productId":"00b13369-8aa6-40e9-9d9a-0f26a28bc7ff","paragraphs":[{"layer":"grade","text":"Gongjian, the [tribute tip](anhua-dark:family), is one of the three loose tips of Anhua tea, lightly pressed into bamboo baskets rather than moulded into bricks or rolls. It sits in the middle of the three, between Tianjian above it and the coarser, stalkier Shengjian below, since the raw leaf is sorted into [numbered grades](anhua-dark:grades) and each tea is made from the grade that suits it. The loose tips grew out of the [Qing border trade](anhua-dark:history) to the north-west."},{"layer":"place","text":"The leaf comes from Anhua County, a mountain county on the Zi river in Hunan and a protected origin for [Anhua dark tea](anhua-dark:definition). Like every Anhua tea it began as one raw tea, [heimaocha](anhua-dark:making): fixed, rolled, piled, rolled again and dried, then steamed soft and pressed lightly, as the loose tips are."},{"layer":"age","text":"This is a 2024 tea, two years old. Anhua tea is [kept for years](anhua-dark:ageing) and said to improve as it rests, though no agreed count of years marks it as aged. Kept clean, dry and aired, away from other smells, it can be left to change over the years ahead."}],"brewing":{"layer":"brewing","text":"In a small pot or gaiwan, use water at the boil and start with a steep of about 15 to 30 seconds, a little longer each round. Pressed and aged Anhua tea is also commonly simmered in a pot."},"notice":{"layer":"notice","styleName":"Anhua dark tea","text":"Pine smoke or pine resin above all, a sweet taste and aftertaste, and a mellow, thick, smooth cup; a liquor from yellow and orange to orange-red. Young tea is often smokier in the first infusions and a little bitter, sweetening as the infusions go on."},"missing":[]},
  "01f78200-1019-4201-8b8a-dbcd1a3d3eba": {"productId":"01f78200-1019-4201-8b8a-dbcd1a3d3eba","paragraphs":[{"layer":"lot","text":"A [green tea](green:definition) made in Japan in 1938. The part of Japan that grew the leaf is not recorded. It was [fixed with steam](green:styles), the usual Japanese way of [killing the green](green:making): heat applied soon after picking stops the leaf’s own enzymes, so it never oxidises and keeps its colour."},{"layer":"age","text":"Green tea is made to be drunk within a year or two, and there is no tradition of [keeping it for decades](green:ageing). At eighty-eight years this one sits far outside what the type promises. What it has become depends on how it was kept over those years, and the record does not say."}],"brewing":{"layer":"brewing","text":"Green tea takes water well below the boil, about 80°C, a little cooler for the youngest leaf and a little warmer for older, larger leaf. Boiling water draws out bitterness and dries the cup. A common start is about 2 grams of leaf to 100 ml, in a glass or a small gaiwan, with short steeps of half a minute to two minutes, and the same leaf can be brewed a few times."},"notice":{"layer":"notice","styleName":"green tea","text":"A fresh, clean cup that many call crisp, with a sweet, soft finish, and a pale green to yellow-green liquor. The smell runs from fresh leaf to flowers, and steamed teas lean grassy or seaweed-like. Too much heat or too long a steep turns the cup bitter and drying."},"missing":[]},
  "0382d7c6-d084-4940-af85-f336d6911131": {"productId":"0382d7c6-d084-4940-af85-f336d6911131","paragraphs":[{"layer":"lot","text":"Qing Mao Hong Cha is a loose [red tea](red:definition) from Yunnan, from the 2018 harvest."},{"layer":"age","text":"The trade keeps Yunnan red [for freshness rather than for age](dian-hong:ageing), and looks to its first one to three years. At eight years this leaf is well past that window."},{"layer":"type","text":"It belongs to the style sold as [Dian Hong](dian-hong:definition), made from the province's large-leaf trees. The leaf is [withered, rolled and left to oxidise](dian-hong:making) until it turns from green to reddish brown, then dried with heat to fix it."}],"brewing":{"layer":"brewing","text":"Dian Hong takes hot water, roughly 90 to 100°C. A common start is about 5 grams to 100 ml, with short steeps that lengthen slowly as the leaf opens."},"notice":{"layer":"notice","styleName":"Dian Hong","text":"A full, sweet cup, often described as malty, with chocolate or cocoa and honey notes and sometimes something floral. The liquor runs golden to bright red, and a good grade has little bitterness."},"missing":[]},
  "042456f9-f84e-425f-8eef-2aed102fedaa": {"productId":"042456f9-f84e-425f-8eef-2aed102fedaa","paragraphs":[{"layer":"place","text":"[Bulang Mountain](bulang-mountain:where-it-is) lies in the south of Menghai County in Xishuangbanna, along Yunnan’s border with Myanmar. It takes its name from the [Bulang people](bulang-mountain:people), who have grown tea there for a very long time. It is a wide mountain area of many villages, and [Bulang as a market name](bulang-mountain:on-a-label) points to a mountain style more than to one place. This tea names no village."},{"layer":"type","text":"The leaf was made into [ripe pu’er](shou:definition) in 2013. It was wetted and heaped in a warm, damp [pile](shou:wet-piling), which was turned about once a week to spread the heat the microbes make and to let air in. It was then dried and sold loose rather than pressed."},{"layer":"age","text":"At thirteen years it has passed into what the trade counts as [aged ripe pu’er](shou:age-aged). The leaf still changes slowly with the air and moisture around it, so storage matters as much as the years."}],"brewing":{"layer":"brewing","text":"Ripe pu’er takes boiling water: fermented, tightly packed leaf needs full heat to open, and it does not scald the way green tea can. A common start is about 7 grams to 100 ml and one quick rinse, which wakes the leaf and carries off dust and any pile smell. Then short steeps that lengthen as the leaf opens, so the cup stays clear rather than heavy; it gives eight or more good cups."},"notice":{"layer":"notice","styleName":"aged ripe pu’er","text":"A smooth, deep cup with woody, date-like or medicinal notes, which the trade calls aged aroma."},"missing":[]},
  "04729b3d-cf32-4bf8-b9a1-8695e247e403": {"productId":"04729b3d-cf32-4bf8-b9a1-8695e247e403","paragraphs":[{"layer":"lot","text":"This is [Meizhan](yancha:meizhan), a Fujian cultivar that came from Anxi, made in 1990 as [Wuyi rock tea](yancha:definition) from the [Wuyi Mountains](wuyi-mountains:where-it-is). It is less famous than Rougui and Shui Xian and is not one of the four famous bushes of Wuyi. The leaf was twisted into long strips and given a heavy [charcoal roast](yancha:making) in the traditional rock tea way. That roast dries the leaf so it keeps."},{"layer":"age","text":"A roast this heavy marks the kind of rock tea that is put away for years, because the heavier the roast, the longer the tea is said to stay good. Over thirty-six years the roast has settled fully into the leaf. Kept sealed, dry and cool, it is spared [going green again](yancha:ageing), the damp fault of stored rock tea."}],"brewing":{"layer":"brewing","text":"Wuyi tea is usually brewed gongfu style with water at or near the boil, about 95 to 100°C, and about 5 to 8 grams of leaf in a 100 to 120 ml gaiwan, a third to a half full. A quick rinse, poured off at once, is common. Steeps start short, about 5 to 20 seconds, and grow a few seconds longer each round, and good rock tea gives seven steeps or more. In a larger pot, use about 2 to 5 grams for 250 to 350 ml and steep two to three minutes."},"notice":{"layer":"notice","styleName":"aged Wuyi rock tea","text":"A smoother, thicker liquor with less sharpness, the roast softened and the high aroma faded."},"missing":[]},
  "04b14fad-842b-4adc-8c7b-f99662eec0a7": {"productId":"04b14fad-842b-4adc-8c7b-f99662eec0a7","paragraphs":[{"layer":"grade","text":"A cake of [Liu Bao](liu-bao:definition) from 1999, made under [Three Cranes](three-cranes:definition), the trademark of Wuzhou Tea Factory, the largest maker of this [dark tea](dark:definition). The mark belongs to that one factory and names neither a grade of leaf nor a village. Around 1958 the same factory worked out [cold-water piling](liu-bao:making-factory): the leaf is wetted, heaped at a modest warmth and turned until it darkens, a steadier route than the farmhouse steaming that came before."},{"layer":"place","text":"The city stands in the east of Guangxi on the Guangdong border, where the Xi and Gui rivers meet. The tea takes its name from Liubao town in [Cangwu County](guangxi:wuzhou-and-cangwu), in the countryside under the city. The city itself was where leaf from the hills was gathered, finished and sent downriver on what the trade still calls the [old tea boat road](wuzhou:liu-bao-trade), to Guangzhou and then by sea to the Chinese workers of Southeast Asia."},{"layer":"age","text":"At twenty-seven years this cake is well past the ten after which the trade counts a Liu Bao as [aged](liu-bao:age-aged). How it was stored matters as much as how long, and the trade does not agree whether such tea keeps improving for decades or peaks sooner."}],"brewing":{"layer":"brewing","text":"From a brick, cake or basket, ease the leaf off along the edge or from the top with a pick rather than snapping it. Whole pieces give up their flavour steadily; crumbs release it all at once and cloud the cup. Liu Bao takes very hot or boiling water, because its leaf is dense and gives up its depth slowly. Rinse it once or twice and pour the rinse away. Use about 5 to 8 grams to 100 ml, start with steeps of five to fifteen seconds and add a few seconds each round; a good Liu Bao gives ten cups or more."},"notice":{"layer":"notice","styleName":"aged Liu Bao","text":"A deep red, thick cup with woody, herbal and betel nut notes; tea several decades old is often described with ginseng and camphor."},"missing":[]},
  "08a89679-b873-4948-a41d-00adfb2fd7d6": {"productId":"08a89679-b873-4948-a41d-00adfb2fd7d6","paragraphs":[{"layer":"place","text":"This leaf grew in [Anxi](anxi:where-it-is), a county of southern Fujian in Quanzhou prefecture, on the southern side of the Daiyun mountains, where [Tieguanyin](anxi:known-for) fills most of the tea land. The county is warm, wet and misty, and its hills of [weathered granite](anxi:why-tea) break down into acidic red and yellow soil that drains freely, which is why tea does well there."},{"layer":"type","text":"[Tieguanyin](tieguanyin:definition) is the name of a cultivar and of the [oolong](oolong:definition) made from it, a partly oxidised tea. Once the leaf is shaken, fixed and rolled, it goes through [cloth wrap rolling](tieguanyin:making): it is wrapped, pressed and dried a little, over and over, and each round draws it tighter into the balls it keeps here. This one was then made into a [scented tea](tieguanyin:osmanthus): fresh osmanthus flowers were layered through the finished tea, and the tea was dried once more."}],"brewing":{"layer":"brewing","text":"Tieguanyin is usually brewed gongfu style with water at or near the boil, about 95 to 100°C; the light green style is often taken a little cooler, about 85 to 95°C. Use about 4 to 8 grams of leaf in a 100 to 150 ml gaiwan or pot, about a third full. A quick rinse, poured off at once, is common. Steeps start short, about 10 to 30 seconds, and grow a few seconds longer each round, and a good Tieguanyin gives about six to eight. In a larger pot, use about 2.5 to 5 grams for 240 to 350 ml and steep two to three minutes."},"notice":{"layer":"notice","styleName":"Tieguanyin","text":"In the light style: orchid and other flowers, a fresh, clean cup and a sweet aftertaste. In the roasted style: toast and charcoal, caramel or honey, stone or dried fruit, nuts, and a liquor that runs from gold to amber."},"missing":[]},
  "0bc826ca-79b8-43b1-ae9f-605c016435eb": {"productId":"0bc826ca-79b8-43b1-ae9f-605c016435eb","paragraphs":[{"layer":"place","text":"A [red tea](red:definition) made in 2023 on [Taiwan](taiwan:on-a-label). Red tea is the fully oxidised tea that English calls black. The record names only the island, not a mountain or township, so where on it the garden lies is not known. The island is known above all for [oolong](taiwan:known-for), and it [turned to black tea](taiwan:history) under Japanese rule, when red tea was first made at [Yuchi](red:history) near Sun Moon Lake."},{"layer":"age","text":"Red tea has no tradition of [ageing](red:ageing). Sealed, it keeps its quality for about a year and a half to three years. At three years this tea sits at the far end of that span, so it is one to drink now rather than to keep."}],"brewing":{"layer":"brewing","text":"Red tea takes water near the boil, about 90 to 100°C; hotter water draws out its aroma and flavour more fully, but its bitterness faster too. In a pot or mug, use about a rounded spoon of leaf for each cup and steep three to five minutes, less for broken leaf and a little less, and a little cooler, for a light, delicate tea. Left too long, it turns bitter and drying, because time and heat pull more tannins from the leaf."},"notice":{"layer":"notice","styleName":"red tea","text":"A sweet cup, often with honey, floral or fruity notes, malt in many, and a brisk strength in the stronger teas. The liquor runs red, bright to deep."},"missing":[]},
  "11d76d7b-0414-4802-84f1-30aee180b644": {"productId":"11d76d7b-0414-4802-84f1-30aee180b644","paragraphs":[{"layer":"place","text":"This cake's leaf comes from [Yiwu](greater-yiwu:where-it-is), in the north of Mengla County in Xishuangbanna, on the east side of the Lancang River. It is one of the old Six Famous Tea Mountains, and its town has long been the place where tea from the surrounding villages is gathered and processed."},{"layer":"type","text":"The leaf was made into [ripe pu’er](shou:definition), a method developed to give in weeks what raw pu’er takes years of keeping to become. In [wet piling](shou:wet-piling) the sun-dried leaf is wetted and heaped, and the microbes working in it make their own heat. The pile is covered to hold that heat in and turned about once a week to spread it and let air through. It is kept below about 65°C, because any hotter and the leaf begins to char. After one to two months the leaf is dried, and this lot was then pressed into a cake."}],"brewing":{"layer":"brewing","text":"From a cake, brick or tuo, ease a piece off along the edge with a pick rather than snapping it. Whole leaves give up their flavour steadily; broken ones release it all at once and cloud the cup. Ripe pu’er takes boiling water: fermented, tightly packed leaf needs full heat to open, and it does not scald the way green tea can. A common start is about 7 grams to 100 ml and one quick rinse, which wakes the leaf and carries off dust and any pile smell. Then short steeps that lengthen as the leaf opens, so the cup stays clear rather than heavy; it gives eight or more good cups."},"notice":{"layer":"notice","styleName":"ripe pu’er","text":"A smooth, sweet cup with earthy or woody notes. A young ripe tea can carry a faint smell of the pile, which fades with airing or in the first steeps."},"missing":[]},
  "12a441ca-0045-4657-8efc-03b873ab62fc": {"productId":"12a441ca-0045-4657-8efc-03b873ab62fc","paragraphs":[{"layer":"place","text":"This [oolong](oolong:definition), a partly oxidised tea, comes from [Nantou](nantou:where-it-is). Nantou lies in the middle of Taiwan and is the island's only county that does not touch the sea. It is also [Taiwan's biggest tea county](nantou:why-people-value-it). Its land climbs from low hills to cold mountain gardens, and the trade divides its tea country into [low, middle and high belts](nantou:altitude-bands), because the height of a garden decides which style it makes. This record names only the county, not the township, so it does not say which belt the leaf grew in."},{"layer":"age","text":"It was made in 1979 and rolled, as most [Taiwan oolong](taiwan-oolong:definition) is, so it is now forty-seven years old. Taiwan has a tradition of keeping oolong for years, called [lao cha](taiwan-oolong:ageing), or old tea. A kept tea is roasted again at low heat from time to time to drive out the moisture it takes in, and stored cool, dry, dark and sealed. No standard says when an oolong becomes old. Those who give a figure put it between ten and thirty years, and this tea is well past that."}],"brewing":{"layer":"brewing","text":"Ball-rolled Taiwan oolong takes hot water, about 90 to 100°C, a fairly generous amount of leaf and short steeps; the balls open slowly and give many infusions. Roasted Dong Ding takes water from about 95°C to a full boil. Aged oolong takes very hot water, in a pot that holds its heat, clay above all. Oriental Beauty is the exception and takes cooler water, about 80 to 95°C."},"notice":{"layer":"notice","styleName":"aged Taiwan oolong","text":"A smooth, mellow, thick cup with little astringency, often plum or prune, sometimes something like medicinal herbs or ginseng, and an amber to red-brown liquor."},"missing":[]},
  "14c448bb-db0e-4b9f-b644-d1d4f88eba38": {"productId":"14c448bb-db0e-4b9f-b644-d1d4f88eba38","paragraphs":[{"layer":"lot","text":"Courage came to the shop already named, from a private collection in mainland China. The leaf is from Yunnan. The mountain and village it grew on were not recorded."},{"layer":"type","text":"It is [raw pu’er](sheng:identity), the branch of pu’er never given shou’s rapid fermentation. The leaf is fried in a wok to [kill the green](sheng:making), which stops most of its enzymes but not all, then rolled and dried in the sun. The activity that survives that heat is what lets the tea keep [changing in storage](sheng:aging) for years. Where a tea is kept is part of its history, though not a promise of quality."}],"brewing":{"layer":"brewing","text":"Young raw pu’er takes water a little off the boil, about 85 to 95°C, because hotter water draws out more of its bitterness; an aged one takes 95°C to boiling. A common start is about 7 grams to 100 ml and a quick rinse of a few seconds, then a first steep of ten to fifteen seconds, adding a few seconds each round. A good raw tea gives eight to ten cups or more."},"notice":{"layer":"notice","styleName":"Sheng Pu’er","text":"In young raw pu’er, a bitter, drying bite that turns into a returning sweetness, a feel in the throat that makes the mouth water, and fresh, floral or fruity notes such as apricot or plum. Tea kept in humid storage can carry a damp, earthy storage taste."},"missing":[]},
  "15a8c483-c2d4-4192-9977-0273a3d538d8": {"productId":"15a8c483-c2d4-4192-9977-0273a3d538d8","paragraphs":[{"layer":"type","text":"A [ripe pu’er](shou:definition) tuo from Menghai leaf, made in 1980. Its leaf was fermented in a [wet pile](shou:wet-piling) before pressing. The pile was developed to give in weeks what raw pu’er gained only after years of keeping. The year puts this tea in the style’s first decade. In 1973 a team from the Kunming, Menghai and Xiaguan factories went to Guangzhou to [learn its piling](shou:piling-1973), and by 1975 Menghai’s method had settled into the ripe pu’er made today, five years before this tuo."},{"layer":"age","text":"At forty-six years it is long past the decade after which the trade counts a tea as [aged ripe pu’er](shou:age-aged). The leaf goes on changing slowly with the air and moisture around it, so the way it has been kept matters as much as the years."}],"brewing":{"layer":"brewing","text":"From a cake, brick or tuo, ease a piece off along the edge with a pick rather than snapping it. Whole leaves give up their flavour steadily; broken ones release it all at once and cloud the cup. Ripe pu’er takes boiling water: fermented, tightly packed leaf needs full heat to open, and it does not scald the way green tea can. A common start is about 7 grams to 100 ml and one quick rinse, which wakes the leaf and carries off dust and any pile smell. Then short steeps that lengthen as the leaf opens, so the cup stays clear rather than heavy; it gives eight or more good cups."},"notice":{"layer":"notice","styleName":"aged ripe pu’er","text":"A smooth, deep cup with woody, date-like or medicinal notes, which the trade calls aged aroma."},"missing":[]},
  "163dd7e7-68f8-4440-b9d8-dc0682df2fbf": {"productId":"163dd7e7-68f8-4440-b9d8-dc0682df2fbf","paragraphs":[{"layer":"age","text":"An [oolong](oolong:definition) from China, made in 2012 and now fourteen years old. Only oolong that was well made and well roasted is [kept to age](oolong:ageing). The lighter, green style teas are meant to be drunk young. Damp is the risk over that many years: leaf that was not dried enough takes up moisture, so oolong kept this long is usually roasted again at low heat from time to time. That is skilled work, and each round can cost the tea a little. The trade has no agreed age at which an oolong counts as aged."},{"layer":"type","text":"Oolong sits between green tea and red tea, and its making sets where. The leaf is [tossed in rounds](oolong:making) with rests between them, so its bruised edges oxidise and the change spreads slowly inward. Then high heat stops it at the point the maker wants. How hard the leaf is [roasted](oolong:oxidation-and-roast) afterwards is a separate choice. Roasting lowers the moisture in the leaf."}],"brewing":{"layer":"brewing","text":"Oolong is most often brewed gongfu style, in a small gaiwan or clay pot with plenty of leaf and short steeps, and it stands many rounds. A common start is about 4 to 6 grams to 100 ml, with a first steep of roughly 5 to 15 seconds and 5 to 10 seconds more each round. Light, green-style oolong takes water a little off the boil, about 90 to 95°C; heavily oxidised, roasted and aged oolong takes water at a full boil. Many people pour a quick first rinse to wake tightly rolled leaf. In a larger pot, use less leaf and steep for a few minutes."},"notice":{"layer":"notice","styleName":"aged oolong","text":"A smooth, mellow and sweet cup, often with dried fruit or plum and wood, sometimes something herbal, little astringency, and an amber to red-brown liquor."},"missing":[]},
  "16cb52e5-444e-4656-8b49-1f3eb4f97b23": {"productId":"16cb52e5-444e-4656-8b49-1f3eb4f97b23","paragraphs":[{"layer":"type","text":"A loose [red tea](red:definition) from Yunnan, the tea English calls black. The Chinese name follows the red of the brewed cup. Red tea made in this province from the large leaf of its own tea trees is known as [Dian Hong](dian-hong:definition). The garden this leaf came from was not recorded."},{"layer":"type","text":"Dian Hong began when the war cut China off from its eastern tea regions, the country needed a new red tea to sell abroad, and the national tea company turned to Yunnan. Feng Shaoqiu made [a trial batch in Shunning](dian-hong:history), now Fengqing, in late 1938, and a factory followed there the next year. For decades nearly all of it went overseas. It was sold widely in China only from the 1980s."}],"brewing":{"layer":"brewing","text":"Dian Hong takes hot water, roughly 90 to 100°C. A common start is about 5 grams to 100 ml, with short steeps that lengthen slowly as the leaf opens."},"notice":{"layer":"notice","styleName":"Dian Hong","text":"A full, sweet cup, often described as malty, with chocolate or cocoa and honey notes and sometimes something floral. The liquor runs golden to bright red, and a good grade has little bitterness."},"missing":[]},
  "177716c0-c199-4c76-8eca-53d4e764692d": {"productId":"177716c0-c199-4c76-8eca-53d4e764692d","paragraphs":[{"layer":"place","text":"This [raw pu’er](sheng:identity) cake comes from [Dali](dali:where-it-is), the prefecture in western Yunnan that lies north of Lincang and well north of the pu’er mountains of Xishuangbanna. The prefecture [grows only a little tea of its own](dali:grown-in-dali), mainly on the Cang mountains and the Wuliang range in Nanjian County. Its name is known in pu’er mostly through [the pressing and trading](dali:tuocha-trade) that grew up there on the old caravan routes."},{"layer":"age","text":"The cake was made in 2005 and is now twenty-one years old. Its leaf was [fried in a wok to kill the green](sheng:making) but never dried with hot air afterwards. Because of that, some of the leaf’s own activity survived, and that is what has let the tea keep changing since. At this age it is past both lines the trade draws for [aged raw pu’er](sheng:ageing): ten years for some, twenty or more for many. How far it has travelled depends on [where it was kept](sheng:storage), because heat and humidity set the pace. It also depends on [how it was pressed](sheng:pressing), because a tight cake changes more slowly than a loose one."}],"brewing":{"layer":"brewing","text":"Pry the leaf off a cake or brick in chunks with a pick or knife, from the surface and toward the centre, rather than crumbling it. A mix of larger pieces and smaller ones brews evenly. Young raw pu’er takes water a little off the boil, about 85 to 95°C, because hotter water draws out more of its bitterness; an aged one takes 95°C to boiling. A common start is about 7 grams to 100 ml and a quick rinse of a few seconds, then a first steep of ten to fifteen seconds, adding a few seconds each round. A good raw tea gives eight to ten cups or more."},"notice":{"layer":"notice","styleName":"aged Sheng Pu’er","text":"A smoother, thicker, sweeter cup with woody, herbal and camphor notes and something of dried dates or dark fruit."},"missing":[]},
  "186380ba-6839-448f-baaf-2b84ef7e5556": {"productId":"186380ba-6839-448f-baaf-2b84ef7e5556","paragraphs":[{"layer":"named","text":"The name reads as a place, a description and a style. [Mahei](mahei-gushu-red:tea-name) is the village in Yiwu, gushu means old tree, as the label describes it, and hong cha means red tea. A section of the old [Tea Horse Road](mahei:village-road-and-harvest) passes through the village, and in April 2024 the farmer Ding Wanchun told local reporters his family needed more than twenty pickers a day for the spring harvest."},{"layer":"type","text":"The leaf was made into [red tea](red:definition), the fully oxidised tea English calls black. It was [withered, then rolled](dian-hong:making) to break its cells so oxidation could begin, left until it turned from green to reddish brown, and then dried. It belongs to the newer branch sold as [old-tree red](dian-hong:old-tree-and-sun-dried), which has no agreed definition or standard."},{"layer":"age","text":"This is a 2025 tea, one year old. Yunnan red tea is [kept for freshness](dian-hong:ageing) rather than for age, and the trade drinks it within its first one to three years."}],"brewing":{"layer":"brewing","text":"Dian Hong takes hot water, roughly 90 to 100°C. A common start is about 5 grams to 100 ml, with short steeps that lengthen slowly as the leaf opens."},"notice":{"layer":"notice","styleName":"Dian Hong","text":"A full, sweet cup, often described as malty, with chocolate or cocoa and honey notes and sometimes something floral. The liquor runs golden to bright red, and a good grade has little bitterness."},"missing":[]},
  "1c65863b-dac7-4b0b-9b9e-e60d4a30ec67": {"productId":"1c65863b-dac7-4b0b-9b9e-e60d4a30ec67","paragraphs":[{"layer":"type","text":"A loose [raw pu’er](sheng:identity) from Yunnan, the undarkened branch of the family, never given the quick fermentation that makes shou. It begins as leaf from the province’s large-leaf tea trees, picked and withered, then fried in a wok to [kill the green](sheng:making), rolled, and dried in the sun over a couple of days. What comes out is [maocha](sheng:processing), the rough tea, and here it has been left loose instead of steamed and pressed into a cake."},{"layer":"type","text":"The wok heat stops most of the leaf’s own enzymes but not all, and because the leaf is never hot-air dried afterwards, the activity that survives lets it keep [changing through storage](sheng:aging) for years. Where and how it is kept becomes part of its history."}],"brewing":{"layer":"brewing","text":"Young raw pu’er takes water a little off the boil, about 85 to 95°C, because hotter water draws out more of its bitterness; an aged one takes 95°C to boiling. A common start is about 7 grams to 100 ml and a quick rinse of a few seconds, then a first steep of ten to fifteen seconds, adding a few seconds each round. A good raw tea gives eight to ten cups or more."},"notice":{"layer":"notice","styleName":"Sheng Pu’er","text":"In young raw pu’er, a bitter, drying bite that turns into a returning sweetness, a feel in the throat that makes the mouth water, and fresh, floral or fruity notes such as apricot or plum. Tea kept in humid storage can carry a damp, earthy storage taste."},"missing":[]},
  "1ce96c77-6c8c-4cf3-a1ee-dcba5189622f": {"productId":"1ce96c77-6c8c-4cf3-a1ee-dcba5189622f","paragraphs":[{"layer":"type","text":"A cake of [Yunnan white](yunnan-white:definition) from Yunnan, made from the province's large-leaf tea plants rather than the smaller bush cultivars of Fujian. Like all [white tea](white:definition), it is made in the fewest steps. The leaf is never heated to stop its change and never rolled, so it keeps its natural shape."},{"layer":"type","text":"The Yunnan way differs from the Fujian one. The leaf is [withered indoors or in shade](yunnan-white:making) instead of under the midday sun, then dried by air, without the final low bake that Fujian white usually gets. It was then pressed into a cake, one of the shapes Yunnan borrows from pu'er. White tea from Yunnan has only found its place in the market in recent years, though [local practice may be older](yunnan-white:history)."}],"brewing":{"layer":"brewing","text":"Yunnan white is brewed gently, as a white tea is, in a gaiwan or small pot, and it gives many infusions; the leaf holds up well."},"notice":{"layer":"notice","styleName":"Yunnan white","text":"A honeyed, sweet cup, often richer and fuller than Fujian white, with little bitterness, sometimes fruit like apricot or melon and a hay or herbal note. Yabao is sweet and silky, often with pine or herbal notes."},"missing":[]},
  "1db0a71d-7259-4333-a5b3-985dbe546eb7": {"productId":"1db0a71d-7259-4333-a5b3-985dbe546eb7","paragraphs":[{"layer":"place","text":"This cake's leaf comes from [Yiwu](greater-yiwu:where-it-is), in the north of Mengla County in Xishuangbanna, east of the Lancang River. It is one of the old Six Famous Tea Mountains, and its town has long been where tea from the surrounding villages is gathered and processed."},{"layer":"age","text":"The cake dates from the 1980s. At about forty-one years, it sits well inside what the trade counts as [aged ripe pu’er](shou:age-aged). The leaf keeps changing slowly with the air and moisture around it, so how it was kept matters as much as how long."},{"layer":"type","text":"The leaf was made into [ripe pu’er](shou:definition). It was heaped warm and damp so that it could be drunk soon after making instead of after years of waiting, then pressed into a cake. Yunnan's factories first brought [wet piling](shou:wet-piling) into production in 1973, so this tea comes from the method's first two decades."}],"brewing":{"layer":"brewing","text":"From a cake, brick or tuo, ease a piece off along the edge with a pick rather than snapping it. Whole leaves give up their flavour steadily; broken ones release it all at once and cloud the cup. Ripe pu’er takes boiling water: fermented, tightly packed leaf needs full heat to open, and it does not scald the way green tea can. A common start is about 7 grams to 100 ml and one quick rinse, which wakes the leaf and carries off dust and any pile smell. Then short steeps that lengthen as the leaf opens, so the cup stays clear rather than heavy; it gives eight or more good cups."},"notice":{"layer":"notice","styleName":"aged ripe pu’er","text":"A smooth, deep cup with woody, date-like or medicinal notes, which the trade calls aged aroma."},"missing":[]},
  "2086d7ce-1a33-4230-977d-1f3f9880f09e": {"productId":"2086d7ce-1a33-4230-977d-1f3f9880f09e","paragraphs":[{"layer":"type","text":"A loose [red tea](red:definition) from Yunnan, made in 2024. Red tea is what English calls black tea. The Chinese name follows the colour of the cup, and the tea is fully oxidised: the rolled leaf is left until it turns from green to reddish brown. In Yunnan the style is [Dian Hong](dian-hong:definition). It [began in late 1938](dian-hong:history), when the war cut China off from its eastern tea regions and Feng Shaoqiu made a trial batch at Shunning, now Fengqing, from the province's large leaf."},{"layer":"age","text":"At two years this leaf still sits within the window the trade favours for the style, its first one to three years. [Dian Hong is kept](dian-hong:ageing) for freshness rather than for age."}],"brewing":{"layer":"brewing","text":"Dian Hong takes hot water, roughly 90 to 100°C. A common start is about 5 grams to 100 ml, with short steeps that lengthen slowly as the leaf opens."},"notice":{"layer":"notice","styleName":"Dian Hong","text":"A full, sweet cup, often described as malty, with chocolate or cocoa and honey notes and sometimes something floral. The liquor runs golden to bright red, and a good grade has little bitterness."},"missing":[]},
  "2194866f-f580-457f-b8ad-c5d027785e2a": {"productId":"2194866f-f580-457f-b8ad-c5d027785e2a","paragraphs":[{"layer":"lot","text":"A cake of [ripe pu’er](shou:definition) from Yunnan, sold as aged. Its year and its exact source in the province are not recorded, so the cake carries its age without a date to put on it."},{"layer":"type","text":"The leaf went through [wet piling](shou:wet-piling) before it was pressed: wetted and heaped so that heat, moisture and microbes could work on it, covered to hold in the heat the microbes make, and turned about once a week to let air in. The pile was developed to do in weeks what years of storage once did for raw pu’er, the tea Hong Kong and Guangdong drinkers had grown used to. Yunnan’s factories [took up the method](shou:piling-1973) in 1973, and the years this cake has spent since its making add a second, slower change on top of the pile."}],"brewing":{"layer":"brewing","text":"From a cake, brick or tuo, ease a piece off along the edge with a pick rather than snapping it. Whole leaves give up their flavour steadily; broken ones release it all at once and cloud the cup. Ripe pu’er takes boiling water: fermented, tightly packed leaf needs full heat to open, and it does not scald the way green tea can. A common start is about 7 grams to 100 ml and one quick rinse, which wakes the leaf and carries off dust and any pile smell. Then short steeps that lengthen as the leaf opens, so the cup stays clear rather than heavy; it gives eight or more good cups."},"notice":{"layer":"notice","styleName":"ripe pu’er","text":"A smooth, sweet cup with earthy or woody notes. A young ripe tea can carry a faint smell of the pile, which fades with airing or in the first steeps."},"missing":[]},
  "2205c8f5-bcc9-4ec2-823b-fecf68db56fb": {"productId":"2205c8f5-bcc9-4ec2-823b-fecf68db56fb","paragraphs":[{"layer":"age","text":"This ripe pu’er cake dates to 2015 and is listed as Pasha, Menghai. As ripe pu’er rests, the [air and moisture](shou:age-aged) around the leaves shape how its aroma develops."}],"missing":[]},
  "255157c3-0852-4228-a294-4a27bf670485": {"productId":"255157c3-0852-4228-a294-4a27bf670485","paragraphs":[{"layer":"place","text":"This red tea comes from [Yuchi](yuchi:where-it-is), the township around Sun Moon Lake in the middle of Nantou County, where tea grows on gentle slopes at roughly 600 to 800 metres. The basin is warm and misty, with deep reddish soil, and the Japanese tea men who first trialled it compared it to [the Assam country of India](yuchi:why-red-tea). Under Japanese rule, large leaf [Assam seed brought from India](yuchi:assam-planting) was planted here to make red tea for export. This leaf was made in 1977, while that trade was [fading](yuchi:decline-and-return): from the 1970s, rising wages made hand picked leaf costly against red tea from other countries, and many growers in the township turned to oolong or to other crops."},{"layer":"age","text":"[Red tea](red:definition), the fully oxidised tea that English calls black tea, has [no tradition of ageing](red:ageing). Sealed, it is expected to keep its quality for a year and a half to three years. This leaf has been kept for forty-nine years, long past that span."}],"brewing":{"layer":"brewing","text":"Red tea takes water near the boil, about 90 to 100°C; hotter water draws out its aroma and flavour more fully, but its bitterness faster too. In a pot or mug, use about a rounded spoon of leaf for each cup and steep three to five minutes, less for broken leaf and a little less, and a little cooler, for a light, delicate tea. Left too long, it turns bitter and drying, because time and heat pull more tannins from the leaf."},"notice":{"layer":"notice","styleName":"red tea","text":"A sweet cup, often with honey, floral or fruity notes, malt in many, and a brisk strength in the stronger teas. The liquor runs red, bright to deep."},"missing":[]},
  "25f429f2-6601-46bd-844c-b2dab6dbf28d": {"productId":"25f429f2-6601-46bd-844c-b2dab6dbf28d","paragraphs":[{"layer":"type","text":"A brick of [raw pu’er](sheng:identity) from Yunnan, the branch of pu’er that is never darkened by fast fermentation. Like all raw pu’er it begins as large-leaf tea that is [fried in a wok to kill the green](sheng:making), rolled and dried in the sun rather than by hot air, so some of the leaf’s own activity survives and lets the tea keep changing for years."},{"layer":"type","text":"Tea was first [pressed](sheng:pressing) so it could travel, packed compact onto pack animals along the old trade routes, and the pressing still decides how it ages: a tight, large piece changes slowly, a loose or small one faster. With no rapid fermentation behind it, this brick [changes through storage](sheng:aging), so where it has been kept is part of its history, not a promise of quality."}],"brewing":{"layer":"brewing","text":"Pry the leaf off a cake or brick in chunks with a pick or knife, from the surface and toward the centre, rather than crumbling it. A mix of larger pieces and smaller ones brews evenly. Young raw pu’er takes water a little off the boil, about 85 to 95°C, because hotter water draws out more of its bitterness; an aged one takes 95°C to boiling. A common start is about 7 grams to 100 ml and a quick rinse of a few seconds, then a first steep of ten to fifteen seconds, adding a few seconds each round. A good raw tea gives eight to ten cups or more."},"notice":{"layer":"notice","styleName":"Sheng Pu’er","text":"In young raw pu’er, a bitter, drying bite that turns into a returning sweetness, a feel in the throat that makes the mouth water, and fresh, floral or fruity notes such as apricot or plum. Tea kept in humid storage can carry a damp, earthy storage taste."},"missing":[]},
  "262a3bcf-51b7-4e50-bac0-2f003e2d93c8": {"productId":"262a3bcf-51b7-4e50-bac0-2f003e2d93c8","paragraphs":[{"layer":"type","text":"A brick of [ripe pu’er](shou:definition): leaf fermented in a warm, damp pile before pressing, so that it was ready to drink soon after it was made rather than set aside for years as raw pu’er is."},{"layer":"type","text":"The pile grew out of the old trade. Pu’er once reached Hong Kong and Guangzhou after a caravan journey of up to a year and further years in merchants’ keeping, and when faster transport in the 1950s brought fresher tea, the trade set out to [hurry that change](shou:piling-history). In [wet piling](shou:wet-piling), leaf dried in the sun is wetted and heaped, covered to hold in the heat its microbes make, and turned about once a week to spread that heat and let air in. After one to two months the leaf is dried."}],"brewing":{"layer":"brewing","text":"From a cake, brick or tuo, ease a piece off along the edge with a pick rather than snapping it. Whole leaves give up their flavour steadily; broken ones release it all at once and cloud the cup. Ripe pu’er takes boiling water: fermented, tightly packed leaf needs full heat to open, and it does not scald the way green tea can. A common start is about 7 grams to 100 ml and one quick rinse, which wakes the leaf and carries off dust and any pile smell. Then short steeps that lengthen as the leaf opens, so the cup stays clear rather than heavy; it gives eight or more good cups."},"notice":{"layer":"notice","styleName":"ripe pu’er","text":"A smooth, sweet cup with earthy or woody notes. A young ripe tea can carry a faint smell of the pile, which fades with airing or in the first steeps."},"missing":[]},
  "27eb4e34-0490-4b5c-be7d-917709ddef8d": {"productId":"27eb4e34-0490-4b5c-be7d-917709ddef8d","paragraphs":[{"layer":"lot","text":"A cake of [raw pu’er](sheng:identity) from Yunnan, dated 1990, which came to the shop with no record of the garden it was picked from. That was common for its era. Buyers began choosing by [named mountains and villages](sheng:history-modern) rather than factory brands only after the collectors’ boom of the 1980s and 1990s."},{"layer":"age","text":"Raw pu’er is never pushed through [a rapid fermentation](sheng:aging). Its leaf is [dried in the sun](sheng:making) rather than with hot air, so some of the leaf’s own activity survives, and the tea keeps changing on its own for years. At thirty-six years, this cake is well past the twenty that many in the trade wait for before they call a [raw pu’er aged](sheng:ageing). Heat and humidity decide how fast that change happens, so the way it was [stored](sheng:storage) is part of its history."}],"brewing":{"layer":"brewing","text":"Pry the leaf off a cake or brick in chunks with a pick or knife, from the surface and toward the centre, rather than crumbling it. A mix of larger pieces and smaller ones brews evenly. Young raw pu’er takes water a little off the boil, about 85 to 95°C, because hotter water draws out more of its bitterness; an aged one takes 95°C to boiling. A common start is about 7 grams to 100 ml and a quick rinse of a few seconds, then a first steep of ten to fifteen seconds, adding a few seconds each round. A good raw tea gives eight to ten cups or more."},"notice":{"layer":"notice","styleName":"aged Sheng Pu’er","text":"A smoother, thicker, sweeter cup with woody, herbal and camphor notes and something of dried dates or dark fruit."},"missing":[]},
  "28436463-2272-4f68-83e1-b6d86f798be2": {"productId":"28436463-2272-4f68-83e1-b6d86f798be2","paragraphs":[{"layer":"lot","text":"This ripe pu’er brick is from Yunnan and dates to 1990. Ripe pu’er gets its character from [wet piling](shou:wet-piling), a process in which damp tea leaves ferment before the tea is dried."}],"missing":[]},
  "290de77e-c3e1-4f14-86de-435f2917a790": {"productId":"290de77e-c3e1-4f14-86de-435f2917a790","paragraphs":[{"layer":"place","text":"This is [Dancong](dancong:name), the [oolong](oolong:definition) of [Phoenix Mountain](phoenix-mountain:where-it-is), a range in Fenghuang town in Chao'an, Chaozhou, in the east of Guangdong. Its name means single bush: the leaf of one bush picked and made on its own, from bushes chosen among the old Phoenix Shuixian plants of the mountain. Tea grows on these slopes from the low foothills up to roughly 1,100 metres. [Cloud and mist](phoenix-mountain:mist-and-climate) sit on the upper slopes for much of the year and the nights are cool, so the bushes grow slowly."},{"layer":"age","text":"To make Dancong, the leaf is withered in the sun, shaken and rested in rounds, then [fixed fast at high heat, rolled into strips and roasted](dancong:making), traditionally over charcoal. A newly roasted Dancong is usually [rested for some months](dancong:ageing) before it is drunk. This leaf was made in 1950, so it has had seventy-six years."}],"brewing":{"layer":"brewing","text":"Brew it gongfu style in a small gaiwan or clay pot, with about 3 to 8 grams for 100 to 120 ml and hot water, about 88 to 100°C; Chinese accounts mostly say 95 to 100°C. A quick rinse is common. Steeps start at a few seconds and grow a few seconds each round, and a good Dancong gives about eight to fifteen. Too long, too hot or too much leaf and it turns bitter and astringent."},"notice":{"layer":"notice","styleName":"aged oolong","text":"A smooth, mellow and sweet cup, often with dried fruit or plum and wood, sometimes something herbal, little astringency, and an amber to red-brown liquor."},"missing":[]},
  "2a818fa4-8a3c-4dd2-baa3-f04795b0fc18": {"productId":"2a818fa4-8a3c-4dd2-baa3-f04795b0fc18","paragraphs":[{"layer":"lot","text":"A [ripe pu’er](shou:definition) from 1980, made from Yunnan leaf and pressed into small, round cakes, the xiao yuan bing of its Chinese name. That year falls in the style’s first decade. In 1973 a team from the Kunming, Menghai and Xiaguan factories went to Guangzhou to [learn its wet piling](shou:piling-1973), and that same year Yunnan’s state factories brought the [fermenting pile](shou:wet-piling) into production."},{"layer":"age","text":"At forty-six years these cakes sit far past the ten years after which the trade counts a ripe pu’er as [aged](shou:age-aged). The leaf goes on changing slowly with the air and moisture around it, so the way these cakes were kept has shaped them as much as the years have."}],"brewing":{"layer":"brewing","text":"From a cake, brick or tuo, ease a piece off along the edge with a pick rather than snapping it. Whole leaves give up their flavour steadily; broken ones release it all at once and cloud the cup. Ripe pu’er takes boiling water: fermented, tightly packed leaf needs full heat to open, and it does not scald the way green tea can. A common start is about 7 grams to 100 ml and one quick rinse, which wakes the leaf and carries off dust and any pile smell. Then short steeps that lengthen as the leaf opens, so the cup stays clear rather than heavy; it gives eight or more good cups."},"notice":{"layer":"notice","styleName":"aged ripe pu’er","text":"A smooth, deep cup with woody, date-like or medicinal notes, which the trade calls aged aroma."},"missing":[]},
  "2b41ad92-19e6-4d73-aba4-0fb0896c5728": {"productId":"2b41ad92-19e6-4d73-aba4-0fb0896c5728","paragraphs":[{"layer":"place","text":"This is loose [Liu Bao](liu-bao:definition) from Cangwu, the county of Wuzhou in eastern Guangxi where the style began. The tea takes its name from [Liubao town](cangwu:where-it-is), in the county's northern hills. Like every [dark tea](dark:definition), its leaf was piled after it was made, so that warmth, moisture and microbes would darken and soften it before it was packed away to age."},{"layer":"place","text":"It was made in 1990, a lean time for the county. Boats had once carried the tea down the Xijiang through Wuzhou to Guangzhou and on to Southeast Asia, along what the trade calls the [tea boat road](cangwu:tea-boat-road). That river trade had broken down in the war years, and by the early 1990s [very few gardens](cangwu:decline-and-return) in the county were still worked. Interest came back only in the 2000s, and Liu Bao became a protected origin in 2011."},{"layer":"age","text":"At thirty-six years it is far past the ten after which the trade counts a Liu Bao as [aged](liu-bao:age-aged). How it was stored matters as much as how long it has waited, and the trade does not agree whether a tea like this keeps improving for decades or peaks sooner."}],"brewing":{"layer":"brewing","text":"Liu Bao takes very hot or boiling water, because its leaf is dense and gives up its depth slowly. Rinse it once or twice and pour the rinse away. Use about 5 to 8 grams to 100 ml, start with steeps of five to fifteen seconds and add a few seconds each round; a good Liu Bao gives ten cups or more."},"notice":{"layer":"notice","styleName":"aged Liu Bao","text":"A deep red, thick cup with woody, herbal and betel nut notes; tea several decades old is often described with ginseng and camphor."},"missing":[]},
  "2c43aa09-e47e-4f14-8f0c-f6ef8f871683": {"productId":"2c43aa09-e47e-4f14-8f0c-f6ef8f871683","paragraphs":[{"layer":"place","text":"This is [Wuyi rock tea](yancha:definition), the oolong of the [Wuyi Mountains](wuyi-mountains:where-it-is) on the border of northern Fujian and Jiangxi, and only tea from that area may be sold under the name. The bushes grow among rock, on ledges and in the ravines, in [thin soil weathered from the cliffs](wuyi-mountains:nature) that drains fast while fog settles on the slopes through the year. The record names no zone or pit, so it does not say how close to the [scenic core](wuyi-mountains:zones) this leaf grew."},{"layer":"type","text":"Like any [oolong](oolong:definition), it is only partly oxidised. The leaf is twisted into long strips rather than rolled into balls, then finished with a [charcoal roast](yancha:making) given in several rounds, with rests of weeks or months between them. The roast dries the tea so it keeps, and the roaster matches its strength to the leaf in hand."}],"brewing":{"layer":"brewing","text":"Wuyi tea is usually brewed gongfu style with water at or near the boil, about 95 to 100°C, and about 5 to 8 grams of leaf in a 100 to 120 ml gaiwan, a third to a half full. A quick rinse, poured off at once, is common. Steeps start short, about 5 to 20 seconds, and grow a few seconds longer each round, and good rock tea gives seven steeps or more. In a larger pot, use about 2 to 5 grams for 250 to 350 ml and steep two to three minutes."},"notice":{"layer":"notice","styleName":"Wuyi rock tea","text":"Roast and stone fruit, a mineral, rocky texture and a long, sweet, mouth-watering finish. Light roast is bright and floral, medium roast fruity and rounded, full roast charcoal, wood and roasted nuts. Da Hong Pao is often floral, Rougui spicy with cinnamon, young Shui Xian sweet and smooth, and old-bush Shui Xian woody and mossy."},"missing":[]},
  "2d489d83-99ce-4a0d-ad45-ddb4bf0430e5": {"productId":"2d489d83-99ce-4a0d-ad45-ddb4bf0430e5","paragraphs":[{"layer":"lot","text":"A [Meizhan](yancha:meizhan) [oolong](oolong:definition) made in 2004, partly oxidised to a medium degree and finished with a [charcoal roast](yancha:making), the roast that dries the leaf so it keeps. Meizhan is a Fujian cultivar that came from Anxi and is also made in the Wuyi way, though it is less famous than Rougui and Shui Xian and is not one of the four famous bushes."},{"layer":"place","text":"The leaf comes from the [Wuyi Mountains](wuyi-mountains:where-it-is), on Fujian's border with Jiangxi. Here bushes grow slowly in thin, stony soil on ledges and in ravines, under heavy rain and frequent fog. The record names no [zone](wuyi-mountains:zones), so it does not say how close to the rocky core of the range this tea grew."},{"layer":"age","text":"Twenty-two years have passed since it was made. Roasted Wuyi tea is the kind [kept for years](yancha:ageing), and its keeping depends on staying sealed and dry, because damp is what turns stored leaf back toward going green, the main fault of age."}],"brewing":{"layer":"brewing","text":"Wuyi tea is usually brewed gongfu style with water at or near the boil, about 95 to 100°C, and about 5 to 8 grams of leaf in a 100 to 120 ml gaiwan, a third to a half full. A quick rinse, poured off at once, is common. Steeps start short, about 5 to 20 seconds, and grow a few seconds longer each round, and good rock tea gives seven steeps or more. In a larger pot, use about 2 to 5 grams for 250 to 350 ml and steep two to three minutes."},"notice":{"layer":"notice","styleName":"aged Wuyi rock tea","text":"A smoother, thicker liquor with less sharpness, the roast softened and the high aroma faded."},"missing":[]},
  "2e8d5029-03f7-4410-8481-8f2bb256ab86": {"productId":"2e8d5029-03f7-4410-8481-8f2bb256ab86","paragraphs":[{"layer":"type","text":"[Mi Lan Xiang](dancong:mi-lan-xiang) is one of the traditional ten types by which [Phoenix Dancong](dancong:definition) is sorted and sold, and one of the most widely made. Each type has its own name, and its character comes from the bush and the making, [not from anything added](dancong:aromas) to the leaf."},{"layer":"place","text":"The leaf comes from Phoenix Mountain in Chaozhou, eastern Guangdong. [Dancong](dancong:name) means single bush: the leaf of one bush made on its own, though a named line today is mostly grown from cuttings or grafts of a chosen bush. This lot was given a medium [roast](dancong:making), and the roast is one of the main ways one Dancong differs from another."}],"brewing":{"layer":"brewing","text":"Brew it gongfu style in a small gaiwan or clay pot, with about 3 to 8 grams for 100 to 120 ml and hot water, about 88 to 100°C; Chinese accounts mostly say 95 to 100°C. A quick rinse is common. Steeps start at a few seconds and grow a few seconds each round, and a good Dancong gives about eight to fifteen. Too long, too hot or too much leaf and it turns bitter and astringent."},"notice":{"layer":"notice","styleName":"Phoenix Dancong","text":"Flowers above all, a sweetness that comes back after swallowing, a high scent that lasts, honey, often ripe fruit such as peach, and what the trade calls mountain rhyme, shan yun; a liquor from golden to orange-red or amber."},"missing":[]},
  "2ec4bcf5-1773-453c-b710-5b859203cb4e": {"productId":"2ec4bcf5-1773-453c-b710-5b859203cb4e","paragraphs":[{"layer":"age","text":"A [Liu Bao](liu-bao:definition) from Guangxi, made in 1990 and sold as loose leaf. At thirty-six years it sits far past the decade after which the trade counts this tea as [aged](liu-bao:age-aged), and how it was stored has shaped it as much as the years have."},{"layer":"type","text":"Liu Bao is the [dark tea](dark:definition) of Cangwu County, near Wuzhou, named for the town of Liubao where it began. As with every post-fermented tea, the leaf is piled after it is made, so warmth, moisture and microbes slowly turn it darker before it is packed and left to age. It was made for a market far from home: Chinese miners and labourers in the [tin mines of Malaya](liu-bao:nanyang-trade) drank it, and it travelled by boat down the river to Wuzhou, on to Guangzhou, and out by sea."}],"brewing":{"layer":"brewing","text":"Liu Bao takes very hot or boiling water, because its leaf is dense and gives up its depth slowly. Rinse it once or twice and pour the rinse away. Use about 5 to 8 grams to 100 ml, start with steeps of five to fifteen seconds and add a few seconds each round; a good Liu Bao gives ten cups or more."},"notice":{"layer":"notice","styleName":"aged Liu Bao","text":"A deep red, thick cup with woody, herbal and betel nut notes; tea several decades old is often described with ginseng and camphor."},"missing":[]},
  "30efe43d-7748-452c-9fb7-c04452a09cf3": {"productId":"30efe43d-7748-452c-9fb7-c04452a09cf3","paragraphs":[{"layer":"lot","text":"A [Zhengshan Xiaozhong](lapsang:definition) made in 1934 in Tongmu village, in the Wuyi Mountains of Fujian. Tongmu is the place usually given as the [birthplace of red tea](lapsang:history), the fully oxidised tea that English calls [black](red:definition). This lot was made by the Tongmu method of the Republican years. It was smoked over pine, rolled by hand and dried over a wood fire. In that way of working the leaf lies on bamboo mats in a [qinglou](lapsang:smoke), a wooden drying house with the fire at the bottom, so the heat and smoke rise through it."},{"layer":"age","text":"At ninety-two years it stands outside any described practice. Lapsang has [no recognised tradition of long ageing](lapsang:ageing), and the trade names no category of decades-old red tea. What it does record is the first few years in good storage, when the pine smoke softens. This leaf has gone far beyond that, and it is a record of how the village made tea long before the trade of today."}],"brewing":{"layer":"brewing","text":"In a cup or pot, use about 3 grams for 240 ml, with water at 90 to 100°C, and steep about two to five minutes, usually around three. Gongfu style, use about 5 grams in a 100 to 110 ml gaiwan or pot, with short steeps that grow a little longer each round. Too hot or too long and the smoke turns harsh and bitter and covers the tea."},"notice":{"layer":"notice","styleName":"aged Lapsang Souchong","text":"The smoke softer and further back, with dried fruit coming forward."},"missing":[]},
  "31ef0ec4-1fbb-4417-8d03-b93fb3dade2d": {"productId":"31ef0ec4-1fbb-4417-8d03-b93fb3dade2d","paragraphs":[{"layer":"type","text":"A loose [ripe pu’er](shou:definition) from Yunnan, left unpressed after fermenting. Its leaf was wetted and heaped in a [damp pile](shou:wet-piling), where microbes make their own heat. The pile is covered to hold that heat in, turned about once a week to spread it and let air in, and kept below about 65°C, because hotter than that the leaf begins to char. After one to two months the leaf is dried."},{"layer":"type","text":"The pile does in weeks what raw pu’er takes years of keeping to do, so a ripe tea is ready to drink soon after it is made. Yunnan [learned the method](shou:piling-1973) in 1973, when a team of seven from the Kunming, Menghai and Xiaguan factories went to study it at the Guangzhou tea factory."}],"brewing":{"layer":"brewing","text":"Ripe pu’er takes boiling water: fermented, tightly packed leaf needs full heat to open, and it does not scald the way green tea can. A common start is about 7 grams to 100 ml and one quick rinse, which wakes the leaf and carries off dust and any pile smell. Then short steeps that lengthen as the leaf opens, so the cup stays clear rather than heavy; it gives eight or more good cups."},"notice":{"layer":"notice","styleName":"ripe pu’er","text":"A smooth, sweet cup with earthy or woody notes. A young ripe tea can carry a faint smell of the pile, which fades with airing or in the first steeps."},"missing":[]},
  "3530cfd4-b2d2-4381-bf7d-1492e418cac3": {"productId":"3530cfd4-b2d2-4381-bf7d-1492e418cac3","paragraphs":[{"layer":"place","text":"A rolled oolong from [Taiwan](taiwan:on-a-label). The label says only that the leaf grew on the island; it names no mountain or township. The island's tea, and the craft of making oolong, came across the strait with [settlers from Fujian](taiwan:history), and rolled oolong is still what its [tea trade](taiwan:known-for) is built on."},{"layer":"type","text":"What sets this tea apart is how the fresh leaf was treated. [GABA tea](gaba:definition) names a method, not a plant or a place. Before the usual making, the leaf is held for some hours [without oxygen](gaba:making), in a sealed chamber of nitrogen or a vacuum. In that state it turns its glutamic acid into GABA, an amino acid, and cannot break it down again, so the finished tea holds much more of it than ordinary leaf. After that it is withered, tossed, fixed, rolled and dried like any [oolong](oolong:definition). The method began in Japan, where the finding is dated to 1987, and [the island's tea research station](gaba:history) later adapted it to oolong, alternating spells without oxygen with spells in air. The island is now a main source of GABA tea sold abroad."}],"brewing":{"layer":"brewing","text":"In a cup or pot, steep it for about two to five minutes. It is forgiving of small changes in water temperature and steeping time. It can also be cold-brewed, steeped for some hours in the fridge."},"notice":{"layer":"notice","styleName":"gABA oolong","text":"Ripe, dried or stewed fruit such as apricot, honeyed sweetness, a smooth, round body, and little bitterness or astringency; often brown sugar or roasted grain, sometimes wood or spice, and a light fruity sourness."},"missing":[]},
  "353ab782-dec2-4d03-9a8a-95e63854277a": {"productId":"353ab782-dec2-4d03-9a8a-95e63854277a","paragraphs":[{"layer":"place","text":"This is [red tea](red:definition) from [Yuchi](yuchi:where-it-is), the township that holds Sun Moon Lake in the middle of Nantou County, made in 1979. Red tea took hold here because of the land: a warm, wet basin of mist and cloud, deep reddish soil, and a lake that keeps the weather mild and steady. The Japanese tea men who first trialled it compared it to the Assam country of India, and the [Assam type](yuchi:assam-planting) seed they brought in is still the root of the township's red tea."},{"layer":"place","text":"The year puts this tea in the township's lean decades. From the 1970s, rising wages made hand picked leaf costly against red tea from other countries, and many growers here moved to oolong or to other crops. The return to local red tea came only after the 1999 earthquake."},{"layer":"age","text":"Red tea has no tradition of [ageing](red:ageing). It is made to be drunk fresh, and sealed it is expected to keep for about three years at most. At forty-seven years, this leaf has lived far beyond the life the trade gives it."}],"brewing":{"layer":"brewing","text":"Red tea takes water near the boil, about 90 to 100°C; hotter water draws out its aroma and flavour more fully, but its bitterness faster too. In a pot or mug, use about a rounded spoon of leaf for each cup and steep three to five minutes, less for broken leaf and a little less, and a little cooler, for a light, delicate tea. Left too long, it turns bitter and drying, because time and heat pull more tannins from the leaf."},"notice":{"layer":"notice","styleName":"red tea","text":"A sweet cup, often with honey, floral or fruity notes, malt in many, and a brisk strength in the stronger teas. The liquor runs red, bright to deep."},"missing":[]},
  "35d3071e-570a-4a7c-a452-6b4568a62481": {"productId":"35d3071e-570a-4a7c-a452-6b4568a62481","paragraphs":[{"layer":"place","text":"This is a [dark tea](dark:definition) from [Anhua](anhua:where-it-is), a mountain county on the middle Zi river in north-central Hunan, at the northern foot of the Xuefeng mountains. Its slopes are deep, loose soil weathered from shale, much of the county is forest, and the tea grows among the trees rather than on cleared plains. The warm, wet air that grows the leaf is the same air it is piled and kept in, which is why the trade [ties the finished tea to the place](anhua:why-people-value-it) and not only to the method."},{"layer":"type","text":"Like every [Anhua dark tea](anhua-dark:definition), it starts as [heimaocha](anhua-dark:making), a raw tea of large local leaf that is fixed, rolled, piled, rolled again and dried over a pine fire. The piling leaves the leaf in warmth and moisture, where microbes and its own chemistry slowly darken it, so the change comes after the leaf is made."},{"layer":"age","text":"At two years this leaf is young. Anhua tea is [kept for years](anhua-dark:ageing) and said to improve, though no agreed count of years marks it as aged; it asks only to be kept clean, dry and aired, away from mould and other smells."}],"brewing":{"layer":"brewing","text":"In a small pot or gaiwan, use water at the boil and start with a steep of about 15 to 30 seconds, a little longer each round. Pressed and aged Anhua tea is also commonly simmered in a pot."},"notice":{"layer":"notice","styleName":"Anhua dark tea","text":"Pine smoke or pine resin above all, a sweet taste and aftertaste, and a mellow, thick, smooth cup; a liquor from yellow and orange to orange-red. Young tea is often smokier in the first infusions and a little bitter, sweetening as the infusions go on."},"missing":[]},
  "3603a079-0aa8-4acd-958f-307322b037e5": {"productId":"3603a079-0aa8-4acd-958f-307322b037e5","paragraphs":[{"layer":"lot","text":"These are pieces of [ripe pu’er](shou:definition) cakes from the 1980s, made from Yunnan leaf and broken over the years, now sold loose. The cakes date from the style’s first two decades: Yunnan’s state factories only brought the [wet-pile method](shou:wet-piling) into production in 1973, heaping damp leaf so its own warmth could ferment it in weeks."},{"layer":"age","text":"At forty-one years the tea sits well within what the trade counts as [aged ripe pu’er](shou:age-aged). The leaf keeps changing slowly with the air and moisture around it, so storage has shaped these pieces as much as time has."}],"brewing":{"layer":"brewing","text":"Ripe pu’er takes boiling water: fermented, tightly packed leaf needs full heat to open, and it does not scald the way green tea can. A common start is about 7 grams to 100 ml and one quick rinse, which wakes the leaf and carries off dust and any pile smell. Then short steeps that lengthen as the leaf opens, so the cup stays clear rather than heavy; it gives eight or more good cups."},"notice":{"layer":"notice","styleName":"aged ripe pu’er","text":"A smooth, deep cup with woody, date-like or medicinal notes, which the trade calls aged aroma."},"missing":[]},
  "38320d2d-fc42-4b78-a895-5cc156b6fd2e": {"productId":"38320d2d-fc42-4b78-a895-5cc156b6fd2e","paragraphs":[{"layer":"type","text":"Mercy is a [raw pu’er](sheng:identity) from Yunnan, sold loose. It began as leaf from the province’s large-leaf trees, withered, then fried in a wok to [kill the green](sheng:making), rolled and dried in the sun. That heat stops most of the leaf’s own enzymes but not all, and the activity that survives is why the tea keeps changing for years."},{"layer":"type","text":"Sheng can be left loose or steamed and pressed, and this one reaches the cup as [loose leaf](sheng:processing). Its village and year were not recorded, so its history is carried by [its time in storage](sheng:aging), which shapes how any raw pu’er evolves."}],"brewing":{"layer":"brewing","text":"Young raw pu’er takes water a little off the boil, about 85 to 95°C, because hotter water draws out more of its bitterness; an aged one takes 95°C to boiling. A common start is about 7 grams to 100 ml and a quick rinse of a few seconds, then a first steep of ten to fifteen seconds, adding a few seconds each round. A good raw tea gives eight to ten cups or more."},"notice":{"layer":"notice","styleName":"Sheng Pu’er","text":"In young raw pu’er, a bitter, drying bite that turns into a returning sweetness, a feel in the throat that makes the mouth water, and fresh, floral or fruity notes such as apricot or plum. Tea kept in humid storage can carry a damp, earthy storage taste."},"missing":[]},
  "3a49cede-89ad-45fd-8c7b-afe80c883e98": {"productId":"3a49cede-89ad-45fd-8c7b-afe80c883e98","paragraphs":[{"layer":"lot","text":"Purple buds from wild tea trees in Yunnan, made as [white tea](white:definition): the leaf is only withered and dried, never heated to stop its change and never rolled, so each bud keeps its natural shape and the white down that gives the style its name."},{"layer":"type","text":"This lot was air dried, which is the [Yunnan way](yunnan-white:making) of finishing white tea, without the low final bake that Fujian white usually gets. It is sold loose, as leaf rather than a pressed cake. White tea from Yunnan is [new to the market](yunnan-white:history), and its trade has grown only in recent years."}],"brewing":{"layer":"brewing","text":"Yunnan white is brewed gently, as a white tea is, in a gaiwan or small pot, and it gives many infusions; the leaf holds up well."},"notice":{"layer":"notice","styleName":"Yunnan white","text":"A honeyed, sweet cup, often richer and fuller than Fujian white, with little bitterness, sometimes fruit like apricot or melon and a hay or herbal note. Yabao is sweet and silky, often with pine or herbal notes."},"missing":[]},
  "3e29dc84-eb0d-4f18-bd71-702b18000b2a": {"productId":"3e29dc84-eb0d-4f18-bd71-702b18000b2a","paragraphs":[{"layer":"lot","text":"A [rougui](yancha:rougui) from the [Wuyi Mountains](wuyi-mountains:where-it-is), the range along the border of northern Fujian and Jiangxi. Rougui is a cultivar of these mountains that dates from the Qing dynasty. This leaf was finished with a heavy [charcoal roast](yancha:making), given in several rounds with weeks or months of rest between them. The roast dries the tea so it keeps, and a [full roast](yancha:roast-levels) keeps the longest. The heavier the roast, the longer a fresh tea is rested before it is drunk."},{"layer":"place","text":"[Rock tea](yancha:definition) grows among the cliffs, in crevices and on ledges, in thin soil weathered from the rock, with heavy rain and fog through the year. The trade sorts this ground into [true rock, half rock and river bank](wuyi-mountains:zones), by how rocky it is and how near it lies to the scenic core. This tea carries the mountain's name without naming a zone, so the label alone does not say how close to the core the leaf grew."}],"brewing":{"layer":"brewing","text":"Wuyi tea is usually brewed gongfu style with water at or near the boil, about 95 to 100°C, and about 5 to 8 grams of leaf in a 100 to 120 ml gaiwan, a third to a half full. A quick rinse, poured off at once, is common. Steeps start short, about 5 to 20 seconds, and grow a few seconds longer each round, and good rock tea gives seven steeps or more. In a larger pot, use about 2 to 5 grams for 250 to 350 ml and steep two to three minutes."},"notice":{"layer":"notice","styleName":"Wuyi rock tea","text":"Roast and stone fruit, a mineral, rocky texture and a long, sweet, mouth-watering finish. Light roast is bright and floral, medium roast fruity and rounded, full roast charcoal, wood and roasted nuts. Da Hong Pao is often floral, Rougui spicy with cinnamon, young Shui Xian sweet and smooth, and old-bush Shui Xian woody and mossy."},"missing":[]},
  "3ea36161-f438-4956-bc50-9d4dfab9f891": {"productId":"3ea36161-f438-4956-bc50-9d4dfab9f891","paragraphs":[{"layer":"age","text":"An [oolong](oolong:definition) from Taiwan, dated 1980 and kept as loose leaf for forty-six years. The island has its own tradition of keeping oolong, called [lao cha](taiwan-oolong:ageing), old tea. Leaf chosen for keeping is stored cool, dry, dark and sealed, and the keeper roasts it again at low heat from time to time to drive out the moisture it takes in. No standard says when an oolong becomes old. Those who give a figure put it between ten and thirty years, and this tea has passed both."},{"layer":"place","text":"The record names only [Taiwan](taiwan:on-a-label), not a mountain or township, so it tells you where the leaf grew and nothing about height, cultivar or style. [Taiwan oolong](taiwan-oolong:definition) began with settlers from Fujian, who brought the plants and the craft, and in the nineteenth century the island sold its oolong abroad as [Formosa Oolong](taiwan-oolong:history)."}],"brewing":{"layer":"brewing","text":"Ball-rolled Taiwan oolong takes hot water, about 90 to 100°C, a fairly generous amount of leaf and short steeps; the balls open slowly and give many infusions. Roasted Dong Ding takes water from about 95°C to a full boil. Aged oolong takes very hot water, in a pot that holds its heat, clay above all. Oriental Beauty is the exception and takes cooler water, about 80 to 95°C."},"notice":{"layer":"notice","styleName":"aged Taiwan oolong","text":"A smooth, mellow, thick cup with little astringency, often plum or prune, sometimes something like medicinal herbs or ginseng, and an amber to red-brown liquor."},"missing":[]},
  "41046786-aa37-4b8e-b390-005e6495da52": {"productId":"41046786-aa37-4b8e-b390-005e6495da52","paragraphs":[{"layer":"place","text":"This [red tea](red:definition) comes from [Yuchi](yuchi:where-it-is), the township that holds Sun Moon Lake in the middle of Nantou County. Red tea took root here under Japanese rule. Large leaf [Assam](yuchi:assam-planting) seed brought from India did well in the township's trial plantings, because the warm, wet and misty basin, with its deep reddish soil, [reminded the trade of Assam country](yuchi:why-red-tea)."},{"layer":"place","text":"The leaf was made in 1981, when the township's red tea was [fading as an export crop](yuchi:decline-and-return). From the 1970s, rising wages made hand picked leaf expensive next to red tea from other countries, and many growers moved to oolong or to other crops. The revival came only after the 1999 earthquake, so this tea comes from the lean years before it."},{"layer":"age","text":"Red tea has [no tradition of ageing](red:ageing). It is made to drink within a few years of sealing, and this one is now forty-five years past its making, far beyond the life the style plans for."}],"brewing":{"layer":"brewing","text":"Red tea takes water near the boil, about 90 to 100°C; hotter water draws out its aroma and flavour more fully, but its bitterness faster too. In a pot or mug, use about a rounded spoon of leaf for each cup and steep three to five minutes, less for broken leaf and a little less, and a little cooler, for a light, delicate tea. Left too long, it turns bitter and drying, because time and heat pull more tannins from the leaf."},"notice":{"layer":"notice","styleName":"red tea","text":"A sweet cup, often with honey, floral or fruity notes, malt in many, and a brisk strength in the stronger teas. The liquor runs red, bright to deep."},"missing":[]},
  "4328920f-b526-457e-94e0-35409523cd00": {"productId":"4328920f-b526-457e-94e0-35409523cd00","paragraphs":[{"layer":"place","text":"[Jingmai](jingmai:where) is a tea mountain in Huimin Town, in Lancang Lahu Autonomous County of Pu’er City. In 2023 its old tea forests and villages were listed together as a UNESCO World Heritage cultural landscape. The tea there grows as [forest tea](jingmai:forest-tea): tall trees with little pruning, shaded by the woods around them. The mountain’s name is carried by both its raw and its ripe pu’er."},{"layer":"type","text":"This leaf from 2009 was made into [ripe pu’er](shou:definition) and kept loose rather than pressed. In the [wet pile](shou:wet-piling) the warmth comes from the microbes themselves. So the heap is covered to hold that warmth in and turned about once a week to spread it and let air in. It is kept below about 65°C, because any hotter and the leaf begins to char."},{"layer":"age","text":"At seventeen years it now sits among what the trade counts as [aged ripe pu’er](shou:age-aged). The leaf goes on changing slowly with the air and moisture around it, which is why storage shapes it as much as the years do."}],"brewing":{"layer":"brewing","text":"Ripe pu’er takes boiling water: fermented, tightly packed leaf needs full heat to open, and it does not scald the way green tea can. A common start is about 7 grams to 100 ml and one quick rinse, which wakes the leaf and carries off dust and any pile smell. Then short steeps that lengthen as the leaf opens, so the cup stays clear rather than heavy; it gives eight or more good cups."},"notice":{"layer":"notice","styleName":"aged ripe pu’er","text":"A smooth, deep cup with woody, date-like or medicinal notes, which the trade calls aged aroma."},"missing":[]},
  "43cb35e0-b34f-4b06-8607-a525989e08cc": {"productId":"43cb35e0-b34f-4b06-8607-a525989e08cc","paragraphs":[{"layer":"lot","text":"Tea Masters Cake is a cake of [ripe pu’er](shou:definition) made from Yunnan leaf. Before it was pressed, the leaf went through [wet piling](shou:wet-piling). It was wetted and heaped, then covered to hold in the heat its own microbes give off. Every week or so it was turned to spread that heat and let air in. The pile stays below about 65°C, because any hotter and the leaf starts to char."},{"layer":"type","text":"The pile does in weeks what raw pu’er takes years of keeping to do, so a cake like this is ready to drink soon after it is made. Yunnan took up the method in 1973. That year a team from the Kunming, Menghai and Xiaguan factories went to [Guangzhou to learn its piling](shou:piling-1973), and by 1975 Menghai's way of doing it had become the ripe pu’er made today."}],"brewing":{"layer":"brewing","text":"From a cake, brick or tuo, ease a piece off along the edge with a pick rather than snapping it. Whole leaves give up their flavour steadily; broken ones release it all at once and cloud the cup. Ripe pu’er takes boiling water: fermented, tightly packed leaf needs full heat to open, and it does not scald the way green tea can. A common start is about 7 grams to 100 ml and one quick rinse, which wakes the leaf and carries off dust and any pile smell. Then short steeps that lengthen as the leaf opens, so the cup stays clear rather than heavy; it gives eight or more good cups."},"notice":{"layer":"notice","styleName":"ripe pu’er","text":"A smooth, sweet cup with earthy or woody notes. A young ripe tea can carry a faint smell of the pile, which fades with airing or in the first steeps."},"missing":[]},
  "445d985e-16d7-41ec-be74-10438950b424": {"productId":"445d985e-16d7-41ec-be74-10438950b424","paragraphs":[{"layer":"type","text":"A loose [raw pu’er](sheng:identity) from Yunnan. Raw is the undarkened branch of pu’er, the one never given shou’s fast fermentation. Its leaf comes from the province’s large leaf tea trees. It is withered, then fried in a wok to [kill the green](sheng:making), rolled, and dried in the sun. The heat stops most of the leaf’s own enzymes but not all. Because the leaf is never hot air dried afterwards, the activity that survives is what lets the tea keep changing for years. This one was never pressed. It is sold loose, as the rough tea called [maocha](sheng:processing)."},{"layer":"type","text":"Without a fermenting pile, raw pu’er [changes gradually in storage](sheng:aging), so the conditions it has been kept in become part of its history. Heat and humidity set the pace, because the change comes partly from slow oxidation and partly from microbes. [Warm, humid stores](sheng:storage) move it quickly. Cool, dry ones move it slowly, and a store that is too dry can leave it stalled and green."}],"brewing":{"layer":"brewing","text":"Young raw pu’er takes water a little off the boil, about 85 to 95°C, because hotter water draws out more of its bitterness; an aged one takes 95°C to boiling. A common start is about 7 grams to 100 ml and a quick rinse of a few seconds, then a first steep of ten to fifteen seconds, adding a few seconds each round. A good raw tea gives eight to ten cups or more."},"notice":{"layer":"notice","styleName":"Sheng Pu’er","text":"In young raw pu’er, a bitter, drying bite that turns into a returning sweetness, a feel in the throat that makes the mouth water, and fresh, floral or fruity notes such as apricot or plum. Tea kept in humid storage can carry a damp, earthy storage taste."},"missing":[]},
  "44832b7a-c7a5-4573-848a-3a8b031f5406": {"productId":"44832b7a-c7a5-4573-848a-3a8b031f5406","paragraphs":[{"layer":"lot","text":"A green tea made in Japan in 1930, ninety-six years ago. The record names the country but not the prefecture where the leaf was grown."},{"layer":"age","text":"Green tea is meant to be drunk within about a year of picking, or kept sealed for a year or two. No tradition of [ageing green tea](green:ageing) is recorded, and it does not mature the way pu’er or white tea can. A green tea this old was not made to last this long, so its keeping shaped it more than its making did, and how it was kept is not on record."},{"layer":"type","text":"As a [green tea](green:definition), the leaf was heated soon after picking so that it never oxidised. In Japan that heat has usually come from [steam](green:styles) rather than a pan."}],"brewing":{"layer":"brewing","text":"Green tea takes water well below the boil, about 80°C, a little cooler for the youngest leaf and a little warmer for older, larger leaf. Boiling water draws out bitterness and dries the cup. A common start is about 2 grams of leaf to 100 ml, in a glass or a small gaiwan, with short steeps of half a minute to two minutes, and the same leaf can be brewed a few times."},"notice":{"layer":"notice","styleName":"green tea","text":"A fresh, clean cup that many call crisp, with a sweet, soft finish, and a pale green to yellow-green liquor. The smell runs from fresh leaf to flowers, and steamed teas lean grassy or seaweed-like. Too much heat or too long a steep turns the cup bitter and drying."},"missing":[]},
  "477098ab-4de2-40b6-be44-9b33cc72d0ee": {"productId":"477098ab-4de2-40b6-be44-9b33cc72d0ee","paragraphs":[{"layer":"grade","text":"A cake of ripe pu’er from Yunnan leaf, made in 1998 and sold under the [Zhong Cha mark](zhong-cha-pai:definition), the brand of the China National Tea Corporation. The mark names who sold the tea, not how fine the leaf is. From the late 1980s the larger factories moved to their own names and newer, smaller makers took up the label, so on a cake from this decade the year of making says more than the wrapper does."},{"layer":"age","text":"Leaf for [ripe pu’er](shou:definition) is heaped warm and damp in a [fermenting pile](shou:wet-piling) before it is pressed. Yunnan’s factories brought that method into production in 1973, which puts 1998 in the style’s third decade. At twenty-eight years this cake is well past the ten years the trade counts as [aged ripe pu’er](shou:age-aged). The leaf keeps changing slowly with the air and moisture around it, so storage has shaped it as much as the years have."}],"brewing":{"layer":"brewing","text":"From a cake, brick or tuo, ease a piece off along the edge with a pick rather than snapping it. Whole leaves give up their flavour steadily; broken ones release it all at once and cloud the cup. Ripe pu’er takes boiling water: fermented, tightly packed leaf needs full heat to open, and it does not scald the way green tea can. A common start is about 7 grams to 100 ml and one quick rinse, which wakes the leaf and carries off dust and any pile smell. Then short steeps that lengthen as the leaf opens, so the cup stays clear rather than heavy; it gives eight or more good cups."},"notice":{"layer":"notice","styleName":"aged ripe pu’er","text":"A smooth, deep cup with woody, date-like or medicinal notes, which the trade calls aged aroma."},"missing":[]},
  "47e229d2-4a48-4f42-88bc-a31f20be85ae": {"productId":"47e229d2-4a48-4f42-88bc-a31f20be85ae","paragraphs":[{"layer":"place","text":"[Beipu](beipu:where-it-is) is a Hakka township in the south-west of Hsinchu County, in low hill country between the central mountains and the coastal plain, well below the high-mountain oolong gardens. Tea here is a [Hakka trade](hsinchu:hakka): local families grow the leaf, make it and sell it, and on many farms the craft has passed down through generations. The township is counted among the core places for [Oriental Beauty](beipu:known-for), but a label that names Beipu [names a township](beipu:in-hsinchu), not a style."},{"layer":"age","text":"This [oolong](oolong:definition), a partly oxidised tea that sits between green and red, was made in 1970. Taiwan has a long habit of keeping oolong for years as [lao cha](taiwan-oolong:ageing), old tea. Keepers roast it again at low heat from time to time to drive out the moisture it takes in. No standard says when an oolong becomes old, and those who give a figure put it between ten and thirty years. At fifty-six years, this tea is well beyond either figure."}],"brewing":{"layer":"brewing","text":"Ball-rolled Taiwan oolong takes hot water, about 90 to 100°C, a fairly generous amount of leaf and short steeps; the balls open slowly and give many infusions. Roasted Dong Ding takes water from about 95°C to a full boil. Aged oolong takes very hot water, in a pot that holds its heat, clay above all. Oriental Beauty is the exception and takes cooler water, about 80 to 95°C."},"notice":{"layer":"notice","styleName":"aged Taiwan oolong","text":"A smooth, mellow, thick cup with little astringency, often plum or prune, sometimes something like medicinal herbs or ginseng, and an amber to red-brown liquor."},"missing":[]},
  "497f48ae-7ba0-4dc0-a051-36823ba40a9d": {"productId":"497f48ae-7ba0-4dc0-a051-36823ba40a9d","paragraphs":[{"layer":"place","text":"Anhua is a mountain county in north-central Hunan, on the middle stretch of the [Zi river](anhua:where-it-is) at the northern foot of the Xuefeng mountains. Rice is hard to grow on its hills and steep valleys, but tea does well there. Tea has been recorded here since the Tang. Under the Ming and Qing the county's leaf went by road and river to the north-west and on to Russia, through merchant towns such as [Tangjiaguan](anhua:history). The trade ties the finished tea to this place as well as to its method, because the same warm, wet air that helps the leaf grow is the air it is [piled and aged in](anhua:why-people-value-it)."},{"layer":"type","text":"This is a loose [Anhua dark tea](anhua-dark:definition), a protected origin name tied to a defined place of making. Like every tea of the county it begins as [heimaocha](anhua-dark:making), a raw tea of large local leaf that is fixed, rolled, piled, rolled again and dried. Dark tea is leaf that is left to change in warmth and moisture after it has been heated and rolled, so the trade calls it [post-fermented](dark:definition)."},{"layer":"age","text":"From 2022, it is now four years old. Anhua tea is kept for years and is [said to improve](anhua-dark:ageing), though no agreed number of years makes it aged. What matters is that it stays clean, dry and aired, away from mould and other smells."}],"brewing":{"layer":"brewing","text":"In a small pot or gaiwan, use water at the boil and start with a steep of about 15 to 30 seconds, a little longer each round. Pressed and aged Anhua tea is also commonly simmered in a pot."},"notice":{"layer":"notice","styleName":"Anhua dark tea","text":"Pine smoke or pine resin above all, a sweet taste and aftertaste, and a mellow, thick, smooth cup; a liquor from yellow and orange to orange-red. Young tea is often smokier in the first infusions and a little bitter, sweetening as the infusions go on."},"missing":[]},
  "4a1ad382-61ed-41da-91dc-57f86e29bf25": {"productId":"4a1ad382-61ed-41da-91dc-57f86e29bf25","paragraphs":[{"layer":"type","text":"Elephant Village is a cake of [raw pu’er](sheng:identity) from Yunnan, made in 2010. It began as [maocha](sheng:making): large-leaf tea fried in a wok, rolled, then dried in the sun rather than by hot air, which leaves enough of the leaf’s own activity alive for the tea to keep changing for years. That leaf was then [pressed into a cake](sheng:pressing), the compact shape that first let pu’er travel the old trade routes on pack animals."},{"layer":"age","text":"At sixteen years it is past the ten that some in the trade count as [aged](sheng:ageing), and short of the twenty or more that many others wait for. How far a cake has come depends on how it was pressed and where it was kept, since [heat and humidity](sheng:storage) set the pace of that slow change."}],"brewing":{"layer":"brewing","text":"Pry the leaf off a cake or brick in chunks with a pick or knife, from the surface and toward the centre, rather than crumbling it. A mix of larger pieces and smaller ones brews evenly. Young raw pu’er takes water a little off the boil, about 85 to 95°C, because hotter water draws out more of its bitterness; an aged one takes 95°C to boiling. A common start is about 7 grams to 100 ml and a quick rinse of a few seconds, then a first steep of ten to fifteen seconds, adding a few seconds each round. A good raw tea gives eight to ten cups or more."},"notice":{"layer":"notice","styleName":"aged Sheng Pu’er","text":"A smoother, thicker, sweeter cup with woody, herbal and camphor notes and something of dried dates or dark fruit."},"missing":[]},
  "4b25399d-e6a7-437e-a7ee-034017ea1614": {"productId":"4b25399d-e6a7-437e-a7ee-034017ea1614","paragraphs":[{"layer":"type","text":"A loose leaf [Liu Bao](liu-bao:definition) from Guangxi, made in the 1990s. The style is named for the town of Liubao in [Cangwu](guangxi:wuzhou-and-cangwu), a county under the city of Wuzhou. Like every [dark tea](dark:definition), its leaf is heaped after it is made, so that warmth, moisture and microbes can darken and soften it before it is packed away to age. It was made for a market far from home: the trade believed it eased the heat and damp of the work done by [Chinese miners in Malaya](liu-bao:nanyang-trade), and it went by boat down the river to Wuzhou and out by sea."},{"layer":"age","text":"At thirty-one years, this tea is well past the ten years after which the trade counts a Liu Bao as [aged](liu-bao:age-aged). How it was stored matters as much as how long it has been kept. The trade links the slow change of these teas to [warm, wet country](guangxi:land-and-climate) and cool storehouses, where the microbes that shape a dark tea do well."}],"brewing":{"layer":"brewing","text":"Liu Bao takes very hot or boiling water, because its leaf is dense and gives up its depth slowly. Rinse it once or twice and pour the rinse away. Use about 5 to 8 grams to 100 ml, start with steeps of five to fifteen seconds and add a few seconds each round; a good Liu Bao gives ten cups or more."},"notice":{"layer":"notice","styleName":"aged Liu Bao","text":"A deep red, thick cup with woody, herbal and betel nut notes; tea several decades old is often described with ginseng and camphor."},"missing":[]},
  "4c952d51-c94d-4a8d-8638-394e24330a8c": {"productId":"4c952d51-c94d-4a8d-8638-394e24330a8c","paragraphs":[{"layer":"type","text":"Universe is a loose [oolong](oolong:definition) from China, the partly oxidised tea that stands between green tea and red tea, also called qing cha, blue-green tea. Its region, cultivar and year are not recorded, so where this leaf sits within that wide range is not known."},{"layer":"type","text":"Every oolong is made in the same order, and each step has a reason. The leaf is withered until it is soft enough to handle without breaking, then [tossed in rounds](oolong:making) with rests between them: the knocking bruises its edges, which begin to oxidise, and the rests let the change spread slowly inward. High heat stops it at the point the maker chooses, and the leaf is rolled and dried."}],"brewing":{"layer":"brewing","text":"Oolong is most often brewed gongfu style, in a small gaiwan or clay pot with plenty of leaf and short steeps, and it stands many rounds. A common start is about 4 to 6 grams to 100 ml, with a first steep of roughly 5 to 15 seconds and 5 to 10 seconds more each round. Light, green-style oolong takes water a little off the boil, about 90 to 95°C; heavily oxidised, roasted and aged oolong takes water at a full boil. Many people pour a quick first rinse to wake tightly rolled leaf. In a larger pot, use less leaf and steep for a few minutes."},"notice":{"layer":"notice","styleName":"oolong","text":"In light, green-style oolong: floral and orchid notes, a creamy or buttery feel and a sweet aftertaste that lingers. In roasted and darker oolong: toasted grain and caramel, wood, stone fruit and a mineral, rock-like character."},"missing":[]},
  "4d01f123-ef1a-4607-a270-551b8e5b8d1c": {"productId":"4d01f123-ef1a-4607-a270-551b8e5b8d1c","paragraphs":[{"layer":"place","text":"The leaf for this cake comes from [Banzhang](banzhang:where-it-is), a group of tea villages on Bulang Mountain in the south of Menghai County, Xishuangbanna. Lao Banzhang is the old village. [Xin Banzhang](banzhang:old-and-new) grew out of it when people moved away, and the two sell at very different prices. On a label, Banzhang is a [market name](banzhang:on-a-label), and it rarely says which village, or the wider area, is meant."},{"layer":"type","text":"It was made into [ripe pu’er](shou:definition) in 2012. The leaf was wetted and heaped in a [damp pile](shou:wet-piling), covered to hold in the heat its own microbes make, and turned about once a week to spread that heat and let air in. Then it was dried and pressed, so it was ready to drink soon after it was made instead of after years of waiting."},{"layer":"age","text":"At fourteen years it is past the ten years the trade counts as [aged ripe pu’er](shou:age-aged). The leaf is still changing slowly with the air and moisture around it, which is why storage matters as much as the years."}],"brewing":{"layer":"brewing","text":"From a cake, brick or tuo, ease a piece off along the edge with a pick rather than snapping it. Whole leaves give up their flavour steadily; broken ones release it all at once and cloud the cup. Ripe pu’er takes boiling water: fermented, tightly packed leaf needs full heat to open, and it does not scald the way green tea can. A common start is about 7 grams to 100 ml and one quick rinse, which wakes the leaf and carries off dust and any pile smell. Then short steeps that lengthen as the leaf opens, so the cup stays clear rather than heavy; it gives eight or more good cups."},"notice":{"layer":"notice","styleName":"aged ripe pu’er","text":"A smooth, deep cup with woody, date-like or medicinal notes, which the trade calls aged aroma."},"missing":[]},
  "4d22b1d2-184f-43a0-b39d-0c65fb74e616": {"productId":"4d22b1d2-184f-43a0-b39d-0c65fb74e616","paragraphs":[{"layer":"place","text":"A cake of [raw pu’er](sheng:identity) from 2006, made from leaf grown in [Menghai](menghai-county:county-and-factory) County, Yunnan. Raw pu’er is never given the fast fermentation of the ripe style. The leaf was [fried to kill the green](sheng:making) and then dried in the sun. That heat stops most of the leaf’s own enzymes but not all of them, and the activity that survives is what lets the tea keep changing after it is pressed."},{"layer":"age","text":"At twenty years it has reached the age that many in the trade wait for before they call a raw pu’er [aged](sheng:ageing), though some count from ten. How far any cake has come depends on how it was pressed and [stored](sheng:storage), so the years it has spent in storage are part of its history."}],"brewing":{"layer":"brewing","text":"Pry the leaf off a cake or brick in chunks with a pick or knife, from the surface and toward the centre, rather than crumbling it. A mix of larger pieces and smaller ones brews evenly. Young raw pu’er takes water a little off the boil, about 85 to 95°C, because hotter water draws out more of its bitterness; an aged one takes 95°C to boiling. A common start is about 7 grams to 100 ml and a quick rinse of a few seconds, then a first steep of ten to fifteen seconds, adding a few seconds each round. A good raw tea gives eight to ten cups or more."},"notice":{"layer":"notice","styleName":"aged Sheng Pu’er","text":"A smoother, thicker, sweeter cup with woody, herbal and camphor notes and something of dried dates or dark fruit."},"missing":[]},
  "4f910dce-bd4c-4a7c-b030-d391ee2f6707": {"productId":"4f910dce-bd4c-4a7c-b030-d391ee2f6707","paragraphs":[{"layer":"named","text":"Xiaguan is one of the oldest names in Yunnan tea. Merchants first pressed the tuo, a compressed cake shaped like a nest, under that name in 1902. The craft carried on through the Kangzang Tea Factory, founded in 1941, and then the Yunnan Xiaguan Tea Factory, which grew into the largest maker of compressed tea in the province. The name comes from the town of Xiaguan in Dali, in western Yunnan, which was a place for trading and pressing tea rather than growing it. This brick of [ripe pu’er](shou:definition) was pressed under the Xiaguan brand in the 1990s."},{"layer":"type","text":"The factory had its own part in how ripe pu’er came to be. In 1958 a [steam method](shou:piling-history) at Xiaguan cut fermentation to about fifteen days. In 1973 Xiaguan joined Kunming and Menghai in a [team of seven](shou:piling-1973) sent to the Guangzhou tea factory to learn [wet piling](shou:wet-piling), the warm, damp heap that gives in weeks what raw leaf reaches only after years of keeping. Each factory then worked out its own way of piling."},{"layer":"age","text":"Made in the 1990s, this brick counts as [aged ripe pu’er](shou:age-aged). The leaf keeps changing slowly with the air and moisture around it, which is why storage shapes it as much as the years do."}],"brewing":{"layer":"brewing","text":"From a cake, brick or tuo, ease a piece off along the edge with a pick rather than snapping it. Whole leaves give up their flavour steadily; broken ones release it all at once and cloud the cup. Ripe pu’er takes boiling water: fermented, tightly packed leaf needs full heat to open, and it does not scald the way green tea can. A common start is about 7 grams to 100 ml and one quick rinse, which wakes the leaf and carries off dust and any pile smell. Then short steeps that lengthen as the leaf opens, so the cup stays clear rather than heavy; it gives eight or more good cups."},"notice":{"layer":"notice","styleName":"aged ripe pu’er","text":"A smooth, deep cup with woody, date-like or medicinal notes, which the trade calls aged aroma."},"missing":[]},
  "50614512-db4d-43f9-96ca-aaab08ed4880": {"productId":"50614512-db4d-43f9-96ca-aaab08ed4880","paragraphs":[{"layer":"place","text":"This oolong comes from [Beipu](beipu:where-it-is), a township in the south-west of Hsinchu County. It sits in low hill country between the central mountains and the coastal plain, well below the high-mountain gardens. Tea in the county is largely a [Hakka](hsinchu:hakka) trade: local families grow the leaf, make it and sell it, and many farms have passed from one generation to the next. Beipu's name is tied to [Oriental Beauty](beipu:known-for), but on a label the name says where a tea was grown. It does not say which style the tea is."},{"layer":"age","text":"The leaf was made in 1977. At forty-nine years it belongs to Taiwan's tradition of [lao cha, old tea](taiwan-oolong:ageing). In that tradition, oolong is kept cool, dry, dark and sealed for years. From time to time it is roasted again at low heat to drive out the moisture it takes in. No standard says when an oolong becomes old. Those who give a figure put it somewhere between ten and thirty years, and this tea is well past both."}],"brewing":{"layer":"brewing","text":"Ball-rolled Taiwan oolong takes hot water, about 90 to 100°C, a fairly generous amount of leaf and short steeps; the balls open slowly and give many infusions. Roasted Dong Ding takes water from about 95°C to a full boil. Aged oolong takes very hot water, in a pot that holds its heat, clay above all. Oriental Beauty is the exception and takes cooler water, about 80 to 95°C."},"notice":{"layer":"notice","styleName":"aged Taiwan oolong","text":"A smooth, mellow, thick cup with little astringency, often plum or prune, sometimes something like medicinal herbs or ginseng, and an amber to red-brown liquor."},"missing":[]},
  "531c1d45-6246-4388-8574-7ce3558da644": {"productId":"531c1d45-6246-4388-8574-7ce3558da644","paragraphs":[{"layer":"place","text":"This loose tea comes from [Anhua](anhua:where-it-is), a county of hills and steep valleys on the middle Zi river in north-central Hunan, at the northern foot of the Xuefeng mountains, where rice is hard to grow and tea does well. The same warm, wet air that grows the leaf is the air it is piled and aged in, which is why the trade ties [the character of Anhua tea](anhua:why-people-value-it) to the place as much as to the method."},{"layer":"type","text":"Like all [dark tea](dark:definition), it is left to change in warmth and moisture after the leaf is made, as microbes and the leaf's own chemistry slowly darken it. In Anhua every tea begins as one raw tea, [heimaocha](anhua-dark:making), from large local leaf that is fixed, rolled, piled, rolled again and dried, then steamed soft before it is shaped."},{"layer":"age","text":"Made in 2023, it is three years old. Anhua tea is [kept for years](anhua-dark:ageing) and said to improve, though no agreed count of years marks it as aged. It wants a clean, dry, aired place, away from mould and other smells."}],"brewing":{"layer":"brewing","text":"In a small pot or gaiwan, use water at the boil and start with a steep of about 15 to 30 seconds, a little longer each round. Pressed and aged Anhua tea is also commonly simmered in a pot."},"notice":{"layer":"notice","styleName":"Anhua dark tea","text":"Pine smoke or pine resin above all, a sweet taste and aftertaste, and a mellow, thick, smooth cup; a liquor from yellow and orange to orange-red. Young tea is often smokier in the first infusions and a little bitter, sweetening as the infusions go on."},"missing":[]},
  "532abc51-f39c-4ca4-a313-1ed3fd434e0e": {"productId":"532abc51-f39c-4ca4-a313-1ed3fd434e0e","paragraphs":[{"layer":"lot","text":"A loose [Yunnan white](yunnan-white:definition) from 2018, picked from wild bush trees that grow in mixed forest rather than in managed gardens. Those trees give larger leaves, so this leaf was withered a little longer before drying. Nothing more was done to it: as with all [white tea](white:definition), the leaf was never heated to stop its change and never rolled."},{"layer":"age","text":"It is eight years old. Yunnan white is [kept like Fujian white](yunnan-white:ageing), and some keep it for years, but there is no agreed view of how long it should age or how it compares with aged Fujian white. Some drinkers prefer it within its first few years."}],"brewing":{"layer":"brewing","text":"Yunnan white is brewed gently, as a white tea is, in a gaiwan or small pot, and it gives many infusions; the leaf holds up well."},"notice":{"layer":"notice","styleName":"Yunnan white","text":"A honeyed, sweet cup, often richer and fuller than Fujian white, with little bitterness, sometimes fruit like apricot or melon and a hay or herbal note. Yabao is sweet and silky, often with pine or herbal notes."},"missing":[]},
  "54f03b67-0e56-4cd2-b478-16f2465f1c80": {"productId":"54f03b67-0e56-4cd2-b478-16f2465f1c80","paragraphs":[{"layer":"place","text":"This leaf comes from [Banzhang](banzhang:where-it-is), a group of tea villages on Bulang Mountain in the south of Menghai County, Xishuangbanna. The name covers more than one settlement: [Lao Banzhang and Xin Banzhang](banzhang:old-and-new), the old village and the one that grew out of it. [A Banzhang label](banzhang:on-a-label) rarely says which of the two is meant."},{"layer":"type","text":"It was made into [ripe pu’er](shou:definition) in 2003 and left loose rather than pressed. The leaf was heaped warm and damp in a [fermenting pile](shou:wet-piling) so that it could be drunk soon after making, thirty years after Yunnan’s state factories brought the method into production in 1973."},{"layer":"age","text":"At twenty-three years the tea has passed into what the trade counts as [aged ripe pu’er](shou:age-aged). The leaf goes on changing slowly with the air and moisture around it, which is why storage shapes it as much as the years do."}],"brewing":{"layer":"brewing","text":"Ripe pu’er takes boiling water: fermented, tightly packed leaf needs full heat to open, and it does not scald the way green tea can. A common start is about 7 grams to 100 ml and one quick rinse, which wakes the leaf and carries off dust and any pile smell. Then short steeps that lengthen as the leaf opens, so the cup stays clear rather than heavy; it gives eight or more good cups."},"notice":{"layer":"notice","styleName":"aged ripe pu’er","text":"A smooth, deep cup with woody, date-like or medicinal notes, which the trade calls aged aroma."},"missing":[]},
  "54f88d83-44c6-4cef-b23e-ed59d36cec62": {"productId":"54f88d83-44c6-4cef-b23e-ed59d36cec62","paragraphs":[{"layer":"type","text":"Loose [ripe pu’er](shou:definition) from Yunnan, made in 2012. The style is made by [wet piling](shou:wet-piling): the leaf is heaped damp and covered to hold the heat its microbes give off, then turned about once a week to spread it and let air in, and finally dried. This leaf was left loose rather than pressed. It was made thirty-nine years after Yunnan’s state factories brought the pile into production in 1973."},{"layer":"age","text":"At fourteen years it is past the ten that put a ripe pu’er among the [aged](shou:age-aged) teas. The leaf keeps changing slowly with the air and moisture around it, so how it has been kept matters as much as the years."}],"brewing":{"layer":"brewing","text":"Ripe pu’er takes boiling water: fermented, tightly packed leaf needs full heat to open, and it does not scald the way green tea can. A common start is about 7 grams to 100 ml and one quick rinse, which wakes the leaf and carries off dust and any pile smell. Then short steeps that lengthen as the leaf opens, so the cup stays clear rather than heavy; it gives eight or more good cups."},"notice":{"layer":"notice","styleName":"aged ripe pu’er","text":"A smooth, deep cup with woody, date-like or medicinal notes, which the trade calls aged aroma."},"missing":[]},
  "55606539-3eef-4b33-a52b-df3c87e38523": {"productId":"55606539-3eef-4b33-a52b-df3c87e38523","paragraphs":[{"layer":"age","text":"A loose leaf [green tea](green:definition) from China, dated 1990. Green tea is meant to be drunk within a year or two of picking, and no tradition of [keeping it for age](green:ageing) is recorded, so a leaf thirty-six years old is outside what the type was made for. With a green tea this old, the type itself promises nothing. What counts is how it was kept."},{"layer":"type","text":"Like every green tea, the leaf was [fixed](green:making) by heat soon after picking. The heat stops the leaf's own enzymes before they can turn it brown. The leaf was then rolled to give it shape and dried until little water was left, so it would keep."}],"brewing":{"layer":"brewing","text":"Green tea takes water well below the boil, about 80°C, a little cooler for the youngest leaf and a little warmer for older, larger leaf. Boiling water draws out bitterness and dries the cup. A common start is about 2 grams of leaf to 100 ml, in a glass or a small gaiwan, with short steeps of half a minute to two minutes, and the same leaf can be brewed a few times."},"notice":{"layer":"notice","styleName":"green tea","text":"A fresh, clean cup that many call crisp, with a sweet, soft finish, and a pale green to yellow-green liquor. The smell runs from fresh leaf to flowers, and steamed teas lean grassy or seaweed-like. Too much heat or too long a steep turns the cup bitter and drying."},"missing":[]},
  "59b97f02-2518-4e1c-82b8-155762bcc03a": {"productId":"59b97f02-2518-4e1c-82b8-155762bcc03a","paragraphs":[{"layer":"lot","text":"An iron cake of [raw pu’er](sheng:identity) from 2001, made from sun-dried Yunnan [maocha](sheng:making) and pressed by a [hydraulic press](sheng:pressing) into a dense cake. Its leaf is lighter in color than that of its darker counterpart, the 2000 Dark Green Tie Bing. A cake pressed this tight changes slowly, so the years work on it gradually."},{"layer":"age","text":"At twenty-five years it has passed both lines the trade draws for [aged raw pu’er](sheng:ageing), ten years for some and twenty for many. Because the change happens slowly in storage, how a cake was kept is part of its [history](sheng:aging)."}],"brewing":{"layer":"brewing","text":"Pry the leaf off a cake or brick in chunks with a pick or knife, from the surface and toward the centre, rather than crumbling it. A mix of larger pieces and smaller ones brews evenly. Young raw pu’er takes water a little off the boil, about 85 to 95°C, because hotter water draws out more of its bitterness; an aged one takes 95°C to boiling. A common start is about 7 grams to 100 ml and a quick rinse of a few seconds, then a first steep of ten to fifteen seconds, adding a few seconds each round. A good raw tea gives eight to ten cups or more."},"notice":{"layer":"notice","styleName":"aged Sheng Pu’er","text":"A smoother, thicker, sweeter cup with woody, herbal and camphor notes and something of dried dates or dark fruit."},"missing":[]},
  "5a356849-7aa1-469e-b36e-07806d92c9ef": {"productId":"5a356849-7aa1-469e-b36e-07806d92c9ef","paragraphs":[{"layer":"lot","text":"7572 is a [ripe pu’er](shou:definition) recipe of the Menghai Tea Factory, and its number says what it is: a 1975 formula, grade 7 leaf, factory number 2. This cake was [wet piled](shou:wet-piling) and pressed in 1999, twenty-four years after [Menghai’s own piling method](shou:piling-1973) settled into the ripe pu’er made today. It arrived without its original paper wrapper."},{"layer":"age","text":"At twenty-seven years it sits well inside what the trade counts as [aged ripe pu’er](shou:age-aged). The leaf is still changing slowly with the air and moisture around it, so where it has been kept matters as much as how long."}],"brewing":{"layer":"brewing","text":"From a cake, brick or tuo, ease a piece off along the edge with a pick rather than snapping it. Whole leaves give up their flavour steadily; broken ones release it all at once and cloud the cup. Ripe pu’er takes boiling water: fermented, tightly packed leaf needs full heat to open, and it does not scald the way green tea can. A common start is about 7 grams to 100 ml and one quick rinse, which wakes the leaf and carries off dust and any pile smell. Then short steeps that lengthen as the leaf opens, so the cup stays clear rather than heavy; it gives eight or more good cups."},"notice":{"layer":"notice","styleName":"aged ripe pu’er","text":"A smooth, deep cup with woody, date-like or medicinal notes, which the trade calls aged aroma."},"missing":[]},
  "5abd5736-76bc-4522-a3aa-6ff863888aa2": {"productId":"5abd5736-76bc-4522-a3aa-6ff863888aa2","paragraphs":[{"layer":"type","text":"A cake of [ripe pu’er](shou:definition) made in Yunnan in 1980, seven years after the province’s state factories brought the [wet-pile method](shou:wet-piling) into production. A team from Kunming, Menghai and Xiaguan had studied piling in Guangzhou in 1973, Kunming got it to work with cold water the following year, and by 1975 [Menghai’s way of piling](shou:piling-1973) had settled into the ripe pu’er still made today. That places this cake in the style’s first decade."},{"layer":"age","text":"At forty-six years it is far past the ten that mark [aged ripe pu’er](shou:age-aged) in the trade. The leaf goes on changing slowly with the air and moisture around it, so the way a tea this old was kept matters as much as how long it has been kept."}],"brewing":{"layer":"brewing","text":"From a cake, brick or tuo, ease a piece off along the edge with a pick rather than snapping it. Whole leaves give up their flavour steadily; broken ones release it all at once and cloud the cup. Ripe pu’er takes boiling water: fermented, tightly packed leaf needs full heat to open, and it does not scald the way green tea can. A common start is about 7 grams to 100 ml and one quick rinse, which wakes the leaf and carries off dust and any pile smell. Then short steeps that lengthen as the leaf opens, so the cup stays clear rather than heavy; it gives eight or more good cups."},"notice":{"layer":"notice","styleName":"aged ripe pu’er","text":"A smooth, deep cup with woody, date-like or medicinal notes, which the trade calls aged aroma."},"missing":[]},
  "5d24a7a0-f93f-4d94-8709-1b6cc804b498": {"productId":"5d24a7a0-f93f-4d94-8709-1b6cc804b498","paragraphs":[{"layer":"lot","text":"Xiao Qing Gan is [ripe pu’er](shou:definition) from Yunnan, packed into small green mandarins from Xinhui district in Jiangmen, Guangdong. Each mandarin is picked young, before it ripens. It is then hollowed out, filled with the tea and dried together with it."},{"layer":"type","text":"The leaf inside was made the ripe way. It was wetted and heaped in a [damp pile](shou:wet-piling), where microbes give off heat. The pile was covered to hold that heat in and turned about once a week to spread it and let air in, then dried after one to two months. The pile was developed to bring about, in weeks, the change that drinkers in Hong Kong and Guangdong knew from raw pu’er aged for years. That is why ripe pu’er is ready to drink soon after it is made."}],"brewing":{"layer":"brewing","text":"Ripe pu’er takes boiling water: fermented, tightly packed leaf needs full heat to open, and it does not scald the way green tea can. A common start is about 7 grams to 100 ml and one quick rinse, which wakes the leaf and carries off dust and any pile smell. Then short steeps that lengthen as the leaf opens, so the cup stays clear rather than heavy; it gives eight or more good cups."},"notice":{"layer":"notice","styleName":"ripe pu’er","text":"A smooth, sweet cup with earthy or woody notes. A young ripe tea can carry a faint smell of the pile, which fades with airing or in the first steeps."},"missing":[]},
  "5e306193-0f9b-465a-955b-4c2388e391c9": {"productId":"5e306193-0f9b-465a-955b-4c2388e391c9","paragraphs":[{"layer":"lot","text":"A loose [red tea](red:definition) from Yunnan, finished in the sun. Its last drying was done in sunlight rather than over heat, which makes it a [sun-dried red](dian-hong:old-tree-and-sun-dried). That is a choice of process, not a separate kind of tea."},{"layer":"type","text":"Up to that final step the leaf was [made as every red tea is](dian-hong:making): withered, rolled to break its cells, then left to oxidise fully until it turned from green to reddish brown. Yunnan's own red, [Dian Hong](dian-hong:definition), began with a trial batch Feng Shaoqiu made in Shunning, now Fengqing, in late 1938. The trade still does not agree whether a red dried in the sun belongs under that name."}],"brewing":{"layer":"brewing","text":"Dian Hong takes hot water, roughly 90 to 100°C. A common start is about 5 grams to 100 ml, with short steeps that lengthen slowly as the leaf opens."},"notice":{"layer":"notice","styleName":"Dian Hong","text":"A full, sweet cup, often described as malty, with chocolate or cocoa and honey notes and sometimes something floral. The liquor runs golden to bright red, and a good grade has little bitterness."},"missing":[]},
  "5fbed1f7-1e83-4068-b53d-b9c807e83431": {"productId":"5fbed1f7-1e83-4068-b53d-b9c807e83431","paragraphs":[{"layer":"lot","text":"A [raw pu’er](sheng:identity) iron cake from 2000. Its leaf is Yunnan [maocha](sheng:making), dried in the sun and then [pressed hydraulically](sheng:pressing) until the cake is packed hard. Pressing began so tea would travel well on pack animals along the old trade routes. It also sets how fast a tea ages: a cake this tight changes slowly, and a looser one changes faster."},{"layer":"age","text":"At twenty-six years it is past both the ten years some count as [aged](sheng:ageing) raw pu’er and the twenty or more that many wait for. In a cake this dense the change is gradual, and [storage](sheng:storage) matters, because heat and humidity decide how quickly oxidation and microbes do their work."}],"brewing":{"layer":"brewing","text":"Pry the leaf off a cake or brick in chunks with a pick or knife, from the surface and toward the centre, rather than crumbling it. A mix of larger pieces and smaller ones brews evenly. Young raw pu’er takes water a little off the boil, about 85 to 95°C, because hotter water draws out more of its bitterness; an aged one takes 95°C to boiling. A common start is about 7 grams to 100 ml and a quick rinse of a few seconds, then a first steep of ten to fifteen seconds, adding a few seconds each round. A good raw tea gives eight to ten cups or more."},"notice":{"layer":"notice","styleName":"aged Sheng Pu’er","text":"A smoother, thicker, sweeter cup with woody, herbal and camphor notes and something of dried dates or dark fruit."},"missing":[]},
  "63b9c29c-917c-4c25-8cdf-6668c774163f": {"productId":"63b9c29c-917c-4c25-8cdf-6668c774163f","paragraphs":[{"layer":"type","text":"New Rainbow is a [raw pu’er](sheng:identity) from Yunnan, kept as loose leaf rather than pressed. It begins as leaf from the province’s large-leaf trees, picked and withered, then fried in a wok to [kill the green](sheng:making) and dried in the sun. The leaf is never hot-air dried, and that is the point: some of its own activity survives the wok, which is what lets the tea go on changing. What comes out is [maocha](sheng:processing), the rough tea that is either sold loose, as this one is, or pressed."},{"layer":"type","text":"Sheng is given none of the rapid fermentation that makes shou, so it changes slowly, over years, as it is [stored](sheng:aging). How and where a tea is kept becomes part of its history, though good storage does not promise a good tea."}],"brewing":{"layer":"brewing","text":"Young raw pu’er takes water a little off the boil, about 85 to 95°C, because hotter water draws out more of its bitterness; an aged one takes 95°C to boiling. A common start is about 7 grams to 100 ml and a quick rinse of a few seconds, then a first steep of ten to fifteen seconds, adding a few seconds each round. A good raw tea gives eight to ten cups or more."},"notice":{"layer":"notice","styleName":"Sheng Pu’er","text":"In young raw pu’er, a bitter, drying bite that turns into a returning sweetness, a feel in the throat that makes the mouth water, and fresh, floral or fruity notes such as apricot or plum. Tea kept in humid storage can carry a damp, earthy storage taste."},"missing":[]},
  "64709233-374b-4d69-a7c8-61fc9e49b78e": {"productId":"64709233-374b-4d69-a7c8-61fc9e49b78e","paragraphs":[{"layer":"lot","text":"A cake of [ripe pu’er](shou:definition) from Yunnan, made in 1990."},{"layer":"age","text":"It was made seventeen years after Yunnan’s state factories brought [wet piling](shou:wet-piling) into production, which places it in the style’s second decade. In wet piling, leaf is heaped damp so its own heat and microbes can change it. At thirty-six years the cake counts as [aged ripe pu’er](shou:age-aged). The leaf still changes slowly with the air and moisture around it, so the way it was stored has shaped it as much as its age."}],"brewing":{"layer":"brewing","text":"From a cake, brick or tuo, ease a piece off along the edge with a pick rather than snapping it. Whole leaves give up their flavour steadily; broken ones release it all at once and cloud the cup. Ripe pu’er takes boiling water: fermented, tightly packed leaf needs full heat to open, and it does not scald the way green tea can. A common start is about 7 grams to 100 ml and one quick rinse, which wakes the leaf and carries off dust and any pile smell. Then short steeps that lengthen as the leaf opens, so the cup stays clear rather than heavy; it gives eight or more good cups."},"notice":{"layer":"notice","styleName":"aged ripe pu’er","text":"A smooth, deep cup with woody, date-like or medicinal notes, which the trade calls aged aroma."},"missing":[]},
  "65c7d8cb-7823-43f0-9d86-9fa5822e5c58": {"productId":"65c7d8cb-7823-43f0-9d86-9fa5822e5c58","paragraphs":[{"layer":"lot","text":"An iron cake of [raw pu’er](sheng:identity) from Yunnan, made in 1990 and pressed hard under a [hydraulic press](sheng:pressing). Its Blue Seal Green Label designation comes from the era of state production, when pu’er was made in [state factories](sheng:history) to standard recipes and sold under the state tea company’s labels."},{"layer":"age","text":"Pressing decides how a tea ages, and a cake this tight changes slowly. At thirty-six years it is past both the ten years some count as [aged raw pu’er](sheng:ageing) and the twenty or more that many wait for. The [slow change of storage](sheng:aging) is part of this cake’s own history."}],"brewing":{"layer":"brewing","text":"Pry the leaf off a cake or brick in chunks with a pick or knife, from the surface and toward the centre, rather than crumbling it. A mix of larger pieces and smaller ones brews evenly. Young raw pu’er takes water a little off the boil, about 85 to 95°C, because hotter water draws out more of its bitterness; an aged one takes 95°C to boiling. A common start is about 7 grams to 100 ml and a quick rinse of a few seconds, then a first steep of ten to fifteen seconds, adding a few seconds each round. A good raw tea gives eight to ten cups or more."},"notice":{"layer":"notice","styleName":"aged Sheng Pu’er","text":"A smoother, thicker, sweeter cup with woody, herbal and camphor notes and something of dried dates or dark fruit."},"missing":[]},
  "65f1e532-4c89-4519-9aa0-5ab5c14fbcbd": {"productId":"65f1e532-4c89-4519-9aa0-5ab5c14fbcbd","paragraphs":[{"layer":"place","text":"This [red tea](red:definition) was grown in Taiwan, the island off the coast of Fujian whose tea came across the strait with settlers. The label names [only the island](taiwan:on-a-label), with no mountain or township within it. Taiwan is known above all for oolong, but it [turned to red tea under Japanese rule](taiwan:history), and its first red tea was made at Yuchi, near Sun Moon Lake."},{"layer":"age","text":"The leaf was made in 2023, so it is now three years old. [Red tea has no tradition of ageing](red:ageing). It is meant to be drunk fresh, and kept sealed it holds for about a year and a half to three years, so this tea is at the far end of that span."},{"layer":"type","text":"English calls it black tea after the dark dry leaf, and Chinese calls it red after the colour of the cup. It is the fully oxidised tea. The fresh leaf is [withered](red:making) until it is soft enough to work, then rolled to break its cells, so that its juices and enzymes meet. It is left in warm, damp air until it turns from green to reddish brown, a step the Chinese trade calls fermentation. Hot air then dries it, which stops the change and keeps the tea stable."}],"brewing":{"layer":"brewing","text":"Red tea takes water near the boil, about 90 to 100°C; hotter water draws out its aroma and flavour more fully, but its bitterness faster too. In a pot or mug, use about a rounded spoon of leaf for each cup and steep three to five minutes, less for broken leaf and a little less, and a little cooler, for a light, delicate tea. Left too long, it turns bitter and drying, because time and heat pull more tannins from the leaf."},"notice":{"layer":"notice","styleName":"red tea","text":"A sweet cup, often with honey, floral or fruity notes, malt in many, and a brisk strength in the stronger teas. The liquor runs red, bright to deep."},"missing":[]},
  "66fba2fb-e53e-4600-8963-e277516d0261": {"productId":"66fba2fb-e53e-4600-8963-e277516d0261","paragraphs":[{"layer":"place","text":"This leaf comes from [Banzhang](banzhang:where-it-is), a group of tea villages on Bulang Mountain in the south of Menghai County, Xishuangbanna. The name covers more than one settlement. Lao Banzhang is the old village, and [Xin Banzhang](banzhang:old-and-new) was founded by people who moved out of it. The old village's tea sells for far more."},{"layer":"age","text":"It is [raw pu’er](sheng:identity) from 1980, kept loose rather than pressed. Raw pu’er begins as [maocha](sheng:making), the sun-dried rough tea, and is never put through shou’s fast fermentation, so it changes slowly in [storage](sheng:aging), and the store it was kept in is part of its history. After forty-six years it is well past the ten or twenty years the trade counts as [aged](sheng:ageing)."}],"brewing":{"layer":"brewing","text":"Young raw pu’er takes water a little off the boil, about 85 to 95°C, because hotter water draws out more of its bitterness; an aged one takes 95°C to boiling. A common start is about 7 grams to 100 ml and a quick rinse of a few seconds, then a first steep of ten to fifteen seconds, adding a few seconds each round. A good raw tea gives eight to ten cups or more."},"notice":{"layer":"notice","styleName":"aged Sheng Pu’er","text":"A smoother, thicker, sweeter cup with woody, herbal and camphor notes and something of dried dates or dark fruit."},"missing":[]},
  "6876236c-bcc5-49d8-b918-5c5db02ca2a5": {"productId":"6876236c-bcc5-49d8-b918-5c5db02ca2a5","paragraphs":[{"layer":"lot","text":"Loose [ripe pu’er](shou:definition) from Yunnan, made in the 1990s and stored in Guangzhou. It was never pressed into a cake or brick, so air moves freely through the leaf and it ages along a more even path."},{"layer":"age","text":"The leaf was fermented in a covered [wet pile](shou:wet-piling), a method Yunnan’s state factories brought into production in 1973 to give in weeks what raw pu’er took years to reach. At thirty-one years it is well past the decade that marks [aged ripe pu’er](shou:age-aged), and it keeps changing slowly with the air and moisture around it, which is why storage counts as much as the years."}],"brewing":{"layer":"brewing","text":"Ripe pu’er takes boiling water: fermented, tightly packed leaf needs full heat to open, and it does not scald the way green tea can. A common start is about 7 grams to 100 ml and one quick rinse, which wakes the leaf and carries off dust and any pile smell. Then short steeps that lengthen as the leaf opens, so the cup stays clear rather than heavy; it gives eight or more good cups."},"notice":{"layer":"notice","styleName":"aged ripe pu’er","text":"A smooth, deep cup with woody, date-like or medicinal notes, which the trade calls aged aroma."},"missing":[]},
  "696f9f29-b0e4-4920-abcc-5348ca20eec2": {"productId":"696f9f29-b0e4-4920-abcc-5348ca20eec2","paragraphs":[{"layer":"place","text":"This leaf comes from Anhua, a mountain county on the Zi river in north central Hunan, widely named as the main home of [Anhua dark tea](anhua-dark:definition) and a starting point of the old tea routes to the northwest. Like every tea made there, it began as [heimaocha](anhua-dark:making), a raw tea of large local leaf, traditionally dried over a pine fire, then steamed soft before pressing."},{"layer":"type","text":"Bailiang, a hundred liang, is one of the county's [flower rolls](anhua-dark:family), tall columns named by their old weight and sitting between the thousand and the ten. A roll is packed into a woven bamboo basket lined with leaf and [pressed tight by treading and twisting](anhua-dark:rolls) with long bars, then left to dry slowly in sun and night air for weeks. The rolls grew out of the border trade under the [Qing](anhua-dark:history)."},{"layer":"age","text":"Made in 2006, it has now had twenty years. Tea from the area is [kept for years](anhua-dark:ageing) in the belief that it improves, though no agreed count of years marks it as aged; what matters is that it stays clean, dry and aired, away from mould and other smells."}],"brewing":{"layer":"brewing","text":"From a brick, cake or basket, ease the leaf off along the edge or from the top with a pick rather than snapping it. Whole pieces give up their flavour steadily; crumbs release it all at once and cloud the cup. In a small pot or gaiwan, use water at the boil and start with a steep of about 15 to 30 seconds, a little longer each round. Pressed and aged Anhua tea is also commonly simmered in a pot."},"notice":{"layer":"notice","styleName":"aged Anhua dark tea","text":"A redder liquor, a sweeter, mellower cup, and sometimes a medicinal or herbal note."},"missing":[]},
  "69ec73c7-88b8-4ebb-a2e0-8a0c06fb33d5": {"productId":"69ec73c7-88b8-4ebb-a2e0-8a0c06fb33d5","paragraphs":[{"layer":"place","text":"This leaf comes from [Yiwu](greater-yiwu:where-it-is), in the north of Mengla County in Xishuangbanna, on the east side of the Lancang River. It is one of the old Six Famous Tea Mountains, and the town has long been where tea from the surrounding villages is gathered and processed. The name covers the town, the mountain and a wider area, so on a label it places the leaf in the region rather than in one village or plot; it is, in the trade's sense, [a market name](greater-yiwu:on-a-label)."},{"layer":"type","text":"The leaf was made into [ripe pu’er](shou:definition). It was wetted and heaped in a [damp pile](shou:wet-piling), where the microbes' own heat works on it. The pile is covered to hold that heat in, turned about once a week to let air through, and kept below about 65°C so the leaf does not char. After one to two months the leaf is dried. The method was developed to give in weeks what raw pu’er reached only after years of keeping, so this tea is ready to drink now rather than after a long wait."}],"brewing":{"layer":"brewing","text":"Ripe pu’er takes boiling water: fermented, tightly packed leaf needs full heat to open, and it does not scald the way green tea can. A common start is about 7 grams to 100 ml and one quick rinse, which wakes the leaf and carries off dust and any pile smell. Then short steeps that lengthen as the leaf opens, so the cup stays clear rather than heavy; it gives eight or more good cups."},"notice":{"layer":"notice","styleName":"ripe pu’er","text":"A smooth, sweet cup with earthy or woody notes. A young ripe tea can carry a faint smell of the pile, which fades with airing or in the first steeps."},"missing":[]},
  "6a3661dd-b5fe-40b5-932b-bf4ad0e65e13": {"productId":"6a3661dd-b5fe-40b5-932b-bf4ad0e65e13","paragraphs":[{"layer":"place","text":"A loose [red tea](red:definition) from [Yuchi](yuchi:where-it-is), the township that holds Sun Moon Lake in the middle of Nantou County. Red tea took root here under Japanese rule, when the colonial government wanted it for export and brought in [large leaf Assam seed](yuchi:assam-planting) from India. Of the trial sites, Yuchi was the one that did well, because its [warm, misty basin](yuchi:why-red-tea), deep reddish soil and steady lake weather were likened to the Assam country itself."},{"layer":"age","text":"This leaf dates from 1980, when that export trade was [fading](yuchi:decline-and-return): from the 1970s rising wages made hand picked leaf costly against red tea from other countries, and many growers moved to oolong or to other crops. The style has [no tradition of ageing](red:ageing). Sealed, it is expected to keep its quality for a year and a half to three years, so at forty-six years this tea sits far outside the life the trade gives it."}],"brewing":{"layer":"brewing","text":"Red tea takes water near the boil, about 90 to 100°C; hotter water draws out its aroma and flavour more fully, but its bitterness faster too. In a pot or mug, use about a rounded spoon of leaf for each cup and steep three to five minutes, less for broken leaf and a little less, and a little cooler, for a light, delicate tea. Left too long, it turns bitter and drying, because time and heat pull more tannins from the leaf."},"notice":{"layer":"notice","styleName":"red tea","text":"A sweet cup, often with honey, floral or fruity notes, malt in many, and a brisk strength in the stronger teas. The liquor runs red, bright to deep."},"missing":[]},
  "6a512a71-2013-4be6-bcf4-102628a5cea5": {"productId":"6a512a71-2013-4be6-bcf4-102628a5cea5","paragraphs":[{"layer":"type","text":"A loose [raw pu’er](sheng:identity) from Yunnan, made in the 1980s. Raw pu’er is never given the fast fermentation that makes shou. Instead it [changes slowly in storage](sheng:aging), so the years this leaf has kept, and the places it was kept, are part of what it has become."},{"layer":"age","text":"The trade does not agree on [when raw pu’er counts as aged](sheng:ageing). Some say ten years, and many wait for twenty or more. Made in the 1980s, this leaf is past both marks. It comes from the decade when [collectors of aged raw pu’er](sheng:history-modern), led at first by Taiwan, began looking for teas like it."}],"brewing":{"layer":"brewing","text":"Young raw pu’er takes water a little off the boil, about 85 to 95°C, because hotter water draws out more of its bitterness; an aged one takes 95°C to boiling. A common start is about 7 grams to 100 ml and a quick rinse of a few seconds, then a first steep of ten to fifteen seconds, adding a few seconds each round. A good raw tea gives eight to ten cups or more."},"notice":{"layer":"notice","styleName":"aged Sheng Pu’er","text":"A smoother, thicker, sweeter cup with woody, herbal and camphor notes and something of dried dates or dark fruit."},"missing":[]},
  "6aabdadd-361f-4f32-9c75-ef1ee0b06a9f": {"productId":"6aabdadd-361f-4f32-9c75-ef1ee0b06a9f","paragraphs":[{"layer":"place","text":"This leaf comes from [Bulang Mountain](bulang-mountain:where-it-is), the wide tea area in the south of Menghai County that runs along Yunnan’s border with Myanmar. On a label the mountain is [a broad market name](bulang-mountain:on-a-label): it points to a mountain style rather than to one of its many villages."},{"layer":"type","text":"These are [tea heads](tea-heads:definition), the dense clumps that knot together while [ripe pu’er](shou:definition) ferments, sorted out after piling and sold apart from the numbered grades of loose leaf. They form in the [wet pile](shou:wet-piling), where dampened leaf is heaped so that microbes warm it from within, turned about once a week to let air in, and held below about 65°C so the leaf does not char. This lot is kept loose."},{"layer":"age","text":"Made in 2018, the tea is now eight years old. That puts it in the stretch of about five to ten years in which [the smell of the pile](shou:age-settling) usually airs away."}],"brewing":{"layer":"brewing","text":"Ripe pu’er takes boiling water: fermented, tightly packed leaf needs full heat to open, and it does not scald the way green tea can. A common start is about 7 grams to 100 ml and one quick rinse, which wakes the leaf and carries off dust and any pile smell. Then short steeps that lengthen as the leaf opens, so the cup stays clear rather than heavy; it gives eight or more good cups."},"notice":{"layer":"notice","styleName":"ripe pu’er","text":"A smooth, sweet cup with earthy or woody notes. A young ripe tea can carry a faint smell of the pile, which fades with airing or in the first steeps."},"missing":[]},
  "6eb095a9-aab2-477d-ad64-53ad9af18332": {"productId":"6eb095a9-aab2-477d-ad64-53ad9af18332","paragraphs":[{"layer":"place","text":"This tuo of [ripe pu’er](shou:definition) is made from leaf grown in Menghai County, Yunnan. On a label, Menghai can mean the county or [Menghai Tea Factory](menghai-county:county-and-factory), which stands inside it and blends leaf from several of its mountains. Here the name says where the leaf grew, and no single mountain is given."},{"layer":"type","text":"Before it was pressed, the leaf was wetted and heaped in a [wet pile](shou:wet-piling). The pile is covered to hold the heat its microbes make and turned about once a week to let air in. The method was built to give in weeks the change raw pu’er takes years of keeping to reach, so a ripe tuo is ready to drink soon after it is made. The county runs through that history: in 1973 its factory joined Kunming and Xiaguan in sending a team to learn piling in Guangzhou, and by 1975 [the Menghai method](shou:piling-1973) had settled into the ripe pu’er made today."}],"brewing":{"layer":"brewing","text":"From a cake, brick or tuo, ease a piece off along the edge with a pick rather than snapping it. Whole leaves give up their flavour steadily; broken ones release it all at once and cloud the cup. Ripe pu’er takes boiling water: fermented, tightly packed leaf needs full heat to open, and it does not scald the way green tea can. A common start is about 7 grams to 100 ml and one quick rinse, which wakes the leaf and carries off dust and any pile smell. Then short steeps that lengthen as the leaf opens, so the cup stays clear rather than heavy; it gives eight or more good cups."},"notice":{"layer":"notice","styleName":"ripe pu’er","text":"A smooth, sweet cup with earthy or woody notes. A young ripe tea can carry a faint smell of the pile, which fades with airing or in the first steeps."},"missing":[]},
  "6ebd0fc4-4787-4fd5-b0d5-900916dcbc00": {"productId":"6ebd0fc4-4787-4fd5-b0d5-900916dcbc00","paragraphs":[{"layer":"place","text":"A loose leaf [dark tea](dark:definition) from Guangxi, made in 1970 and sold as Liu Bao. Guangxi on a label [names a region, not a style](guangxi:on-a-label), though a dark tea from the province is most often this one: [Liu Bao](liu-bao:definition), named for the town of Liubao where it began. Like every dark tea, its leaf was piled after it was made so that warmth, moisture and microbes would darken it, then packed and left to age."},{"layer":"age","text":"At fifty-six years it sits far past the ten that the trade counts as [aged](liu-bao:age-aged), and how it was stored matters as much as how long. Liu Bao this old is [mostly stock](liu-bao:old-stock) that sat in Malaysia or Hong Kong after the mining trade ended. Because such tea is hard to date, the trade reads its age from the basket, the labels and the papers packed with it."}],"brewing":{"layer":"brewing","text":"Liu Bao takes very hot or boiling water, because its leaf is dense and gives up its depth slowly. Rinse it once or twice and pour the rinse away. Use about 5 to 8 grams to 100 ml, start with steeps of five to fifteen seconds and add a few seconds each round; a good Liu Bao gives ten cups or more."},"notice":{"layer":"notice","styleName":"aged Liu Bao","text":"A deep red, thick cup with woody, herbal and betel nut notes; tea several decades old is often described with ginseng and camphor."},"missing":[]},
  "70dfae59-11cb-4cc0-a1f5-357f0bd96fdf": {"productId":"70dfae59-11cb-4cc0-a1f5-357f0bd96fdf","paragraphs":[{"layer":"lot","text":"Loose [ripe pu’er](shou:definition) made in Yunnan in 1990. It was left loose, unpressed. That places it in the style’s second decade, since the [wet-pile method](shou:wet-piling) reached production in Yunnan’s state factories in 1973."},{"layer":"age","text":"At thirty-six years it counts as [aged ripe pu’er](shou:age-aged). The leaf goes on changing with the air and moisture around it. How it was kept has shaped it as much as its age has."}],"brewing":{"layer":"brewing","text":"Ripe pu’er takes boiling water: fermented, tightly packed leaf needs full heat to open, and it does not scald the way green tea can. A common start is about 7 grams to 100 ml and one quick rinse, which wakes the leaf and carries off dust and any pile smell. Then short steeps that lengthen as the leaf opens, so the cup stays clear rather than heavy; it gives eight or more good cups."},"notice":{"layer":"notice","styleName":"aged ripe pu’er","text":"A smooth, deep cup with woody, date-like or medicinal notes, which the trade calls aged aroma."},"missing":[]},
  "721bd8f9-a211-4830-8f10-cdd855e639ce": {"productId":"721bd8f9-a211-4830-8f10-cdd855e639ce","paragraphs":[{"layer":"lot","text":"A [raw pu’er](sheng:identity) from the 1980s, kept as loose leaf rather than pressed into a cake, and set aside for decades in [humid storage](sheng:storage). Warm, damp stores move a raw tea along faster than dry ones, which is why the years have done so much to this lot."},{"layer":"age","text":"It began as [maocha](sheng:making), the rough tea of Yunnan’s large-leaf trees: wok-fried to kill the green and dried in the sun, but never hot-air dried, so the enzymes that survived could keep the leaf changing over time. Made in the 1980s, it is well past the point where the trade starts to call raw pu’er [aged](sheng:ageing). Some count from ten years, and many wait for twenty or more."}],"brewing":{"layer":"brewing","text":"Young raw pu’er takes water a little off the boil, about 85 to 95°C, because hotter water draws out more of its bitterness; an aged one takes 95°C to boiling. A common start is about 7 grams to 100 ml and a quick rinse of a few seconds, then a first steep of ten to fifteen seconds, adding a few seconds each round. A good raw tea gives eight to ten cups or more."},"notice":{"layer":"notice","styleName":"aged Sheng Pu’er","text":"A smoother, thicker, sweeter cup with woody, herbal and camphor notes and something of dried dates or dark fruit."},"missing":[]},
  "72c291c4-9840-42da-8331-ec8a08c65b65": {"productId":"72c291c4-9840-42da-8331-ec8a08c65b65","paragraphs":[{"layer":"lot","text":"A cake of [raw pu’er](sheng:identity) from Yunnan, made in 2007 from purple-bud leaf. The leaf was fried in a wok, rolled and [dried in the sun](sheng:making) as maocha. Because it was never hot-air dried, some of its own activity survived, and that is what lets the tea keep changing after it was pressed into a cake."},{"layer":"age","text":"At nineteen years it sits right at the threshold the trade argues over: some call a raw pu’er [aged](sheng:ageing) at ten years, and many wait for twenty. How far it has travelled depends on its [storage](sheng:storage), since heat and humidity set the pace, and on its [pressing](sheng:pressing), because a tight cake changes more slowly than a loose one."}],"brewing":{"layer":"brewing","text":"Pry the leaf off a cake or brick in chunks with a pick or knife, from the surface and toward the centre, rather than crumbling it. A mix of larger pieces and smaller ones brews evenly. Young raw pu’er takes water a little off the boil, about 85 to 95°C, because hotter water draws out more of its bitterness; an aged one takes 95°C to boiling. A common start is about 7 grams to 100 ml and a quick rinse of a few seconds, then a first steep of ten to fifteen seconds, adding a few seconds each round. A good raw tea gives eight to ten cups or more."},"notice":{"layer":"notice","styleName":"aged Sheng Pu’er","text":"A smoother, thicker, sweeter cup with woody, herbal and camphor notes and something of dried dates or dark fruit."},"missing":[]},
  "7400ece7-a8ed-4328-b462-ac18178b9dfa": {"productId":"7400ece7-a8ed-4328-b462-ac18178b9dfa","paragraphs":[{"layer":"lot","text":"A loose [Liu Bao](liu-bao:definition) made in 1990 from leaf grown in Cangwu County, which came to us through the Guangzhou tea trade. That route is an old one. In the [river trade](liu-bao:nanyang-trade), the tea went by boat down to Wuzhou and on to Guangzhou, then out by sea to the Chinese miners and labourers of Southeast Asia."},{"layer":"place","text":"Cangwu is a county under [Wuzhou](guangxi:wuzhou-and-cangwu), in eastern Guangxi, and Liubao town, which gave the tea its name, lies inside it. The area is warm and wet, with acidic soils. The trade links that [steady damp warmth](guangxi:land-and-climate) to the slow ageing of Liu Bao, because the microbes that shape a dark tea thrive in it."},{"layer":"age","text":"Like every dark tea, the leaf was piled after it was made so that warmth, moisture and microbes could darken and soften it, and then it was packed to age. Thirty-six years on, it is well past the ten years after which the trade counts a Liu Bao as [aged](liu-bao:age-aged). The way it was stored has shaped it as much as the years have."}],"brewing":{"layer":"brewing","text":"Liu Bao takes very hot or boiling water, because its leaf is dense and gives up its depth slowly. Rinse it once or twice and pour the rinse away. Use about 5 to 8 grams to 100 ml, start with steeps of five to fifteen seconds and add a few seconds each round; a good Liu Bao gives ten cups or more."},"notice":{"layer":"notice","styleName":"aged Liu Bao","text":"A deep red, thick cup with woody, herbal and betel nut notes; tea several decades old is often described with ginseng and camphor."},"missing":[]},
  "748fd404-2846-4bac-83e3-797e884e9e22": {"productId":"748fd404-2846-4bac-83e3-797e884e9e22","paragraphs":[{"layer":"place","text":"This basket tea was made in 1985 in [Qimen County](qimen:where-it-is), in the hills of southern Anhui near the Huangshan mountains. It comes from the local small leaf bush that also gives [Keemun](qimen:known-for). The name points elsewhere: [Lu'an](anhui:lu-an-names) is a city in western Anhui known for a green tea, while this tea takes its name from the old Liu An way of making and trading."},{"layer":"type","text":"[Liu An](liu-an:definition) is a [dark tea](dark:definition), so the leaf keeps changing slowly after it is made. Spring leaf is first made much like a green tea, then fired over charcoal in autumn and spread outdoors for one night to take the [night dew](liu-an:making). It is steamed soft, packed into small [bamboo baskets](liu-an:basket) lined with bamboo leaf and fired once more. It is sold only after it has rested for some years."},{"layer":"age","text":"At forty-one years, this basket has rested far longer than the usual three. The style is said to [improve with years in its basket](liu-an:ageing), as long as it is kept dry and in wrapping that breathes. Basket tea was mostly known through the [southern trade](liu-an:southern-trade) in Guangdong, Hong Kong and Macau, where people kept it at home and in medicine shops."}],"brewing":{"layer":"brewing","text":"Use water at or near the boil, rinse the leaf quickly, and keep the steeps short, each a little longer than the last, in a gaiwan or clay pot; doses run from about 3 to 8 grams for 100 ml, for six to ten or more steeps. A small piece of the basket's bamboo leaf is often brewed with it. Aged tea can also be simmered in a larger pot, about 1 gram to 200 to 300 ml, for a few minutes or longer."},"notice":{"layer":"notice","styleName":"aged Liu An","text":"A redder, browner liquor, the smoke gone, and the cup moving toward medicinal, woody and camphor notes, often with betel nut."},"missing":[]},
  "74e4d411-449f-41d8-a425-9298a71a08ba": {"productId":"74e4d411-449f-41d8-a425-9298a71a08ba","paragraphs":[{"layer":"type","text":"[Meizhan](yancha:meizhan) (梅占) is a Fujian cultivar that came from Anxi, and this leaf was grown and made as [Wuyi rock tea](yancha:definition) in the Wuyi Mountains. It is less known than Rougui and Shui Xian, and it is not one of the four famous bushes of the range. As rock tea, the leaf is twisted into long strips and finished with a [charcoal roast](yancha:making) given in several rounds with rests between them, which dries the tea so it keeps."},{"layer":"place","text":"The bushes of this area grow in [thin, stony ground](wuyi-mountains:nature) among cliffs and ravines, where rain is heavy, mist is common and the soil drains fast. The record names the range but not a zone, so it does not say how close to the [true rock core](wuyi-mountains:zones) this leaf grew."},{"layer":"age","text":"Picked in 2024, the tea is two years old. Rock tea with a medium or full roast is the kind [kept for years](yancha:ageing), and the heavier the roast, the longer it is said to stay good, provided it is kept sealed, dry and cool."}],"brewing":{"layer":"brewing","text":"Wuyi tea is usually brewed gongfu style with water at or near the boil, about 95 to 100°C, and about 5 to 8 grams of leaf in a 100 to 120 ml gaiwan, a third to a half full. A quick rinse, poured off at once, is common. Steeps start short, about 5 to 20 seconds, and grow a few seconds longer each round, and good rock tea gives seven steeps or more. In a larger pot, use about 2 to 5 grams for 250 to 350 ml and steep two to three minutes."},"notice":{"layer":"notice","styleName":"Wuyi rock tea","text":"Roast and stone fruit, a mineral, rocky texture and a long, sweet, mouth-watering finish. Light roast is bright and floral, medium roast fruity and rounded, full roast charcoal, wood and roasted nuts. Da Hong Pao is often floral, Rougui spicy with cinnamon, young Shui Xian sweet and smooth, and old-bush Shui Xian woody and mossy."},"missing":[]},
  "76396f61-48ec-4bd6-bcf1-dd22c73633f4": {"productId":"76396f61-48ec-4bd6-bcf1-dd22c73633f4","paragraphs":[{"layer":"lot","text":"A loose [first-grade](anhua-dark:grades) [Anhua dark tea](anhua-dark:definition), made in 2020 from spring leaf grown in cultivated gardens. The county's raw leaf is sorted into numbered grades, and each finished tea draws on the grade that suits it. Anhua sits in the mountains on the Zi river in north-central Hunan, and its name is a protected origin in China, tied to a defined place of making."},{"layer":"age","text":"Every tea from the area begins as one raw tea, [heimaocha](anhua-dark:making): large leaf fixed, rolled, piled and rolled again before it is dried. At six years this one is still young for a tea that is kept for years and said to improve, though the trade has no agreed count of years that makes one [aged](anhua-dark:ageing). It is best kept clean, dry and aired, away from mould and other smells."}],"brewing":{"layer":"brewing","text":"In a small pot or gaiwan, use water at the boil and start with a steep of about 15 to 30 seconds, a little longer each round. Pressed and aged Anhua tea is also commonly simmered in a pot."},"notice":{"layer":"notice","styleName":"Anhua dark tea","text":"Pine smoke or pine resin above all, a sweet taste and aftertaste, and a mellow, thick, smooth cup; a liquor from yellow and orange to orange-red. Young tea is often smokier in the first infusions and a little bitter, sweetening as the infusions go on."},"missing":[]},
  "77175e22-e6a2-445a-9f1d-c1bad425e0c9": {"productId":"77175e22-e6a2-445a-9f1d-c1bad425e0c9","paragraphs":[{"layer":"type","text":"A rolled [GABA oolong](gaba:definition) from Taiwan. GABA names a way of making tea rather than a plant or a place: the leaf is treated so that the finished tea holds far more of this amino acid than ordinary tea does. The fresh leaf first spends some hours [without oxygen](gaba:making), sealed in a chamber filled with nitrogen or emptied to a vacuum. Without air it turns its glutamic acid into GABA and cannot break it down again, so it builds up. After that it is made as any [oolong](oolong:definition) is: withered and tossed, fixed, rolled and dried."},{"layer":"type","text":"The [method began in Japan](gaba:history) and is dated to 1987. Taiwan's tea research station later changed it and adapted it to oolong, and the island is now a main source of GABA tea sold abroad. The label names only [Taiwan](taiwan:on-a-label). That tells you the leaf was grown on the island and nothing more about its mountain, height or cultivar."}],"brewing":{"layer":"brewing","text":"In a cup or pot, steep it for about two to five minutes. It is forgiving of small changes in water temperature and steeping time. It can also be cold-brewed, steeped for some hours in the fridge."},"notice":{"layer":"notice","styleName":"gABA oolong","text":"Ripe, dried or stewed fruit such as apricot, honeyed sweetness, a smooth, round body, and little bitterness or astringency; often brown sugar or roasted grain, sometimes wood or spice, and a light fruity sourness."},"missing":[]},
  "7871147c-679b-45ce-af2a-d513e11d2f5a": {"productId":"7871147c-679b-45ce-af2a-d513e11d2f5a","paragraphs":[{"layer":"grade","text":"Zhen pin means precious item. It is one of the [grade words](tieguanyin:grades) that brands print in the names of Anxi Tieguanyin. This tea carries no year, so it is known by its grade rather than a vintage."},{"layer":"type","text":"The leaf is [Tieguanyin](tieguanyin:definition) from Anxi County in southern Fujian, where the tea began and where its name is protected. It was roasted in the traditional way. That is the older of the [Anxi styles](tieguanyin:styles), the one the light green kind displaced from the 1990s. Like other [oolong](oolong:definition), it is partly oxidised. It was [wrapped in cloth and rolled](tieguanyin:making) over several rounds, each round tightening the leaf into a small ball."}],"brewing":{"layer":"brewing","text":"Tieguanyin is usually brewed gongfu style with water at or near the boil, about 95 to 100°C; the light green style is often taken a little cooler, about 85 to 95°C. Use about 4 to 8 grams of leaf in a 100 to 150 ml gaiwan or pot, about a third full. A quick rinse, poured off at once, is common. Steeps start short, about 10 to 30 seconds, and grow a few seconds longer each round, and a good Tieguanyin gives about six to eight. In a larger pot, use about 2.5 to 5 grams for 240 to 350 ml and steep two to three minutes."},"notice":{"layer":"notice","styleName":"Tieguanyin","text":"In the light style: orchid and other flowers, a fresh, clean cup and a sweet aftertaste. In the roasted style: toast and charcoal, caramel or honey, stone or dried fruit, nuts, and a liquor that runs from gold to amber."},"missing":[]},
  "7871ff39-1980-4edc-b5cb-edebf5a62232": {"productId":"7871ff39-1980-4edc-b5cb-edebf5a62232","paragraphs":[{"layer":"lot","text":"This leaf is [Meizhan](yancha:meizhan), a Fujian cultivar that came from Anxi and is also made in the Wuyi Mountains, where this tea grew. It is less famous than Rougui and Shui Xian and sits outside the four famous bushes. The lot was taken to medium oxidation, the middle ground of a [partly oxidised](oolong:definition) tea, and finished with a traditional [charcoal roast](yancha:making), which dries the leaf so it keeps."},{"layer":"place","text":"The [Wuyi Mountains](wuyi-mountains:where-it-is) run along the border of northern Fujian and Jiangxi. The range is steep, wet and misty, and its bushes grow in [thin, stony soil](wuyi-mountains:nature) on ledges and between rocks, where the ground drains fast. A record that names only Wuyi does not say how close to the [scenic core](wuyi-mountains:zones) the leaf grew."},{"layer":"age","text":"A [medium roast](yancha:roast-levels) is the kind of Wuyi tea made to be kept for years. What it asks of its keeper is dry, sealed storage, since damp is the main fault of stored rock tea and can turn it [green again](yancha:ageing)."}],"brewing":{"layer":"brewing","text":"Wuyi tea is usually brewed gongfu style with water at or near the boil, about 95 to 100°C, and about 5 to 8 grams of leaf in a 100 to 120 ml gaiwan, a third to a half full. A quick rinse, poured off at once, is common. Steeps start short, about 5 to 20 seconds, and grow a few seconds longer each round, and good rock tea gives seven steeps or more. In a larger pot, use about 2 to 5 grams for 250 to 350 ml and steep two to three minutes."},"notice":{"layer":"notice","styleName":"aged Wuyi rock tea","text":"A smoother, thicker liquor with less sharpness, the roast softened and the high aroma faded."},"missing":[]},
  "78bdc812-b5da-47fb-88a9-b8d9cb69ad3a": {"productId":"78bdc812-b5da-47fb-88a9-b8d9cb69ad3a","paragraphs":[{"layer":"type","text":"Muyun Da Hong Pao is a [Wuyi rock tea](yancha:definition), the oolong of the Wuyi Mountains in northern Fujian, where the bushes grow among rock on ledges and terraces in cliff country. The name [Da Hong Pao](yancha:da-hong-pao), Big Red Robe, began with six mother trees on a cliff at Jiulongke, and picking from them stopped in 2006. What is sold under the name today is tea from Qidan, the cultivar grown from cuttings of those trees, or more often a blend of several Wuyi cultivars."},{"layer":"lot","text":"This leaf was twisted into long strips and given a heavy roast over charcoal, the way Wuyi tea is finished: in [several rounds](yancha:making) with rests of weeks or months between them, not in one pass. The roast dries the tea so it keeps, and the maker matches its strength to the leaf."},{"layer":"place","text":"The label names the Wuyi Mountains without a zone or a pit, so it does not say how close to the [true rock core](wuyi-mountains:zones) the bushes grew. The trade sorts Wuyi tea by that distance, from the stony core out through the half rock ring to the river banks."}],"brewing":{"layer":"brewing","text":"Wuyi tea is usually brewed gongfu style with water at or near the boil, about 95 to 100°C, and about 5 to 8 grams of leaf in a 100 to 120 ml gaiwan, a third to a half full. A quick rinse, poured off at once, is common. Steeps start short, about 5 to 20 seconds, and grow a few seconds longer each round, and good rock tea gives seven steeps or more. In a larger pot, use about 2 to 5 grams for 250 to 350 ml and steep two to three minutes."},"notice":{"layer":"notice","styleName":"Wuyi rock tea","text":"Roast and stone fruit, a mineral, rocky texture and a long, sweet, mouth-watering finish. Light roast is bright and floral, medium roast fruity and rounded, full roast charcoal, wood and roasted nuts. Da Hong Pao is often floral, Rougui spicy with cinnamon, young Shui Xian sweet and smooth, and old-bush Shui Xian woody and mossy."},"missing":[]},
  "78beda1b-688a-48b1-96f1-5969a7d90c88": {"productId":"78beda1b-688a-48b1-96f1-5969a7d90c88","paragraphs":[{"layer":"place","text":"An oolong from [Nantou](nantou:where-it-is), the county in the middle of Taiwan and the only one that does not touch the sea. Nantou is the island's [biggest tea county](nantou:why-people-value-it). Its land climbs from low hills to cold mountain gardens, and where in the county a tea grew decides whether it is made in the [roasted way or the high mountain way](nantou:altitude-bands). This record names only the county, not the township or mountain."},{"layer":"type","text":"It is rolled [oolong](oolong:definition), the partly oxidised tea that sits between green and red tea. It belongs to the [Taiwan oolong](taiwan-oolong:definition) line, whose plants and craft came over from Fujian."},{"layer":"age","text":"Made in 1979, it has now been kept for forty-seven years. Taiwan has its own tradition of keeping oolong, called [lao cha](taiwan-oolong:ageing), or old tea. The leaf chosen for keeping starts dry and well roasted. It is roasted again at low heat from time to time to drive out the moisture it takes in, and it is stored cool, dark and sealed. No standard says when an oolong becomes old. Those who give a figure put it between ten and thirty years, and this tea is well past the longest of them."}],"brewing":{"layer":"brewing","text":"Ball-rolled Taiwan oolong takes hot water, about 90 to 100°C, a fairly generous amount of leaf and short steeps; the balls open slowly and give many infusions. Roasted Dong Ding takes water from about 95°C to a full boil. Aged oolong takes very hot water, in a pot that holds its heat, clay above all. Oriental Beauty is the exception and takes cooler water, about 80 to 95°C."},"notice":{"layer":"notice","styleName":"aged Taiwan oolong","text":"A smooth, mellow, thick cup with little astringency, often plum or prune, sometimes something like medicinal herbs or ginseng, and an amber to red-brown liquor."},"missing":[]},
  "7c89fdac-12f2-4858-88f7-28b8e1bf9bb6": {"productId":"7c89fdac-12f2-4858-88f7-28b8e1bf9bb6","paragraphs":[{"layer":"age","text":"A cake of [raw pu’er](sheng:identity) made from Yunnan leaf in 1980. At forty-six years it sits well past both the ten years some count as [aged](sheng:ageing) and the twenty or more that many wait for."},{"layer":"type","text":"Unlike shou, it was never hurried through a fast fermentation. Its change has come slowly in [storage](sheng:aging), year by year, so the places it was kept are part of its history. Its year also puts it at the start of the decade when collectors, led at first by Taiwan, began [looking for aged raw pu’er](sheng:history-modern)."}],"brewing":{"layer":"brewing","text":"Pry the leaf off a cake or brick in chunks with a pick or knife, from the surface and toward the centre, rather than crumbling it. A mix of larger pieces and smaller ones brews evenly. Young raw pu’er takes water a little off the boil, about 85 to 95°C, because hotter water draws out more of its bitterness; an aged one takes 95°C to boiling. A common start is about 7 grams to 100 ml and a quick rinse of a few seconds, then a first steep of ten to fifteen seconds, adding a few seconds each round. A good raw tea gives eight to ten cups or more."},"notice":{"layer":"notice","styleName":"aged Sheng Pu’er","text":"A smoother, thicker, sweeter cup with woody, herbal and camphor notes and something of dried dates or dark fruit."},"missing":[]},
  "7fb0812b-4ae3-48c6-863b-ad59943eb88f": {"productId":"7fb0812b-4ae3-48c6-863b-ad59943eb88f","paragraphs":[{"layer":"lot","text":"A [ripe pu’er](shou:definition) cake from Yunnan, made in 2001. Its name, Qi Zi Bing, means seven sons cake, after the traditional packing of seven cakes to a bamboo tong. The leaf was fermented in a [wet pile](shou:wet-piling), heaped warm and damp and turned so the microbes could work through it, then pressed into this cake."},{"layer":"age","text":"That puts it in the style’s third decade, twenty-eight years after Yunnan’s factories brought the pile into production in 1973. At twenty-five years it sits well past the ten that mark [aged ripe pu’er](shou:age-aged), and the leaf is still changing slowly with the air and moisture around it. That is why storage shapes it as much as the years do."}],"brewing":{"layer":"brewing","text":"From a cake, brick or tuo, ease a piece off along the edge with a pick rather than snapping it. Whole leaves give up their flavour steadily; broken ones release it all at once and cloud the cup. Ripe pu’er takes boiling water: fermented, tightly packed leaf needs full heat to open, and it does not scald the way green tea can. A common start is about 7 grams to 100 ml and one quick rinse, which wakes the leaf and carries off dust and any pile smell. Then short steeps that lengthen as the leaf opens, so the cup stays clear rather than heavy; it gives eight or more good cups."},"notice":{"layer":"notice","styleName":"aged ripe pu’er","text":"A smooth, deep cup with woody, date-like or medicinal notes, which the trade calls aged aroma."},"missing":[]},
  "82124f03-a6a6-4a40-8a5b-cf1fc715ce8c": {"productId":"82124f03-a6a6-4a40-8a5b-cf1fc715ce8c","paragraphs":[{"layer":"place","text":"This is loose [Liu Bao](liu-bao:definition) from [Cangwu County](cangwu:where-it-is), in the hill country of eastern Guangxi, where the town of Liubao gave the tea its name. Like every [dark tea](dark:definition), the leaf was piled after it was made so that warmth, moisture and microbes could change it, and then it was packed away to age."},{"layer":"place","text":"It was made in 1980, during the long [decline](cangwu:decline-and-return) that began when war broke the river trade. By the early 1990s very few gardens in the county were still worked. Liu Bao had been made for [Chinese miners and labourers in Southeast Asia](liu-bao:nanyang-trade), and most Liu Bao of this age is [old stock](liu-bao:old-stock) that was left in warehouses in Malaysia and Hong Kong when that trade ended."},{"layer":"age","text":"At forty-six years it is far past the decade after which Liu Bao counts as [aged](liu-bao:age-aged). For a tea this old, the way it was stored has shaped it as much as the years have."}],"brewing":{"layer":"brewing","text":"Liu Bao takes very hot or boiling water, because its leaf is dense and gives up its depth slowly. Rinse it once or twice and pour the rinse away. Use about 5 to 8 grams to 100 ml, start with steeps of five to fifteen seconds and add a few seconds each round; a good Liu Bao gives ten cups or more."},"notice":{"layer":"notice","styleName":"aged Liu Bao","text":"A deep red, thick cup with woody, herbal and betel nut notes; tea several decades old is often described with ginseng and camphor."},"missing":[]},
  "82271623-93f1-40a7-901d-ba085c08014e": {"productId":"82271623-93f1-40a7-901d-ba085c08014e","paragraphs":[{"layer":"lot","text":"A cake of [raw pu’er](sheng:identity) made in Yunnan in 1980. The record does not name the mountain or the factory. The year places it in the decades after 1949, when pu’er was made in [state factories](sheng:history) to standard recipes and sold under the state tea company’s labels."},{"layer":"age","text":"Raw pu’er is never put through shou’s quick fermentation. It [changes slowly in storage](sheng:aging), so the forty-six years since it was pressed are part of this cake’s history. The trade has no agreed point where [aged raw pu’er](sheng:ageing) begins: some count from ten years, many from twenty. This cake is well past both. Heat and humidity set how fast that change runs, which is why [where a cake is kept](sheng:storage) shapes it as much as its age does."}],"brewing":{"layer":"brewing","text":"Pry the leaf off a cake or brick in chunks with a pick or knife, from the surface and toward the centre, rather than crumbling it. A mix of larger pieces and smaller ones brews evenly. Young raw pu’er takes water a little off the boil, about 85 to 95°C, because hotter water draws out more of its bitterness; an aged one takes 95°C to boiling. A common start is about 7 grams to 100 ml and a quick rinse of a few seconds, then a first steep of ten to fifteen seconds, adding a few seconds each round. A good raw tea gives eight to ten cups or more."},"notice":{"layer":"notice","styleName":"aged Sheng Pu’er","text":"A smoother, thicker, sweeter cup with woody, herbal and camphor notes and something of dried dates or dark fruit."},"missing":[]},
  "82c845c0-9cb6-4ce3-9eb0-29b501acd080": {"productId":"82c845c0-9cb6-4ce3-9eb0-29b501acd080","paragraphs":[{"layer":"place","text":"This leaf comes from [Yiwu](greater-yiwu:where-it-is), in the north of Mengla County in Xishuangbanna, on the east side of the Lancang River. The area is one of the old Six Famous Tea Mountains, and its town has long been where leaf from the surrounding villages is gathered and processed."},{"layer":"age","text":"At twenty years it sits well inside what the trade counts as [aged ripe pu’er](shou:age-aged). The leaf keeps changing slowly with the air and moisture around it, which is why the way it has been kept matters as much as the years."},{"layer":"type","text":"It was made as [ripe pu’er](shou:definition) in 2006 and kept loose rather than pressed, thirty-three years after Yunnan’s state factories brought the [wet-pile method](shou:wet-piling) into production. The pile is wetted, heaped and covered to hold the heat its microbes give off, then turned to let air in, so that in weeks the leaf reaches a change that raw pu’er only finds over years of keeping."}],"brewing":{"layer":"brewing","text":"Ripe pu’er takes boiling water: fermented, tightly packed leaf needs full heat to open, and it does not scald the way green tea can. A common start is about 7 grams to 100 ml and one quick rinse, which wakes the leaf and carries off dust and any pile smell. Then short steeps that lengthen as the leaf opens, so the cup stays clear rather than heavy; it gives eight or more good cups."},"notice":{"layer":"notice","styleName":"aged ripe pu’er","text":"A smooth, deep cup with woody, date-like or medicinal notes, which the trade calls aged aroma."},"missing":[]},
  "8367fc84-1fec-4f85-8b55-9677ccbe287d": {"productId":"8367fc84-1fec-4f85-8b55-9677ccbe287d","paragraphs":[{"layer":"place","text":"This is [Oriental Beauty](hsinchu:why-people-value-it) from [Hsinchu](hsinchu:where-it-is), a county of hills and uplands in the north west of Taiwan. Tea there is largely a [Hakka](hsinchu:hakka) trade: local families grow the leaf, make the tea and sell it, and many farms have passed down through generations. The record names the county but not a township, and the county covers several tea townships, among them [Emei and Beipu](hsinchu:tea-townships)."},{"layer":"type","text":"The tea depends on a [small green leafhopper](hsinchu:summer-leafhopper) that feeds on the young shoots in summer. Its bite starts the leaf's change while it is still on the bush, so growers keep insecticide off these gardens. The bud and the next two leaves are picked by hand, and the leaf is [oxidised far more](taiwan-oolong:oriental-beauty) than other Taiwan oolong, close to red tea, before it is dried. Locally it keeps an older folk name, [pengfeng cha](hsinchu:oriental-beauty-names), braggart's tea."}],"brewing":{"layer":"brewing","text":"Ball-rolled Taiwan oolong takes hot water, about 90 to 100°C, a fairly generous amount of leaf and short steeps; the balls open slowly and give many infusions. Roasted Dong Ding takes water from about 95°C to a full boil. Aged oolong takes very hot water, in a pot that holds its heat, clay above all. Oriental Beauty is the exception and takes cooler water, about 80 to 95°C."},"notice":{"layer":"notice","styleName":"Taiwan oolong","text":"In light high mountain tea: a sweet, floral cup, often creamy or buttery, with little bitterness and a long sweet aftertaste. In roasted Dong Ding: caramel, ripe fruit, nuts and a toasted aroma. In Baozhong: floral notes and a clear, bright liquor. In Oriental Beauty: ripe fruit and honey, with little bitterness."},"missing":[]},
  "861e232b-a63d-43aa-95a9-a98ef6621eb0": {"productId":"861e232b-a63d-43aa-95a9-a98ef6621eb0","paragraphs":[{"layer":"place","text":"A rolled [Taiwan oolong](taiwan-oolong:definition) from 1980, grown on the island whose tea plants and craft first came over from Fujian. Its label gives only [Taiwan](taiwan:on-a-label). That places the leaf on the island and says nothing of the mountain, township or cultivar it came from."},{"layer":"age","text":"At forty-six years it belongs to the island's tradition of [lao cha](taiwan-oolong:ageing), old tea. An oolong chosen for keeping starts well roasted and dry. It is roasted again at low heat from time to time to drive out the moisture it takes in, and it is kept cool, dark and sealed in between, while the liquor deepens over the years from amber towards red-brown. No standard says how many years make an oolong old. Those who give a figure put it somewhere between ten and thirty, and this tea is past both."}],"brewing":{"layer":"brewing","text":"Ball-rolled Taiwan oolong takes hot water, about 90 to 100°C, a fairly generous amount of leaf and short steeps; the balls open slowly and give many infusions. Roasted Dong Ding takes water from about 95°C to a full boil. Aged oolong takes very hot water, in a pot that holds its heat, clay above all. Oriental Beauty is the exception and takes cooler water, about 80 to 95°C."},"notice":{"layer":"notice","styleName":"aged Taiwan oolong","text":"A smooth, mellow, thick cup with little astringency, often plum or prune, sometimes something like medicinal herbs or ginseng, and an amber to red-brown liquor."},"missing":[]},
  "8630d742-ff45-466d-a26f-9e7e2993a46f": {"productId":"8630d742-ff45-466d-a26f-9e7e2993a46f","paragraphs":[{"layer":"place","text":"A [red tea](red:definition) grown in Taiwan. The label names only [the island](taiwan:on-a-label), not a mountain or township, so it tells you where the leaf grew and nothing finer. Red tea on the island dates from [the Japanese period](red:history), when it was first made at Yuchi near Sun Moon Lake, in the centre of [the island's tea country](taiwan:areas)."},{"layer":"type","text":"It is the fully oxidised tea that English calls black. The fresh leaf is [withered](red:making) until it is soft enough to work, then rolled so its juices and enzymes meet. It is left in warm, damp air until it turns reddish brown, and dried with hot air to end the change and keep it stable."},{"layer":"age","text":"This lot is from 2023, so it is three years old. Red tea has [no tradition of ageing](red:ageing): sealed, it keeps for about a year and a half to three years, and this tea now sits at the far end of that span."}],"brewing":{"layer":"brewing","text":"Red tea takes water near the boil, about 90 to 100°C; hotter water draws out its aroma and flavour more fully, but its bitterness faster too. In a pot or mug, use about a rounded spoon of leaf for each cup and steep three to five minutes, less for broken leaf and a little less, and a little cooler, for a light, delicate tea. Left too long, it turns bitter and drying, because time and heat pull more tannins from the leaf."},"notice":{"layer":"notice","styleName":"red tea","text":"A sweet cup, often with honey, floral or fruity notes, malt in many, and a brisk strength in the stronger teas. The liquor runs red, bright to deep."},"missing":[]},
  "88774ca9-5550-4abc-9d50-a60d71775b40": {"productId":"88774ca9-5550-4abc-9d50-a60d71775b40","paragraphs":[{"layer":"lot","text":"An iron cake, or tie bing, of [ripe pu’er](shou:definition) from Yunnan, made in 1997 and pressed with a hydraulic press rather than in a stone mould. The press packs the leaf far harder and denser than stone does, and that density slows the cake’s ageing, so the outside of the cake changes faster than its heart."},{"layer":"age","text":"It comes from the style’s third decade, twenty-four years after the [wet-pile method](shou:wet-piling) reached production in 1973. At twenty-nine years the cake counts as [aged ripe pu’er](shou:age-aged), where storage shapes it as much as the years do."}],"brewing":{"layer":"brewing","text":"From a cake, brick or tuo, ease a piece off along the edge with a pick rather than snapping it. Whole leaves give up their flavour steadily; broken ones release it all at once and cloud the cup. Ripe pu’er takes boiling water: fermented, tightly packed leaf needs full heat to open, and it does not scald the way green tea can. A common start is about 7 grams to 100 ml and one quick rinse, which wakes the leaf and carries off dust and any pile smell. Then short steeps that lengthen as the leaf opens, so the cup stays clear rather than heavy; it gives eight or more good cups."},"notice":{"layer":"notice","styleName":"aged ripe pu’er","text":"A smooth, deep cup with woody, date-like or medicinal notes, which the trade calls aged aroma."},"missing":[]},
  "892f6346-5381-4fc2-be7b-feebbafdd281": {"productId":"892f6346-5381-4fc2-be7b-feebbafdd281","paragraphs":[{"layer":"lot","text":"Raw pu’er from Yunnan, picked in 1963 to the maojian standard of young, downy tips, and kept as loose leaf ever since. The garden it came from is not recorded."},{"layer":"type","text":"Like all [raw pu’er](sheng:making), the leaf was fried to stop most of its own enzymes, then dried in the sun and never with hot air. The activity that survived is what has let it keep changing for years. It was never pressed and has stayed as [maocha](sheng:processing), the rough tea in its loose state."},{"layer":"age","text":"At sixty-three years it is well past any line the trade draws for [aged raw pu’er](sheng:ageing), whether that line is ten years or twenty. Over those decades its [storage](sheng:storage) has been part of its history."}],"brewing":{"layer":"brewing","text":"Young raw pu’er takes water a little off the boil, about 85 to 95°C, because hotter water draws out more of its bitterness; an aged one takes 95°C to boiling. A common start is about 7 grams to 100 ml and a quick rinse of a few seconds, then a first steep of ten to fifteen seconds, adding a few seconds each round. A good raw tea gives eight to ten cups or more."},"notice":{"layer":"notice","styleName":"aged Sheng Pu’er","text":"A smoother, thicker, sweeter cup with woody, herbal and camphor notes and something of dried dates or dark fruit."},"missing":[]},
  "8c24430b-49d5-4c9d-9ea8-2d353057e2b9": {"productId":"8c24430b-49d5-4c9d-9ea8-2d353057e2b9","paragraphs":[{"layer":"named","text":"[Nanqiao](nanqiao-ruigong-brick:nanqiao-name) was once the name of the county around Mengzhe in southern Yunnan. Menghai County Nanqiao Tea Company, founded in February 2004, kept that old name for itself. The China Tea Marketing Association lists Che Fo Nan as its brand and records that its teas went to Hong Kong, Taiwan and Southeast Asia. Ruigong bricks reached that trade: at a Malaysian tea fair in 2022, the exhibitor Quanyuxuan offered five of them together at stall 27, listed as [ripe tea from 2008](nanqiao-ruigong-brick:malaysian-tea-fair), a year older than this one."},{"layer":"type","text":"This brick holds leaf from [Menghai County](menghai-county:county-and-factory), made into [ripe pu’er](shou:definition) in 2009. The leaf was heaped warm and damp in a [fermenting pile](shou:wet-piling) and turned so that air could reach it, all to give in weeks the dark cup that raw pu’er takes years to reach. Yunnan’s state factories brought that method into production in 1973, so this brick comes from the style’s fourth decade."},{"layer":"age","text":"At seventeen years it is well past the ten that the trade counts as [aged ripe pu’er](shou:age-aged). The leaf keeps changing slowly with the air and moisture around it, which is why the way it has been kept matters as much as its years."}],"brewing":{"layer":"brewing","text":"From a cake, brick or tuo, ease a piece off along the edge with a pick rather than snapping it. Whole leaves give up their flavour steadily; broken ones release it all at once and cloud the cup. Ripe pu’er takes boiling water: fermented, tightly packed leaf needs full heat to open, and it does not scald the way green tea can. A common start is about 7 grams to 100 ml and one quick rinse, which wakes the leaf and carries off dust and any pile smell. Then short steeps that lengthen as the leaf opens, so the cup stays clear rather than heavy; it gives eight or more good cups."},"notice":{"layer":"notice","styleName":"aged ripe pu’er","text":"A smooth, deep cup with woody, date-like or medicinal notes, which the trade calls aged aroma."},"missing":[]},
  "8cfed807-4557-4409-bd82-7d373c549421": {"productId":"8cfed807-4557-4409-bd82-7d373c549421","paragraphs":[{"layer":"place","text":"This cake was made from [Yiwu](greater-yiwu:where-it-is) leaf, grown in the north of Mengla County in Xishuangbanna, on the east side of the Lancang River. The area is one of the old Six Famous Tea Mountains, and its town has long been where the surrounding villages bring their tea to be gathered and processed."},{"layer":"type","text":"The leaf was made into [ripe pu’er](shou:definition) by [wet piling](shou:wet-piling). It was wetted and heaped so that microbes could warm it from within, covered to hold that heat and turned about once a week to let air in, then dried after one to two months and pressed into a cake in 2015. The pile exists to give, in weeks, the change that raw pu’er only reaches after years of keeping."},{"layer":"age","text":"At eleven years it has passed into what the trade counts as [aged ripe pu’er](shou:age-aged). The leaf still changes slowly with the air and moisture around it, which is why storage matters as much as the years."}],"brewing":{"layer":"brewing","text":"From a cake, brick or tuo, ease a piece off along the edge with a pick rather than snapping it. Whole leaves give up their flavour steadily; broken ones release it all at once and cloud the cup. Ripe pu’er takes boiling water: fermented, tightly packed leaf needs full heat to open, and it does not scald the way green tea can. A common start is about 7 grams to 100 ml and one quick rinse, which wakes the leaf and carries off dust and any pile smell. Then short steeps that lengthen as the leaf opens, so the cup stays clear rather than heavy; it gives eight or more good cups."},"notice":{"layer":"notice","styleName":"aged ripe pu’er","text":"A smooth, deep cup with woody, date-like or medicinal notes, which the trade calls aged aroma."},"missing":[]},
  "912d02af-6ae4-4f87-b4eb-3039801b66d0": {"productId":"912d02af-6ae4-4f87-b4eb-3039801b66d0","paragraphs":[{"layer":"type","text":"A cake of [white tea](white:definition) from [Fujian](fujian-white:definition), the province that is its home, dated 2008. The leaf is only withered and dried, never rolled or heated to stop its change. [Pressed white tea](fujian-white:cakes) is new: cakes began in the 2000s and spread around 2010, because a cake keeps and travels more easily than loose leaf. That places this one among the early cakes, though the year on a cake can mark its pressing rather than its picking."},{"layer":"age","text":"At eighteen years it is well past the seven of the trade's saying, [one year tea, three years medicine, seven years treasure](fujian-white:ageing). It is a saying, not a measure, and no agreed number of years makes a white tea aged. It is best kept dry, clean and aired, away from strong smells and sunlight."}],"brewing":{"layer":"brewing","text":"Gongfu style, use about 1 gram of leaf to 15 to 25 ml of water, for example 5 grams in a 100 to 110 ml gaiwan; weigh it, since the leaf is light and bulky. Silver Needle and young, delicate tea take water below the boil, about 75 to 90°C; older, leafier or aged tea takes water at or near the boil. Start with a steep of 10 to 45 seconds and add a few seconds each round. An aged cake is often rinsed quickly first, and older pressed tea can be simmered on the stove, about 5 grams to 500 ml for 3 to 10 minutes; young, delicate tea is not."},"notice":{"layer":"notice","styleName":"aged Fujian white","text":"Jujube or dried dates, herbs and medicine, wood, honey and dried fruit, a deeper, redder liquor, a thicker, rounder body, and less lift in the scent than a young tea."},"missing":[]},
  "9196a857-be6d-4dfe-b6fc-8b0c6f3cbb8e": {"productId":"9196a857-be6d-4dfe-b6fc-8b0c6f3cbb8e","paragraphs":[{"layer":"type","text":"Miracle Fate is a loose [ripe pu’er](shou:definition) from Yunnan. The leaf was fermented in a warm, damp pile and then left unpressed. The pile was developed to give, within weeks, the dark and mellow cup that Hong Kong and Guangdong drinkers knew from raw pu’er aged for years. That is why a tea like this is ready to drink soon after it is made."},{"layer":"type","text":"In [wet piling](shou:wet-piling), sun-dried leaf is wetted and heaped so that heat, moisture and microbes can work on it. The microbes make the heat, so the heap is covered to hold it in. It is turned about once a week to spread that heat and let air in, and kept below about 65°C so the leaf does not char. After one to two months the leaf is dried. Yunnan’s state factories brought the method into production in 1973."}],"brewing":{"layer":"brewing","text":"Ripe pu’er takes boiling water: fermented, tightly packed leaf needs full heat to open, and it does not scald the way green tea can. A common start is about 7 grams to 100 ml and one quick rinse, which wakes the leaf and carries off dust and any pile smell. Then short steeps that lengthen as the leaf opens, so the cup stays clear rather than heavy; it gives eight or more good cups."},"notice":{"layer":"notice","styleName":"ripe pu’er","text":"A smooth, sweet cup with earthy or woody notes. A young ripe tea can carry a faint smell of the pile, which fades with airing or in the first steeps."},"missing":[]},
  "92d1bdc0-531f-4b3b-b0f4-89cc9b2eb71f": {"productId":"92d1bdc0-531f-4b3b-b0f4-89cc9b2eb71f","paragraphs":[{"layer":"lot","text":"These pearls are [Yunnan white](yunnan-white:definition), made from the large-leaf tea plants of Yunnan. The leaf was withered and dried [the white tea way](yunnan-white:making), then rolled into dragon pearls by hand. Each pearl was shaped on its own while the leaf was still pliable, which makes this slow work."},{"layer":"type","text":"The rolling is what sets this tea apart. [White tea](white:definition) is not normally rolled or bruised, so the leaf keeps its natural shape and oxidises only a little, by its own enzymes. Shaping each pearl bruises the leaf slightly, and that gives this tea a faint layer of oxidation on top of the white tea base."}],"brewing":{"layer":"brewing","text":"Yunnan white is brewed gently, as a white tea is, in a gaiwan or small pot, and it gives many infusions; the leaf holds up well."},"notice":{"layer":"notice","styleName":"Yunnan white","text":"A honeyed, sweet cup, often richer and fuller than Fujian white, with little bitterness, sometimes fruit like apricot or melon and a hay or herbal note. Yabao is sweet and silky, often with pine or herbal notes."},"missing":[]},
  "92edd2a0-12ae-4116-b722-1da128d99923": {"productId":"92edd2a0-12ae-4116-b722-1da128d99923","paragraphs":[{"layer":"type","text":"A cake of [Yunnan white tea](yunnan-white:definition) from Lincang. It is made from Yunnan's large leaf tea plants rather than the small bush cultivars of Fujian, where most [white tea](white:definition) is still made. White tea is the tea of fewest steps: the leaf is never heated to halt its change and never rolled, so it keeps its natural shape."},{"layer":"type","text":"In Yunnan the leaf is [withered indoors or in shade](yunnan-white:making), out of the midday sun, then dried by air without the final low bake that Fujian white usually gets. Pressing it into a cake borrows one of the shapes of pu’er. Yunnan white is [new to the trade](yunnan-white:history), popular only in recent years, though local practice may be older."}],"brewing":{"layer":"brewing","text":"Yunnan white is brewed gently, as a white tea is, in a gaiwan or small pot, and it gives many infusions; the leaf holds up well."},"notice":{"layer":"notice","styleName":"Yunnan white","text":"A honeyed, sweet cup, often richer and fuller than Fujian white, with little bitterness, sometimes fruit like apricot or melon and a hay or herbal note. Yabao is sweet and silky, often with pine or herbal notes."},"missing":[]},
  "958129f4-e643-4ea2-9cc4-9c3aa9ff0613": {"productId":"958129f4-e643-4ea2-9cc4-9c3aa9ff0613","paragraphs":[{"layer":"lot","text":"A [ripe pu’er](shou:definition) from Yunnan, made in 1998 and packed in bamboo tubes. That places it in the style’s third decade: Yunnan’s state factories only brought the [wet-pile method](shou:wet-piling) into production in 1973."},{"layer":"age","text":"At twenty-eight years it has become what the trade counts as [aged ripe pu’er](shou:age-aged). The leaf keeps changing slowly with the air and moisture around it, so the way it has been kept matters as much as the years."}],"brewing":{"layer":"brewing","text":"From a cake, brick or tuo, ease a piece off along the edge with a pick rather than snapping it. Whole leaves give up their flavour steadily; broken ones release it all at once and cloud the cup. Ripe pu’er takes boiling water: fermented, tightly packed leaf needs full heat to open, and it does not scald the way green tea can. A common start is about 7 grams to 100 ml and one quick rinse, which wakes the leaf and carries off dust and any pile smell. Then short steeps that lengthen as the leaf opens, so the cup stays clear rather than heavy; it gives eight or more good cups."},"notice":{"layer":"notice","styleName":"aged ripe pu’er","text":"A smooth, deep cup with woody, date-like or medicinal notes, which the trade calls aged aroma."},"missing":[]},
  "967f2ab8-25ad-4b80-87b8-8386e331015f": {"productId":"967f2ab8-25ad-4b80-87b8-8386e331015f","paragraphs":[{"layer":"place","text":"A [white tea](white:definition) cake from Fujian, the province that is [the home of white tea](fujian-white:definition). The record [names the province only](fujian:on-a-label), so the leaf may come from Fuding, Zhenghe or another county that makes white tea; which one is not recorded."},{"layer":"type","text":"Pressing white tea is a recent practice. [White tea cakes](fujian-white:cakes) began in the 2000s and spread around 2010, because a cake is smaller and easier to keep and carry than loose leaf. Some are pressed from leaf already aged loose for a few years, so the year 2016 can mark the pressing rather than the picking."},{"layer":"age","text":"At ten years, this cake is past the seven in the trade's saying that white tea is [tea in its first year, medicine at three and a treasure at seven](fujian-white:ageing). That is a saying, not a tested claim, and no agreed number of years makes a white tea aged."}],"brewing":{"layer":"brewing","text":"Gongfu style, use about 1 gram of leaf to 15 to 25 ml of water, for example 5 grams in a 100 to 110 ml gaiwan; weigh it, since the leaf is light and bulky. Silver Needle and young, delicate tea take water below the boil, about 75 to 90°C; older, leafier or aged tea takes water at or near the boil. Start with a steep of 10 to 45 seconds and add a few seconds each round. An aged cake is often rinsed quickly first, and older pressed tea can be simmered on the stove, about 5 grams to 500 ml for 3 to 10 minutes; young, delicate tea is not."},"notice":{"layer":"notice","styleName":"aged Fujian white","text":"Jujube or dried dates, herbs and medicine, wood, honey and dried fruit, a deeper, redder liquor, a thicker, rounder body, and less lift in the scent than a young tea."},"missing":[]},
  "968b7e58-a7aa-45d3-8186-f02a1dad3323": {"productId":"968b7e58-a7aa-45d3-8186-f02a1dad3323","paragraphs":[{"layer":"age","text":"A rolled [Taiwan oolong](taiwan-oolong:definition) from 1989, now thirty-seven years old. It is [lao cha](taiwan-oolong:ageing), old tea, in the island's sense: oolong kept for years and roasted again at low heat from time to time, to drive out the moisture it takes in while it rests. No standard sets how many years make an oolong old. Those who give a figure put it somewhere between ten and thirty, and this tea has passed the longest of them."},{"layer":"place","text":"The origin is given only as [Taiwan](taiwan:on-a-label). That places the leaf on the island, whose tea plants and craft came from Fujian, but says nothing of the mountain, the height or the cultivar it grew from."}],"brewing":{"layer":"brewing","text":"Ball-rolled Taiwan oolong takes hot water, about 90 to 100°C, a fairly generous amount of leaf and short steeps; the balls open slowly and give many infusions. Roasted Dong Ding takes water from about 95°C to a full boil. Aged oolong takes very hot water, in a pot that holds its heat, clay above all. Oriental Beauty is the exception and takes cooler water, about 80 to 95°C."},"notice":{"layer":"notice","styleName":"aged Taiwan oolong","text":"A smooth, mellow, thick cup with little astringency, often plum or prune, sometimes something like medicinal herbs or ginseng, and an amber to red-brown liquor."},"missing":[]},
  "987919f9-5496-4a9d-aa00-0907b50feac9": {"productId":"987919f9-5496-4a9d-aa00-0907b50feac9","paragraphs":[{"layer":"place","text":"A [rolled oolong](taiwan-oolong:definition) grown in [Lugu](lugu:where-it-is), a mountain township of valleys and bamboo forest in the south west of Nantou County, in central Taiwan. Lugu is where [Dong Ding oolong](nantou:lugu-dong-ding) comes from. Its tea goes back to bushes [brought from Fujian](lugu:history) in the nineteenth century; the story told locally credits Lin Fengchi with a few seedlings planted on the slopes of Dong Ding. The township lies in the [middle belt](nantou:altitude-bands) of Nantou's tea country, below the high mountain gardens, where roasted oolong is at home."},{"layer":"age","text":"This tea was made in 1996 and has had thirty years since, which places it in Taiwan's tradition of keeping oolong as [lao cha](taiwan-oolong:ageing), old tea. Oolong kept this way is stored cool, dry, dark and sealed, and roasted again at low heat from time to time to drive out the moisture it takes in. No standard says how many years make an oolong old. Those who give a figure put it somewhere between ten and thirty, so at thirty years this tea sits at the far end of that count."}],"brewing":{"layer":"brewing","text":"Ball-rolled Taiwan oolong takes hot water, about 90 to 100°C, a fairly generous amount of leaf and short steeps; the balls open slowly and give many infusions. Roasted Dong Ding takes water from about 95°C to a full boil. Aged oolong takes very hot water, in a pot that holds its heat, clay above all. Oriental Beauty is the exception and takes cooler water, about 80 to 95°C."},"notice":{"layer":"notice","styleName":"aged Taiwan oolong","text":"A smooth, mellow, thick cup with little astringency, often plum or prune, sometimes something like medicinal herbs or ginseng, and an amber to red-brown liquor."},"missing":[]},
  "9887552c-a0a0-415f-bcdf-4d4fd3f94975": {"productId":"9887552c-a0a0-415f-bcdf-4d4fd3f94975","paragraphs":[{"layer":"place","text":"A 2008 cake of [raw pu’er](sheng:identity) from [Yiwu](greater-yiwu:where-it-is), in the north of Mengla County in Xishuangbanna, on the east side of the Lancang River. The area is one of the old Six Famous Tea Mountains, and its town has long been where leaf from the surrounding villages is gathered and processed. The record names the region rather than a single village, and [on a label the name](greater-yiwu:on-a-label) can mean the town, the mountain or a wider area."},{"layer":"type","text":"Raw pu’er is fried to kill the green and then [dried in the sun](sheng:making) rather than by hot air, so some of the leaf’s own activity survives and the tea keeps changing for years. How fast depends on how tightly it was [pressed](sheng:pressing) and how it was [stored](sheng:storage), since heat and humidity drive the slow oxidation and microbial work inside the cake."},{"layer":"age","text":"At eighteen years this cake sits where the trade divides: some count raw pu’er as [aged](sheng:ageing) from ten years, while many wait for twenty or more."}],"brewing":{"layer":"brewing","text":"Pry the leaf off a cake or brick in chunks with a pick or knife, from the surface and toward the centre, rather than crumbling it. A mix of larger pieces and smaller ones brews evenly. Young raw pu’er takes water a little off the boil, about 85 to 95°C, because hotter water draws out more of its bitterness; an aged one takes 95°C to boiling. A common start is about 7 grams to 100 ml and a quick rinse of a few seconds, then a first steep of ten to fifteen seconds, adding a few seconds each round. A good raw tea gives eight to ten cups or more."},"notice":{"layer":"notice","styleName":"aged Sheng Pu’er","text":"A smoother, thicker, sweeter cup with woody, herbal and camphor notes and something of dried dates or dark fruit."},"missing":[]},
  "997225e0-c2b5-4769-b869-e9a635462462": {"productId":"997225e0-c2b5-4769-b869-e9a635462462","paragraphs":[{"layer":"grade","text":"Huangpian are the older, coarser leaves pulled out when tea is sorted. For a long time the trade counted them as low grade, and some threw them away, before it came round to them. This is huangpian from Yunnan, made into loose [ripe pu’er](shou:definition) in the 1990s. That was within three decades of 1973, when the [wet-pile method](shou:wet-piling) reached production."},{"layer":"age","text":"Made in the 1990s, the tea is well past the ten years after which the trade counts a ripe pu’er as [aged](shou:age-aged). The leaf keeps changing slowly with the air and moisture around it, so the way it has been kept shapes it as much as the years have."}],"brewing":{"layer":"brewing","text":"Ripe pu’er takes boiling water: fermented, tightly packed leaf needs full heat to open, and it does not scald the way green tea can. A common start is about 7 grams to 100 ml and one quick rinse, which wakes the leaf and carries off dust and any pile smell. Then short steeps that lengthen as the leaf opens, so the cup stays clear rather than heavy; it gives eight or more good cups."},"notice":{"layer":"notice","styleName":"aged ripe pu’er","text":"A smooth, deep cup with woody, date-like or medicinal notes, which the trade calls aged aroma."},"missing":[]},
  "9b5b05f1-a6d6-4651-9126-0fe42c5c5e86": {"productId":"9b5b05f1-a6d6-4651-9126-0fe42c5c5e86","paragraphs":[{"layer":"named","text":"Huiliu means [returned](malaysian-returned-liu-bao:returned), and on this label Malaysia names a stop in the life of the tea, not where it grew. This [Liu Bao](liu-bao:definition) was made in Guangxi in the 1990s. The shop traces it from Guangzhou to storage in Malaysia and Singapore, then back to Guangzhou again."},{"layer":"named","text":"That journey follows an old road. A [trade account published in 1951](malaysian-returned-liu-bao:river-trade) follows Liu Bao downstream, changing to a larger wooden boat at Libu for Fengkai and then to a powered vessel for Guangzhou, with Ipoh and Kuala Lumpur among its final markets. The tea was made for [Chinese miners and labourers in Malaya](liu-bao:nanyang-trade), above all in the tin mines. Older tea has since been [finding its way back](malaysian-returned-liu-bao:tea-came-back): on a visit to Wuzhou in 2024, the Malaysian trade representative Lin Hengyi saw a 1973 import order linking a Malaysian firm with a Wuzhou tea company, and merchants there asked him about bringing older Liu Bao back to the Chinese market."},{"layer":"age","text":"At thirty-one years this lot is well past the ten after which the trade counts a Liu Bao as [aged](liu-bao:age-aged). Its years abroad are part of that count, because how the tea was stored matters as much as how long, and the [place a lot was kept](liu-bao:old-stock) gives it its own character."}],"brewing":{"layer":"brewing","text":"Liu Bao takes very hot or boiling water, because its leaf is dense and gives up its depth slowly. Rinse it once or twice and pour the rinse away. Use about 5 to 8 grams to 100 ml, start with steeps of five to fifteen seconds and add a few seconds each round; a good Liu Bao gives ten cups or more."},"notice":{"layer":"notice","styleName":"aged Liu Bao","text":"A deep red, thick cup with woody, herbal and betel nut notes; tea several decades old is often described with ginseng and camphor."},"missing":[]},
  "9bdb9053-442d-4090-8419-8e16a31a886b": {"productId":"9bdb9053-442d-4090-8419-8e16a31a886b","paragraphs":[{"layer":"age","text":"A [Tieguanyin](tieguanyin:definition) made in 1970 and kept for the fifty-six years since. That puts its making about two decades before the light green style took over in Anxi in the 1990s. Its years place it in the third kind the trade sorts Tieguanyin into, [old Tie](tieguanyin:styles) or chenxiang, which is Tieguanyin kept for years."},{"layer":"place","text":"The leaf grew in [Anxi](anxi:where-it-is), a county of Quanzhou prefecture in southern Fujian, on the southern side of the Daiyun mountains. Tieguanyin fills most of the county's tea land, and its name is protected there as [Anxi Tieguanyin](anxi:on-a-label), so the label states where the leaf grew. It is rolled into tight balls. Tieguanyin is usually given that form by [wrapping the leaf in cloth and rolling it](tieguanyin:making) round after round."}],"brewing":{"layer":"brewing","text":"Tieguanyin is usually brewed gongfu style with water at or near the boil, about 95 to 100°C; the light green style is often taken a little cooler, about 85 to 95°C. Use about 4 to 8 grams of leaf in a 100 to 150 ml gaiwan or pot, about a third full. A quick rinse, poured off at once, is common. Steeps start short, about 10 to 30 seconds, and grow a few seconds longer each round, and a good Tieguanyin gives about six to eight. In a larger pot, use about 2.5 to 5 grams for 240 to 350 ml and steep two to three minutes."},"notice":{"layer":"notice","styleName":"aged Tieguanyin","text":"A smoother, rounder, softer cup with the fire gone, a liquor turned orange-red or reddish-brown, and often a soft fruity sourness."},"missing":[]},
  "9df5db45-98f8-4d89-a852-65fd42e62e23": {"productId":"9df5db45-98f8-4d89-a852-65fd42e62e23","paragraphs":[{"layer":"place","text":"Ruicaokui (瑞草魁) is a [green tea](green:definition) from [Anhui](anhui:where-it-is), the province in eastern China where tea grows only in the hills of the south and west, in a few separate pockets, while the flat north grows none. Anhui is [known above all for its green teas](anhui:known-for). Its tea hills lie under [mist and cloud](anhui:land-and-climate) for much of the year, and the cold winters let the bushes rest, so the leaf comes on strong in spring."},{"layer":"type","text":"Like every tea of its kind, this leaf was never allowed to oxidise. Soon after picking it was [fixed](green:making), heated fast to stop the leaf's own enzymes before they could turn it brown. It was then rolled to take its shape and dried until only a little water remained, so that it keeps."}],"brewing":{"layer":"brewing","text":"Green tea takes water well below the boil, about 80°C, a little cooler for the youngest leaf and a little warmer for older, larger leaf. Boiling water draws out bitterness and dries the cup. A common start is about 2 grams of leaf to 100 ml, in a glass or a small gaiwan, with short steeps of half a minute to two minutes, and the same leaf can be brewed a few times."},"notice":{"layer":"notice","styleName":"green tea","text":"A fresh, clean cup that many call crisp, with a sweet, soft finish, and a pale green to yellow-green liquor. The smell runs from fresh leaf to flowers, and steamed teas lean grassy or seaweed-like. Too much heat or too long a steep turns the cup bitter and drying."},"missing":[]},
  "9fd4470c-41fe-482b-88c0-d867afe2eeb8": {"productId":"9fd4470c-41fe-482b-88c0-d867afe2eeb8","paragraphs":[{"layer":"place","text":"This [oolong](oolong:definition) comes from [Li Shan](li-shan:where-it-is), Pear Mountain, a high area in the middle of Taiwan whose tea gardens are the highest on the island, at roughly 1,800 to 2,500 metres. Most places put it in [Heping District, Taichung](li-shan:taichung-or-nantou). Tea came to these slopes late, in the last decades of the twentieth century, and by the 1990s Li Shan counted as one of the island's main [high mountain tea](li-shan:history) names."},{"layer":"place","text":"Cold shapes the leaf at this height. Nights are cool and [mist and cloud](li-shan:why-people-value-it) sit on the slopes, so the leaves grow slowly, and the cold allows fewer harvests in a year. The usual tea of the area is lightly oxidised and rolled into balls, the way most [Taiwan oolong](taiwan-oolong:definition) is made."},{"layer":"age","text":"This lot is from 2019, which makes it seven years old. That is still young by the measure of [lao cha](taiwan-oolong:ageing), Taiwan's tradition of keeping oolong for years, where those who give a figure put old tea at somewhere between ten and thirty years."}],"brewing":{"layer":"brewing","text":"Ball-rolled Taiwan oolong takes hot water, about 90 to 100°C, a fairly generous amount of leaf and short steeps; the balls open slowly and give many infusions. Roasted Dong Ding takes water from about 95°C to a full boil. Aged oolong takes very hot water, in a pot that holds its heat, clay above all. Oriental Beauty is the exception and takes cooler water, about 80 to 95°C."},"notice":{"layer":"notice","styleName":"Taiwan oolong","text":"In light high mountain tea: a sweet, floral cup, often creamy or buttery, with little bitterness and a long sweet aftertaste. In roasted Dong Ding: caramel, ripe fruit, nuts and a toasted aroma. In Baozhong: floral notes and a clear, bright liquor. In Oriental Beauty: ripe fruit and honey, with little bitterness."},"missing":[]},
  "a0ee5133-19c6-4828-9765-e0cba1275788": {"productId":"a0ee5133-19c6-4828-9765-e0cba1275788","paragraphs":[{"layer":"place","text":"This [Lapsang Souchong](lapsang:definition) comes from the [Wuyi Mountains](wuyi-mountains:where-it-is), on the border of northern Fujian and Jiangxi. The range makes two very different teas on different ground: rock oolong in the lower valleys and cliffs, and Lapsang on the high, forested northern edge around [Tongmu](wuyi-mountains:two-teas), the village widely called the birthplace of Chinese black tea. Tea shipped from this area to Europe in the seventeenth and eighteenth centuries was sold as [Bohea](fujian:history), a spelling of the local name for Wuyi."},{"layer":"type","text":"It is a [red tea](red:definition), the fully oxidised tea English calls black, and Lapsang is called the oldest of them, though the dates given for its beginning differ. The leaf is withered, rolled and left to oxidise in covered baskets, then passed through a [hot pan](lapsang:making) to stop the oxidation quickly and rolled again while hot, which shapes the strip and helps it take up smoke. In the traditional way it is dried over a [pine fire](lapsang:smoke) in a qinglou, a wooden house of several floors with the fire at the bottom and the leaf on bamboo mats above, so the heat rises through it."}],"brewing":{"layer":"brewing","text":"In a cup or pot, use about 3 grams for 240 ml, with water at 90 to 100°C, and steep about two to five minutes, usually around three. Gongfu style, use about 5 grams in a 100 to 110 ml gaiwan or pot, with short steeps that grow a little longer each round. Too hot or too long and the smoke turns harsh and bitter and covers the tea."},"notice":{"layer":"notice","styleName":"Lapsang Souchong","text":"In the smoked tea: pine and pine resin, longan or dried longan, campfire or woodsmoke, dried fruit and a sweet aftertaste. In the unsmoked tea: honey, longan and fruit or flowers."},"missing":[]},
  "a17b96aa-a13e-4713-930d-ebc939d85f2c": {"productId":"a17b96aa-a13e-4713-930d-ebc939d85f2c","paragraphs":[{"layer":"type","text":"An [oolong](oolong:definition), the partly oxidised tea, made in China in 1983. How far the leaf is oxidised and how hard it is [roasted](oolong:oxidation-and-roast) are two separate choices. Roasting lowers the moisture in the leaf."},{"layer":"age","text":"It has been kept for forty-three years. Only oolong that was well made and well roasted is set aside to age, because a light, green oolong fades if it is kept too long, and damp is the danger for oolong that was not dried and roasted enough. Through years of [storage](oolong:ageing), good oolong is roasted again at low heat from time to time to drive off the moisture it has taken in, and as the decades pass its liquor deepens towards red-brown."}],"brewing":{"layer":"brewing","text":"Oolong is most often brewed gongfu style, in a small gaiwan or clay pot with plenty of leaf and short steeps, and it stands many rounds. A common start is about 4 to 6 grams to 100 ml, with a first steep of roughly 5 to 15 seconds and 5 to 10 seconds more each round. Light, green-style oolong takes water a little off the boil, about 90 to 95°C; heavily oxidised, roasted and aged oolong takes water at a full boil. Many people pour a quick first rinse to wake tightly rolled leaf. In a larger pot, use less leaf and steep for a few minutes."},"notice":{"layer":"notice","styleName":"aged oolong","text":"A smooth, mellow and sweet cup, often with dried fruit or plum and wood, sometimes something herbal, little astringency, and an amber to red-brown liquor."},"missing":[]},
  "a2e0137d-705e-4255-8e40-3bf0f319fdf4": {"productId":"a2e0137d-705e-4255-8e40-3bf0f319fdf4","paragraphs":[{"layer":"place","text":"The leaf comes from [Zhenghe](zhenghe:where-it-is), an inland mountain county in the north of Fujian. It sits back from the coast under forest and mist, and its winters are colder than on the coastal tea hills. With Fuding it is one of the two main homes of white tea. The county grows its own bush, [Zhenghe Da Bai](zhenghe:known-for), which is said to have been found at Tieshan in the late nineteenth century and is now planted well beyond the area."},{"layer":"type","text":"[White tea](white:definition) is made in the fewest steps. The leaf is [withered and then dried at low heat](fujian-white:making), and it is never fixed or rolled. This one was pressed into a cake. Dated 2008, it comes from the early years of [pressed white tea](fujian-white:cakes). Cakes began in the 2000s and spread around 2010, because a cake is easier to keep and carry than loose leaf. Some cakes were pressed from leaf that had already aged loose, so the year can mark the pressing rather than the pick."},{"layer":"age","text":"At eighteen years the cake is well past the seven of the trade's saying, [tea in the first year, medicine at three, a treasure at seven](fujian-white:ageing). That is a saying, not a tested claim, and no agreed number of years makes a white tea aged. The years change the liquor too, which deepens and reddens as the tea ages."}],"brewing":{"layer":"brewing","text":"Gongfu style, use about 1 gram of leaf to 15 to 25 ml of water, for example 5 grams in a 100 to 110 ml gaiwan; weigh it, since the leaf is light and bulky. Silver Needle and young, delicate tea take water below the boil, about 75 to 90°C; older, leafier or aged tea takes water at or near the boil. Start with a steep of 10 to 45 seconds and add a few seconds each round. An aged cake is often rinsed quickly first, and older pressed tea can be simmered on the stove, about 5 grams to 500 ml for 3 to 10 minutes; young, delicate tea is not."},"notice":{"layer":"notice","styleName":"aged Fujian white","text":"Jujube or dried dates, herbs and medicine, wood, honey and dried fruit, a deeper, redder liquor, a thicker, rounder body, and less lift in the scent than a young tea."},"missing":[]},
  "a3ab643a-2ff0-40a0-969a-69892ce7f15d": {"productId":"a3ab643a-2ff0-40a0-969a-69892ce7f15d","paragraphs":[{"layer":"lot","text":"This loose leaf comes from Yunnan, picked from trees growing wild in forest that were never planted, pruned or managed. Its name, yesheng, means wild growing, and the leaf it gives is irregular, shaped by the forest around each tree rather than by a farmer's hand."},{"layer":"type","text":"It is made as [raw pu’er](sheng:identity): picked, withered and fried in a wok to [kill the green](sheng:making), then rolled and dried in the sun. The leaf is never dried with hot air afterwards, so some of its own activity survives, and that is what lets it keep [changing through storage](sheng:aging) for years. Left unpressed, it reaches the drinker much as the [rough tea, or maocha](sheng:processing), that other raw pu’er begins from."}],"brewing":{"layer":"brewing","text":"Young raw pu’er takes water a little off the boil, about 85 to 95°C, because hotter water draws out more of its bitterness; an aged one takes 95°C to boiling. A common start is about 7 grams to 100 ml and a quick rinse of a few seconds, then a first steep of ten to fifteen seconds, adding a few seconds each round. A good raw tea gives eight to ten cups or more."},"notice":{"layer":"notice","styleName":"Sheng Pu’er","text":"In young raw pu’er, a bitter, drying bite that turns into a returning sweetness, a feel in the throat that makes the mouth water, and fresh, floral or fruity notes such as apricot or plum. Tea kept in humid storage can carry a damp, earthy storage taste."},"missing":[]},
  "a3e29766-eaa5-49c1-9ac7-15fc9d0fe3d2": {"productId":"a3e29766-eaa5-49c1-9ac7-15fc9d0fe3d2","paragraphs":[{"layer":"lot","text":"A loose [Liu Bao](liu-bao:definition) from the 1990s, kept in Guangzhou and stored the old way. It was not pressed into cakes. The leaf was [packed into bamboo baskets](liu-bao:making-traditional) lined with bamboo leaves, and the basket lets the tea breathe, so it goes on changing through the decades it rests."},{"layer":"place","text":"Liu Bao is the [dark tea](dark:definition) of [Guangxi](guangxi:where-it-is), named for Liubao town in Cangwu County, near Wuzhou. Its leaf is piled after it is made, so warmth, moisture and microbes can slowly change it. The region's [warm, wet climate](guangxi:land-and-climate) is part of the reason it is made here: the trade links that steady damp to the slow ageing the style is kept for."},{"layer":"age","text":"At over thirty years, this lot is well past the ten the trade needs before it counts a Liu Bao as [aged](liu-bao:age-aged), and how a tea was stored matters as much as how long. Guangzhou has long been part of the style's story. The tea went by boat down the river to Wuzhou, on to Guangzhou, and out by sea to the Chinese workers of the [Southeast Asian tin mines](liu-bao:nanyang-trade)."}],"brewing":{"layer":"brewing","text":"Liu Bao takes very hot or boiling water, because its leaf is dense and gives up its depth slowly. Rinse it once or twice and pour the rinse away. Use about 5 to 8 grams to 100 ml, start with steeps of five to fifteen seconds and add a few seconds each round; a good Liu Bao gives ten cups or more."},"notice":{"layer":"notice","styleName":"aged Liu Bao","text":"A deep red, thick cup with woody, herbal and betel nut notes; tea several decades old is often described with ginseng and camphor."},"missing":[]},
  "a488b5ae-b5e1-45e3-bec0-9ec55839aedd": {"productId":"a488b5ae-b5e1-45e3-bec0-9ec55839aedd","paragraphs":[{"layer":"lot","text":"A cake of [raw pu’er](sheng:identity) from Yunnan, picked in the spring of 2023 and pressed under a stone. It began as [maocha](sheng:making): leaf fried in a wok to kill the green, rolled, then dried in the sun rather than by hot air, so enough of its own activity survives to keep it changing for years. Pressing under a stone leaves [a looser cake](sheng:pressing) than a hydraulic press would, and a looser cake changes faster."},{"layer":"age","text":"At three years it is still a [young raw pu’er](sheng:age-young), early in the slow change that sheng goes through [in storage](sheng:aging) instead of shou’s rapid fermentation. Heat and humidity decide how fast that change runs, which is why [where a cake is kept](sheng:storage) becomes part of its history."}],"brewing":{"layer":"brewing","text":"Pry the leaf off a cake or brick in chunks with a pick or knife, from the surface and toward the centre, rather than crumbling it. A mix of larger pieces and smaller ones brews evenly. Young raw pu’er takes water a little off the boil, about 85 to 95°C, because hotter water draws out more of its bitterness; an aged one takes 95°C to boiling. A common start is about 7 grams to 100 ml and a quick rinse of a few seconds, then a first steep of ten to fifteen seconds, adding a few seconds each round. A good raw tea gives eight to ten cups or more."},"notice":{"layer":"notice","styleName":"Sheng Pu’er","text":"In young raw pu’er, a bitter, drying bite that turns into a returning sweetness, a feel in the throat that makes the mouth water, and fresh, floral or fruity notes such as apricot or plum. Tea kept in humid storage can carry a damp, earthy storage taste."},"missing":[]},
  "ad149932-2312-4c3c-b21f-50f69677b721": {"productId":"ad149932-2312-4c3c-b21f-50f69677b721","paragraphs":[{"layer":"place","text":"A cake of [Fuding white tea](fujian-white:definition) from 2009. Fuding is a hilly coastal city in the north-east of Fujian, by the Zhejiang border. Its white tea carries a protected origin name in China and is tied to Taimu Mountain. Like all white tea, the leaf was only [withered and dried](white:definition), never fixed or rolled, before it was pressed."},{"layer":"age","text":"[Pressed white tea](fujian-white:cakes) was still new in 2009. Cakes began in that decade and spread around 2010, because a cake keeps and travels more easily than loose leaf. The year on a cake can mark when it was pressed rather than when it was picked. At seventeen years this cake is well past the seven of the trade's saying, [one year tea, three years medicine, seven years treasure](fujian-white:ageing). That is a saying, though, and no agreed number of years makes a white tea aged. As white tea ages, its liquor turns deeper and redder."}],"brewing":{"layer":"brewing","text":"Gongfu style, use about 1 gram of leaf to 15 to 25 ml of water, for example 5 grams in a 100 to 110 ml gaiwan; weigh it, since the leaf is light and bulky. Silver Needle and young, delicate tea take water below the boil, about 75 to 90°C; older, leafier or aged tea takes water at or near the boil. Start with a steep of 10 to 45 seconds and add a few seconds each round. An aged cake is often rinsed quickly first, and older pressed tea can be simmered on the stove, about 5 grams to 500 ml for 3 to 10 minutes; young, delicate tea is not."},"notice":{"layer":"notice","styleName":"aged Fujian white","text":"Jujube or dried dates, herbs and medicine, wood, honey and dried fruit, a deeper, redder liquor, a thicker, rounder body, and less lift in the scent than a young tea."},"missing":[]},
  "aea0e386-cb35-4ef9-91f4-3badd53c2c88": {"productId":"aea0e386-cb35-4ef9-91f4-3badd53c2c88","paragraphs":[{"layer":"place","text":"The leaf is from [Banzhang](banzhang:where-it-is), a group of tea villages on Bulang Mountain in the south of Menghai County, Xishuangbanna. The name covers more than one settlement: [Lao Banzhang](banzhang:old-and-new), the old village, and Xin Banzhang, which grew out of it. As a [market name](banzhang:on-a-label), Banzhang rarely says which of the two is meant."},{"layer":"type","text":"These are [tea heads](tea-heads:definition), the dense clumps of leaf that knot together while [ripe pu’er](shou:definition) ferments in its [damp pile](shou:wet-piling). They are sorted out once the pile is done and kept loose, apart from the numbered grades of loose ripe tea."},{"layer":"age","text":"Made in 2000, these heads are now twenty-six years old, well into what the trade counts as [aged ripe pu’er](shou:age-aged). The leaf keeps changing slowly with the air and moisture around it, which is why storage shapes it as much as the years do."}],"brewing":{"layer":"brewing","text":"Ripe pu’er takes boiling water: fermented, tightly packed leaf needs full heat to open, and it does not scald the way green tea can. A common start is about 7 grams to 100 ml and one quick rinse, which wakes the leaf and carries off dust and any pile smell. Then short steeps that lengthen as the leaf opens, so the cup stays clear rather than heavy; it gives eight or more good cups."},"notice":{"layer":"notice","styleName":"aged ripe pu’er","text":"A smooth, deep cup with woody, date-like or medicinal notes, which the trade calls aged aroma."},"missing":[]},
  "b05e2498-389d-4663-ba1f-46a0eb4c1b11": {"productId":"b05e2498-389d-4663-ba1f-46a0eb4c1b11","paragraphs":[{"layer":"lot","text":"A [red tea](red:definition) from Lincang. Its maker, Shangming Private Reserve Tea, labels it single-tree ancient wild red: leaf from one tree over 600 years old, fully oxidised, then finished by charcoal roasting, a [final drying](dian-hong:making) over heat that fixes the leaf once oxidation is done."},{"layer":"type","text":"Lincang, in the south-west of Yunnan, holds Fengqing County, the home of [Dian Hong](dian-hong:definition), the red tea made from the province's large-leaf trees. Red tea from [old trees](dian-hong:old-tree-and-sun-dried) is a newer branch sold under the Yunnan red name. There is no agreed standard for it, and the trade has not settled whether it belongs to Dian Hong at all."}],"brewing":{"layer":"brewing","text":"Dian Hong takes hot water, roughly 90 to 100°C. A common start is about 5 grams to 100 ml, with short steeps that lengthen slowly as the leaf opens."},"notice":{"layer":"notice","styleName":"Dian Hong","text":"A full, sweet cup, often described as malty, with chocolate or cocoa and honey notes and sometimes something floral. The liquor runs golden to bright red, and a good grade has little bitterness."},"missing":[]},
  "b0d36eda-3756-40af-a285-24dee2610445": {"productId":"b0d36eda-3756-40af-a285-24dee2610445","paragraphs":[{"layer":"lot","text":"Wan Zhi, \"ten thousand branches\", is a cake of [ripe pu’er](shou:definition) from Yunnan, made in 1980. Its leaf went through [wet piling](shou:wet-piling) before it was pressed: it was dampened and heaped so that heat, moisture and microbes could work on it. That places it in the style’s first decade, only seven years after a team from Yunnan’s factories [went to Guangzhou to learn the pile](shou:piling-1973) in 1973."},{"layer":"age","text":"At forty-six years it is long past the point where the trade counts a ripe pu’er as [aged](shou:age-aged). The leaf has gone on changing all that time with the air and moisture around it, so how it was kept matters as much as the years."}],"brewing":{"layer":"brewing","text":"From a cake, brick or tuo, ease a piece off along the edge with a pick rather than snapping it. Whole leaves give up their flavour steadily; broken ones release it all at once and cloud the cup. Ripe pu’er takes boiling water: fermented, tightly packed leaf needs full heat to open, and it does not scald the way green tea can. A common start is about 7 grams to 100 ml and one quick rinse, which wakes the leaf and carries off dust and any pile smell. Then short steeps that lengthen as the leaf opens, so the cup stays clear rather than heavy; it gives eight or more good cups."},"notice":{"layer":"notice","styleName":"aged ripe pu’er","text":"A smooth, deep cup with woody, date-like or medicinal notes, which the trade calls aged aroma."},"missing":[]},
  "b0edf4a1-b7c1-48be-aced-3911a8f0a35d": {"productId":"b0edf4a1-b7c1-48be-aced-3911a8f0a35d","paragraphs":[{"layer":"place","text":"A [dark tea](dark:definition) made in 1983 from leaf grown in [Taiwan](taiwan:on-a-label). The label names only the island, not a mountain or a township, so where on it the leaf grew is not recorded. The island's tea first came across the strait from Fujian, and its trade is built on [oolong](taiwan:known-for)."},{"layer":"age","text":"Dark tea is leaf that, once heated and rolled, is left to change in warmth and moisture, and it is [made to be kept](dark:ageing). The trade values it more as the years pass, and storage sets the pace: kept cool and dry, the change is slow; kept warmer and more humid, it is faster. At forty-three years, this tea has had more than four decades of that change."}],"brewing":{"layer":"brewing","text":"Dark tea takes boiling water. Its leaf is mature and dense, so it gives up its flavour slowly and is hard to overbrew. Rinse it first with boiling water and pour that off within seconds: the rinse wakes the leaf and washes off dust and any stale smell from storage, and an old tea may take a second rinse. In a small pot use plenty of leaf, about 7 grams to 120 ml, then steep very briefly at first and a little longer each time; a good dark tea gives many cups."},"notice":{"layer":"notice","styleName":"dark tea","text":"A smooth, mellow cup with low bitterness and a deep red colour, often sweet and woody or earthy, sometimes with herbal or medicinal notes. A young dark tea can still smell of the pile or of storage; an aged one is usually redder, sweeter and thicker."},"missing":[]},
  "b11a8bad-89d9-4518-9406-25145d4c6e2c": {"productId":"b11a8bad-89d9-4518-9406-25145d4c6e2c","paragraphs":[{"layer":"named","text":"San He means Three Cranes, the [trademark](three-cranes:definition) of Wuzhou Tea Factory. The birds on it come from Hegang Tower, which stands beside the works. The factory opened for the export trade in 1953 and registered the [Three Cranes mark](san-he-liu-bao:three-cranes) in October 1991. This [Liu Bao](liu-bao:definition) comes from that same decade."},{"layer":"named","text":"The factory has its own way of working the leaf. Since 1958 it has used [cold-water piling](san-he-liu-bao:cold-water-piling): workers moisten the leaves and heap them to ferment, and the method has been taught from one technician to the next on shift. After fermentation the tea rests in a [brick-and-timber warehouse](san-he-liu-bao:aging-warehouse), begun the year the factory opened, where porous wooden boards help keep moisture and temperature steady."},{"layer":"age","text":"The shop records Guangzhou as one of the places this tea was stored. At thirty-one years it is well past the ten after which the trade counts a Liu Bao as [aged](liu-bao:age-aged), and how it was kept matters as much as how long."}],"brewing":{"layer":"brewing","text":"Liu Bao takes very hot or boiling water, because its leaf is dense and gives up its depth slowly. Rinse it once or twice and pour the rinse away. Use about 5 to 8 grams to 100 ml, start with steeps of five to fifteen seconds and add a few seconds each round; a good Liu Bao gives ten cups or more."},"notice":{"layer":"notice","styleName":"aged Liu Bao","text":"A deep red, thick cup with woody, herbal and betel nut notes; tea several decades old is often described with ginseng and camphor."},"missing":[]},
  "b2057039-6c27-4ebf-8385-930bb15cdb4f": {"productId":"b2057039-6c27-4ebf-8385-930bb15cdb4f","paragraphs":[{"layer":"lot","text":"A [red tea](red:definition) from Yunnan, made in 2006 and pressed into a cake. Red tea is the fully oxidised kind: once the leaf's cells are broken, its own enzymes turn it from green to reddish brown before it is dried."},{"layer":"type","text":"Red tea from Yunnan goes by the name [Dian Hong](dian-hong:definition) and is made from the province's large-leaf trees. Feng Shaoqiu made a [trial batch](dian-hong:history) in Shunning, now Fengqing, in late 1938, when the war had cut China off from its eastern tea regions."},{"layer":"age","text":"Dian Hong is usually [kept for freshness](dian-hong:ageing) rather than for age, and the trade treats it as best in its first one to three years. This cake was made in 2006, twenty years ago, so it is long past that window."}],"brewing":{"layer":"brewing","text":"Dian Hong takes hot water, roughly 90 to 100°C. A common start is about 5 grams to 100 ml, with short steeps that lengthen slowly as the leaf opens."},"notice":{"layer":"notice","styleName":"Dian Hong","text":"A full, sweet cup, often described as malty, with chocolate or cocoa and honey notes and sometimes something floral. The liquor runs golden to bright red, and a good grade has little bitterness."},"missing":[]},
  "b33c86ab-f899-4a67-a702-b97001851a56": {"productId":"b33c86ab-f899-4a67-a702-b97001851a56","paragraphs":[{"layer":"type","text":"This is [raw pu’er](sheng:identity) from Yunnan, made in 2005 and left loose rather than pressed. Raw pu’er is never hot-air dried after the wok, so some of the leaf’s own activity survives, and that is what lets the [rough tea, or maocha](sheng:making), keep changing for years."},{"layer":"age","text":"At twenty-one years it has passed the point where many in the trade begin to call raw pu’er [aged](sheng:ageing), though some count from ten. Without shou’s quick fermentation, all of that change has come slowly, [in storage](sheng:aging), so how and where it was kept is part of this tea’s history as much as the years are."}],"brewing":{"layer":"brewing","text":"Young raw pu’er takes water a little off the boil, about 85 to 95°C, because hotter water draws out more of its bitterness; an aged one takes 95°C to boiling. A common start is about 7 grams to 100 ml and a quick rinse of a few seconds, then a first steep of ten to fifteen seconds, adding a few seconds each round. A good raw tea gives eight to ten cups or more."},"notice":{"layer":"notice","styleName":"aged Sheng Pu’er","text":"A smoother, thicker, sweeter cup with woody, herbal and camphor notes and something of dried dates or dark fruit."},"missing":[]},
  "b56b1acc-7542-44e6-9f64-35e99ae91eef": {"productId":"b56b1acc-7542-44e6-9f64-35e99ae91eef","paragraphs":[{"layer":"lot","text":"A cake of [raw pu’er](sheng:identity) from Yunnan, dated 1976 and infused with ginseng. Raw pu’er is the undarkened branch of the style, never given the quick fermentation that makes shou, so whatever this cake is now, it became through time."},{"layer":"age","text":"At fifty years it sits far past both the ten years some count as [aged raw pu’er](sheng:ageing) and the twenty or more that many wait for. Over that span a well-kept raw cake moves in the cup from pale gold toward amber and then red. Because the change happens [slowly in storage](sheng:aging), affecting leaf and liquor alike, the places this cake was kept belong to its history."}],"brewing":{"layer":"brewing","text":"Pry the leaf off a cake or brick in chunks with a pick or knife, from the surface and toward the centre, rather than crumbling it. A mix of larger pieces and smaller ones brews evenly. Young raw pu’er takes water a little off the boil, about 85 to 95°C, because hotter water draws out more of its bitterness; an aged one takes 95°C to boiling. A common start is about 7 grams to 100 ml and a quick rinse of a few seconds, then a first steep of ten to fifteen seconds, adding a few seconds each round. A good raw tea gives eight to ten cups or more."},"notice":{"layer":"notice","styleName":"aged Sheng Pu’er","text":"A smoother, thicker, sweeter cup with woody, herbal and camphor notes and something of dried dates or dark fruit."},"missing":[]},
  "b6654adc-2754-4388-8e6b-f9c9660f2f96": {"productId":"b6654adc-2754-4388-8e6b-f9c9660f2f96","paragraphs":[{"layer":"type","text":"Yun Shen Chu is a cake of [Yunnan white](yunnan-white:definition), white tea made from Yunnan’s large-leaf tea plants rather than from the smaller bush cultivars of Fujian. The style is [new to the market](yunnan-white:history): its trade has grown only in recent years, though local practice may be older."},{"layer":"type","text":"It is made the [white tea](white:definition) way, in the fewest steps. The leaf is only withered and dried, never heated to stop its change and never rolled, so it keeps its natural shape. In Yunnan the [withering](yunnan-white:making) is done indoors or in shade rather than under the midday sun, and the leaf then dries in the air, without the final low bake Fujian white usually gets. Once dried, the leaf can be sold loose or, as here, pressed into the cake shape of pu’er."}],"brewing":{"layer":"brewing","text":"Yunnan white is brewed gently, as a white tea is, in a gaiwan or small pot, and it gives many infusions; the leaf holds up well."},"notice":{"layer":"notice","styleName":"Yunnan white","text":"A honeyed, sweet cup, often richer and fuller than Fujian white, with little bitterness, sometimes fruit like apricot or melon and a hay or herbal note. Yabao is sweet and silky, often with pine or herbal notes."},"missing":[]},
  "b742891e-c6b5-46b7-877b-e7b68391b51d": {"productId":"b742891e-c6b5-46b7-877b-e7b68391b51d","paragraphs":[{"layer":"lot","text":"This is a [Zhengshan Xiaozhong](lapsang:definition), the [red tea](red:definition) of Tongmu village in the Wuyi Mountains, dated 1920. It was pine smoked the traditional way of the early Republican era. In that way the leaf dries over a fire of local pine in a [qinglou](lapsang:smoke), a wooden house of several floors with the fire at the bottom and the leaf on bamboo mats above, so the heat and smoke rise through it."},{"layer":"place","text":"Tongmu sits on the high northern edge of the [Wuyi range](wuyi-mountains:two-teas), close to the Jiangxi border, in forested country that is now protected. It is the village usually given as the [birthplace of black tea](fujian:history). Its tea first reached Europe through Dutch and then British trade, under names such as [Bohea and Souchong](lapsang:history)."},{"layer":"age","text":"At a hundred and six years, this tea stands outside any named tradition. Lapsang has no recognised [tradition of long ageing](lapsang:ageing), and no category of red tea aged for decades is described."}],"brewing":{"layer":"brewing","text":"In a cup or pot, use about 3 grams for 240 ml, with water at 90 to 100°C, and steep about two to five minutes, usually around three. Gongfu style, use about 5 grams in a 100 to 110 ml gaiwan or pot, with short steeps that grow a little longer each round. Too hot or too long and the smoke turns harsh and bitter and covers the tea."},"notice":{"layer":"notice","styleName":"aged Lapsang Souchong","text":"The smoke softer and further back, with dried fruit coming forward."},"missing":[]},
  "b842eeec-15be-4865-8b8c-a158364a9a65": {"productId":"b842eeec-15be-4865-8b8c-a158364a9a65","paragraphs":[{"layer":"type","text":"A loose [raw pu’er](sheng:identity) from Yunnan, made in 2005. Like all raw pu’er it began as [maocha](sheng:making), the rough tea: leaf from large-leaf trees, fried in a wok to kill the green, rolled and dried in the sun. It is never dried with hot air afterwards, so some of the leaf’s own activity survives, and that is what lets the tea keep changing for years."},{"layer":"age","text":"At twenty-one years it has passed both of the trade’s lines for [aged raw pu’er](sheng:ageing): some count from ten years, many wait for twenty or more. The change comes as much from [storage](sheng:storage) as from time. Slow oxidation and the work of microbes carry it, and heat and humidity decide how fast they run."}],"brewing":{"layer":"brewing","text":"Young raw pu’er takes water a little off the boil, about 85 to 95°C, because hotter water draws out more of its bitterness; an aged one takes 95°C to boiling. A common start is about 7 grams to 100 ml and a quick rinse of a few seconds, then a first steep of ten to fifteen seconds, adding a few seconds each round. A good raw tea gives eight to ten cups or more."},"notice":{"layer":"notice","styleName":"aged Sheng Pu’er","text":"A smoother, thicker, sweeter cup with woody, herbal and camphor notes and something of dried dates or dark fruit."},"missing":[]},
  "b8a58f68-5bd9-4143-b84c-92f3235f7c60": {"productId":"b8a58f68-5bd9-4143-b84c-92f3235f7c60","paragraphs":[{"layer":"age","text":"This [Taiwan oolong](taiwan-oolong:definition) dates from 1970, which makes it fifty-six years old. The island has a tradition of keeping oolong for years as [lao cha](taiwan-oolong:ageing), old tea: leaf is put away well roasted and dry, then roasted again at low heat from time to time to drive out the moisture it takes in, and stored cool, dark and sealed. No standard says when an oolong becomes old. Those who give a figure put it somewhere between ten and thirty years, and this tea has gone well past both."},{"layer":"type","text":"Oolong reached the island with settlers from Fujian, who brought the plants and the craft, and it was grown for sale in the nineteenth century. From the 1860s it was sold abroad as [Formosa Oolong](taiwan-oolong:history), and tea stayed one of the island's leading exports through the years of Japanese rule."}],"brewing":{"layer":"brewing","text":"Ball-rolled Taiwan oolong takes hot water, about 90 to 100°C, a fairly generous amount of leaf and short steeps; the balls open slowly and give many infusions. Roasted Dong Ding takes water from about 95°C to a full boil. Aged oolong takes very hot water, in a pot that holds its heat, clay above all. Oriental Beauty is the exception and takes cooler water, about 80 to 95°C."},"notice":{"layer":"notice","styleName":"aged Taiwan oolong","text":"A smooth, mellow, thick cup with little astringency, often plum or prune, sometimes something like medicinal herbs or ginseng, and an amber to red-brown liquor."},"missing":[]},
  "b8f48865-a48a-4aed-a99d-126fdd4faf17": {"productId":"b8f48865-a48a-4aed-a99d-126fdd4faf17","paragraphs":[{"layer":"place","text":"[Anxi](anxi:where-it-is) is a county in southern Fujian, inland from the coast and north of Xiamen, on the southern side of the Daiyun mountains. On this tea the name says [where the leaf grew](anxi:on-a-label), not its style or grade. The tea dates from 1988. Anxi was then still one of the poorer counties in Fujian, and the [Tieguanyin boom](anxi:history) that changed that had not yet come."},{"layer":"age","text":"It was also made before the [light green style](tieguanyin:styles) took over in Anxi in the 1990s, at a time when the roasted style, the older of the two, still held. The trade has a name for Tieguanyin kept for years: chenxiang, or old Tie. This one is thirty-eight years old. The light kind goes stale quickly, and the heavier, charcoal roasted kind is the one [kept for years](tieguanyin:ageing), sealed, dry and dark, until the fire of the roast settles."},{"layer":"type","text":"[Tieguanyin](tieguanyin:definition) is both a cultivar and the partly oxidised [oolong](oolong:definition) made from it. The leaf is rolled into tight balls by [wrapping it in cloth](tieguanyin:making), pressing it and drying it a little, again and again, with each round making it tighter."}],"brewing":{"layer":"brewing","text":"Tieguanyin is usually brewed gongfu style with water at or near the boil, about 95 to 100°C; the light green style is often taken a little cooler, about 85 to 95°C. Use about 4 to 8 grams of leaf in a 100 to 150 ml gaiwan or pot, about a third full. A quick rinse, poured off at once, is common. Steeps start short, about 10 to 30 seconds, and grow a few seconds longer each round, and a good Tieguanyin gives about six to eight. In a larger pot, use about 2.5 to 5 grams for 240 to 350 ml and steep two to three minutes."},"notice":{"layer":"notice","styleName":"aged Tieguanyin","text":"A smoother, rounder, softer cup with the fire gone, a liquor turned orange-red or reddish-brown, and often a soft fruity sourness."},"missing":[]},
  "ba5a1e02-ac6f-4c5c-81bd-aed428034809": {"productId":"ba5a1e02-ac6f-4c5c-81bd-aed428034809","paragraphs":[{"layer":"place","text":"This loose leaf comes from [Yiwu](greater-yiwu:where-it-is), in the north of Mengla County in Xishuangbanna, on the east side of the Lancang River. Yiwu is one of the old Six Famous Tea Mountains, and its town has long been where the tea of the surrounding villages is gathered and processed."},{"layer":"type","text":"It is [Yunnan white](yunnan-white:definition), made from the province's large-leaf tea plants rather than the bush cultivars of Fujian. The leaf was only [withered and dried](yunnan-white:making). It was withered indoors or in shade and then dried by air. It was never heated to stop its change, never rolled, and never given the low final bake that Fujian white usually gets."},{"layer":"age","text":"Made in 2015, it has now been kept for eleven years. There is no settled view of how long Yunnan white should be kept. Some keep it for years, others prefer to drink it within a few, and nobody agrees on how it compares with [aged Fujian white](yunnan-white:ageing)."}],"brewing":{"layer":"brewing","text":"Yunnan white is brewed gently, as a white tea is, in a gaiwan or small pot, and it gives many infusions; the leaf holds up well."},"notice":{"layer":"notice","styleName":"aged white tea","text":"Honey, dried fruit or jujube, something herbal and woody, a rounder, thicker body and a darker, redder liquor, with less lift in the aroma than a young tea."},"missing":[]},
  "bac9ea9d-0697-4f26-a1be-afcebd1b177c": {"productId":"bac9ea9d-0697-4f26-a1be-afcebd1b177c","paragraphs":[{"layer":"type","text":"A cake of [raw pu’er](sheng:identity) from Yunnan, made in 2010. Unlike shou, it was never given a fast fermentation. The leaf was fried in a wok to kill the green, then [dried in the sun](sheng:making) rather than by hot air, so some of its own activity survived. That is what has let it keep changing in the cake ever since."},{"layer":"age","text":"At sixteen years it sits between the trade’s two answers to when [raw pu’er counts as aged](sheng:ageing): past the ten years some accept, short of the twenty many wait for. How far it has come depends on how it was pressed and where it was kept, because [heat and humidity](sheng:storage) set the pace of that change."}],"brewing":{"layer":"brewing","text":"Pry the leaf off a cake or brick in chunks with a pick or knife, from the surface and toward the centre, rather than crumbling it. A mix of larger pieces and smaller ones brews evenly. Young raw pu’er takes water a little off the boil, about 85 to 95°C, because hotter water draws out more of its bitterness; an aged one takes 95°C to boiling. A common start is about 7 grams to 100 ml and a quick rinse of a few seconds, then a first steep of ten to fifteen seconds, adding a few seconds each round. A good raw tea gives eight to ten cups or more."},"notice":{"layer":"notice","styleName":"aged Sheng Pu’er","text":"A smoother, thicker, sweeter cup with woody, herbal and camphor notes and something of dried dates or dark fruit."},"missing":[]},
  "bb692acb-b4a0-4114-afa8-c9644140eb5f": {"productId":"bb692acb-b4a0-4114-afa8-c9644140eb5f","paragraphs":[{"layer":"lot","text":"This loose ripe pu’er comes from the highlands of northern Vietnam, near the Yunnan border. Ripe pu’er is made by fermenting tea leaves in a damp pile, a process called [wet piling](shou:wet-piling)."}],"brewing":{"layer":"brewing","text":"Ripe pu’er takes boiling water: fermented, tightly packed leaf needs full heat to open, and it does not scald the way green tea can. A common start is about 7 grams to 100 ml and one quick rinse, which wakes the leaf and carries off dust and any pile smell. Then short steeps that lengthen as the leaf opens, so the cup stays clear rather than heavy; it gives eight or more good cups."},"notice":{"layer":"notice","styleName":"ripe pu’er","text":"A smooth, sweet cup with earthy or woody notes. A young ripe tea can carry a faint smell of the pile, which fades with airing or in the first steeps."},"missing":[]},
  "bd519b7f-003b-4c4c-acf2-c6adb41b5511": {"productId":"bd519b7f-003b-4c4c-acf2-c6adb41b5511","paragraphs":[{"layer":"age","text":"Raw pu’er from Yunnan, made in 1980 and kept as loose leaf. At forty-six years it sits well past any line the trade draws for [aged](sheng:ageing): some count from ten years, many wait for twenty or more."},{"layer":"type","text":"[Sheng](sheng:identity) is never given the quick fermentation of shou, so [it changes slowly in storage](sheng:aging), and the years it has been kept become part of its history. It was never pressed: a tight, large cake changes slowly, while [loose or small tea](sheng:pressing) changes sooner."}],"brewing":{"layer":"brewing","text":"Young raw pu’er takes water a little off the boil, about 85 to 95°C, because hotter water draws out more of its bitterness; an aged one takes 95°C to boiling. A common start is about 7 grams to 100 ml and a quick rinse of a few seconds, then a first steep of ten to fifteen seconds, adding a few seconds each round. A good raw tea gives eight to ten cups or more."},"notice":{"layer":"notice","styleName":"aged Sheng Pu’er","text":"A smoother, thicker, sweeter cup with woody, herbal and camphor notes and something of dried dates or dark fruit."},"missing":[]},
  "bed57179-9625-4d7c-b7e4-2ad2c138dbe3": {"productId":"bed57179-9625-4d7c-b7e4-2ad2c138dbe3","paragraphs":[{"layer":"place","text":"A loose [Taiwan oolong](taiwan-oolong:definition) from Zhudong, made in 1983. The island's oolong plants and craft came over from Fujian with its settlers, and [oolong](oolong:definition) itself is the partly oxidised tea, standing between green tea and red."},{"layer":"age","text":"At forty-three years it belongs to Taiwan’s tradition of keeping oolong, called [lao cha](taiwan-oolong:ageing), old tea. Tea chosen for keeping starts well roasted and dry, and keepers roast it again at low heat from time to time to drive out the moisture it takes in. It is stored cool, dry, dark and sealed. No standard says when an oolong becomes old. Those who give a figure put it between ten and thirty years, and this tea is well past the longer of the two."}],"brewing":{"layer":"brewing","text":"Ball-rolled Taiwan oolong takes hot water, about 90 to 100°C, a fairly generous amount of leaf and short steeps; the balls open slowly and give many infusions. Roasted Dong Ding takes water from about 95°C to a full boil. Aged oolong takes very hot water, in a pot that holds its heat, clay above all. Oriental Beauty is the exception and takes cooler water, about 80 to 95°C."},"notice":{"layer":"notice","styleName":"aged Taiwan oolong","text":"A smooth, mellow, thick cup with little astringency, often plum or prune, sometimes something like medicinal herbs or ginseng, and an amber to red-brown liquor."},"missing":[]},
  "c015f973-1e2e-4bef-bd04-85093fa7bfd5": {"productId":"c015f973-1e2e-4bef-bd04-85093fa7bfd5","paragraphs":[{"layer":"place","text":"A [raw pu’er](sheng:identity) cake made in 1996 from leaf grown in Menghai County, Yunnan. [Menghai](menghai-county:county-and-factory) on a label can mean the county or the factory that stands in it. This record names the county as the leaf’s origin and says nothing of a maker."},{"layer":"age","text":"Thirty years on, it is past the point where the trade says [raw pu’er counts as aged](sheng:ageing). Some put that point at ten years, and many wait for twenty or more."},{"layer":"type","text":"Unlike shou, it was never put through a fast fermentation, so it has [changed slowly](sheng:aging) in [storage](sheng:storage). Oxidation and microbes do that work, which is why warmth and humidity set how fast a tea changes. [Pressing](sheng:pressing) began so tea would travel well on the old trade routes. It also shapes ageing, since a tight cake changes more slowly than a loose one."}],"brewing":{"layer":"brewing","text":"Pry the leaf off a cake or brick in chunks with a pick or knife, from the surface and toward the centre, rather than crumbling it. A mix of larger pieces and smaller ones brews evenly. Young raw pu’er takes water a little off the boil, about 85 to 95°C, because hotter water draws out more of its bitterness; an aged one takes 95°C to boiling. A common start is about 7 grams to 100 ml and a quick rinse of a few seconds, then a first steep of ten to fifteen seconds, adding a few seconds each round. A good raw tea gives eight to ten cups or more."},"notice":{"layer":"notice","styleName":"aged Sheng Pu’er","text":"A smoother, thicker, sweeter cup with woody, herbal and camphor notes and something of dried dates or dark fruit."},"missing":[]},
  "c0eeb3ed-cbc3-4ca1-8daa-8509593b02cb": {"productId":"c0eeb3ed-cbc3-4ca1-8daa-8509593b02cb","paragraphs":[{"layer":"age","text":"A cake of [raw pu’er](sheng:identity) from Yunnan, made in 2005 and now twenty-one years old. That puts it past both lines the trade draws for [aged raw pu’er](sheng:ageing): some count from ten years, many wait for twenty or more."},{"layer":"type","text":"Raw pu’er is never given shou’s rapid fermentation. The leaf is [fried in a wok to kill the green](sheng:making) but never hot-air dried afterwards, so some of its own activity survives, and that is what lets the tea keep changing for years. How tightly a [cake is pressed](sheng:pressing) and how warm and damp it is kept decide how fast that change runs, so [storage](sheng:storage) belongs to this cake’s history as much as its years do."}],"brewing":{"layer":"brewing","text":"Pry the leaf off a cake or brick in chunks with a pick or knife, from the surface and toward the centre, rather than crumbling it. A mix of larger pieces and smaller ones brews evenly. Young raw pu’er takes water a little off the boil, about 85 to 95°C, because hotter water draws out more of its bitterness; an aged one takes 95°C to boiling. A common start is about 7 grams to 100 ml and a quick rinse of a few seconds, then a first steep of ten to fifteen seconds, adding a few seconds each round. A good raw tea gives eight to ten cups or more."},"notice":{"layer":"notice","styleName":"aged Sheng Pu’er","text":"A smoother, thicker, sweeter cup with woody, herbal and camphor notes and something of dried dates or dark fruit."},"missing":[]},
  "c2525628-57bc-40df-824f-05c225930f74": {"productId":"c2525628-57bc-40df-824f-05c225930f74","paragraphs":[{"layer":"place","text":"[Kunlu Mountain](kunlu-mountain:where) is a spur of the Wuliang range in Ning’er County, Pu’er City, with heights given at about 1,410 to 2,271 metres. Its [old tea trees](kunlu-mountain:trees) cover a little over 10,000 mu. They stand tall and mostly unpruned, with wild, transitional and planted types growing side by side, and the trade knows the mountain for them."},{"layer":"type","text":"This is [raw pu’er](sheng:identity) from 2007. It was never given shou’s fast fermentation, so its character changes slowly over years. Raw pu’er is wok fired and then sun dried into [maocha](sheng:making), and this tea was left loose rather than pressed into a cake."},{"layer":"age","text":"At nineteen years it has had almost two decades of [change in storage](sheng:aging), and it sits on the line the trade still argues over. Some call raw pu’er [aged](sheng:ageing) after ten years, and many wait for twenty or more."}],"brewing":{"layer":"brewing","text":"Young raw pu’er takes water a little off the boil, about 85 to 95°C, because hotter water draws out more of its bitterness; an aged one takes 95°C to boiling. A common start is about 7 grams to 100 ml and a quick rinse of a few seconds, then a first steep of ten to fifteen seconds, adding a few seconds each round. A good raw tea gives eight to ten cups or more."},"notice":{"layer":"notice","styleName":"aged Sheng Pu’er","text":"A smoother, thicker, sweeter cup with woody, herbal and camphor notes and something of dried dates or dark fruit."},"missing":[]},
  "c30e521a-e8dd-4eee-9d8d-ce4cdca40e1e": {"productId":"c30e521a-e8dd-4eee-9d8d-ce4cdca40e1e","paragraphs":[{"layer":"named","text":"[Ya Shi Xiang](dancong:ya-shi-xiang), duck dung in its Chinese name, is the market name for one line of Dancong, traced to Pingkengtou village. Most lists of the ten classic kinds leave it out, though it sells widely. In 2014 a second name, Yinhua Xiang, silver flower, was put forward, and many sellers keep the old one. Three stories explain the name, all told as stories: that it was chosen to put thieves off the bush, that it comes from the yellow local soil called duck dung soil, and that duck droppings lay on the bush."},{"layer":"place","text":"The leaf grows on [Phoenix Mountain](phoenix-mountain:where-it-is), the range in Chaozhou in eastern Guangdong, where gardens climb from low foothills to roughly 1,100 metres. Cloud and [mist](phoenix-mountain:mist-and-climate) sit on the upper slopes for much of the year and the nights are cool, so the bushes grow slowly. [Dancong](dancong:name) means single bush, the leaf of one bush made on its own, though today a named line is mostly grown from cuttings or grafts, so one name no longer means one tree. As an [oolong](oolong:definition), it is partly oxidised, between green tea and red."}],"brewing":{"layer":"brewing","text":"Brew it gongfu style in a small gaiwan or clay pot, with about 3 to 8 grams for 100 to 120 ml and hot water, about 88 to 100°C; Chinese accounts mostly say 95 to 100°C. A quick rinse is common. Steeps start at a few seconds and grow a few seconds each round, and a good Dancong gives about eight to fifteen. Too long, too hot or too much leaf and it turns bitter and astringent."},"notice":{"layer":"notice","styleName":"Phoenix Dancong","text":"Flowers above all, a sweetness that comes back after swallowing, a high scent that lasts, honey, often ripe fruit such as peach, and what the trade calls mountain rhyme, shan yun; a liquor from golden to orange-red or amber."},"missing":[]},
  "c5c84d4f-d6ac-4a5b-997b-cec70c45a350": {"productId":"c5c84d4f-d6ac-4a5b-997b-cec70c45a350","paragraphs":[{"layer":"place","text":"Huakang Oolong is an oolong grown in [Taiwan](taiwan:where-it-is), the island off the coast of Fujian. The record names only the island. That says where the leaf grew and nothing more: not the mountain, the height, the cultivar or the style. Where a seller names a mountain or township, that is the fuller claim."},{"layer":"type","text":"Oolong is the [partly oxidised tea](oolong:definition), standing between green tea and red. On the island most of it is lightly to moderately oxidised and rolled into balls, with [Qingxin oolong](taiwan-oolong:definition) the main cultivar and Jinxuan the other common one. The plants and the craft came with settlers from that coast. In the 1860s the Scottish merchant John Dodd, working with the Taipei merchant Li Chunsheng, sold the island's tea abroad as [Formosa Oolong](taiwan-oolong:history)."}],"brewing":{"layer":"brewing","text":"Ball-rolled Taiwan oolong takes hot water, about 90 to 100°C, a fairly generous amount of leaf and short steeps; the balls open slowly and give many infusions. Roasted Dong Ding takes water from about 95°C to a full boil. Aged oolong takes very hot water, in a pot that holds its heat, clay above all. Oriental Beauty is the exception and takes cooler water, about 80 to 95°C."},"notice":{"layer":"notice","styleName":"Taiwan oolong","text":"In light high mountain tea: a sweet, floral cup, often creamy or buttery, with little bitterness and a long sweet aftertaste. In roasted Dong Ding: caramel, ripe fruit, nuts and a toasted aroma. In Baozhong: floral notes and a clear, bright liquor. In Oriental Beauty: ripe fruit and honey, with little bitterness."},"missing":[]},
  "c81e326c-c1a9-42b9-867f-586bad4852fc": {"productId":"c81e326c-c1a9-42b9-867f-586bad4852fc","paragraphs":[{"layer":"type","text":"A loose oolong from China. [Oolong](oolong:definition) is the partly oxidised tea, standing between green tea, which is not oxidised at all, and red tea, which is oxidised all the way, and the range inside the type is wide."},{"layer":"type","text":"Where a given oolong sits in that range is set in the making. The leaf is withered until it is soft enough to handle, then [tossed in rounds](oolong:making) with rests between them: the knocking bruises its edges so they begin to oxidise, and the rests let the change spread slowly inward. High heat stops it at the point the maker wants, and the leaf is rolled and dried. How far it oxidises and how hard it is then [roasted](oolong:oxidation-and-roast) are two separate choices, and roasting lowers the moisture so the tea keeps."}],"brewing":{"layer":"brewing","text":"Oolong is most often brewed gongfu style, in a small gaiwan or clay pot with plenty of leaf and short steeps, and it stands many rounds. A common start is about 4 to 6 grams to 100 ml, with a first steep of roughly 5 to 15 seconds and 5 to 10 seconds more each round. Light, green-style oolong takes water a little off the boil, about 90 to 95°C; heavily oxidised, roasted and aged oolong takes water at a full boil. Many people pour a quick first rinse to wake tightly rolled leaf. In a larger pot, use less leaf and steep for a few minutes."},"notice":{"layer":"notice","styleName":"oolong","text":"In light, green-style oolong: floral and orchid notes, a creamy or buttery feel and a sweet aftertaste that lingers. In roasted and darker oolong: toasted grain and caramel, wood, stone fruit and a mineral, rock-like character."},"missing":[]},
  "c93e6e5a-cd4a-40a4-97e9-15fba5f6e251": {"productId":"c93e6e5a-cd4a-40a4-97e9-15fba5f6e251","paragraphs":[{"layer":"lot","text":"A large-format cake of [ripe pu’er](shou:definition) from Yunnan, pressed with dragon imagery."},{"layer":"type","text":"Before pressing, the leaf went through [wet piling](shou:wet-piling): wetted, heaped and covered so the heat of its own microbes could work on it, then turned about once a week to spread that heat and let air in. The pile is held below about 65°C, since hotter than that the leaf begins to char. The method was built to give in weeks what raw pu’er reached only after years of keeping, so a cake like this is ready to open now rather than after a long wait."}],"brewing":{"layer":"brewing","text":"From a cake, brick or tuo, ease a piece off along the edge with a pick rather than snapping it. Whole leaves give up their flavour steadily; broken ones release it all at once and cloud the cup. Ripe pu’er takes boiling water: fermented, tightly packed leaf needs full heat to open, and it does not scald the way green tea can. A common start is about 7 grams to 100 ml and one quick rinse, which wakes the leaf and carries off dust and any pile smell. Then short steeps that lengthen as the leaf opens, so the cup stays clear rather than heavy; it gives eight or more good cups."},"notice":{"layer":"notice","styleName":"ripe pu’er","text":"A smooth, sweet cup with earthy or woody notes. A young ripe tea can carry a faint smell of the pile, which fades with airing or in the first steeps."},"missing":[]},
  "c95f9820-09ef-4115-b987-4438bf2a2482": {"productId":"c95f9820-09ef-4115-b987-4438bf2a2482","paragraphs":[{"layer":"type","text":"[Rougui](yancha:rougui), cassia in Chinese, is a cultivar of the [Wuyi Mountains](wuyi-mountains:where-it-is), the range along the border of northern Fujian and Jiangxi. It dates from the Qing dynasty and is now one of the most widely planted teas in the area. The bushes there grow in [thin, stony soil](wuyi-mountains:nature) on ledges, in ravines and between rocks. The ground drains fast and mist settles on the slopes, which is why growth on the mountain is slow."},{"layer":"lot","text":"This leaf was made in the standard way for [Wuyi rock tea](yancha:definition). It was withered and rested, then twisted into long thin strips rather than rolled into balls, and finished with a [charcoal roast](yancha:making). The roast is done in several rounds, with rests of weeks or months between them, not in one pass. It dries the tea so that it keeps, and each stage has to be managed with care."}],"brewing":{"layer":"brewing","text":"Wuyi tea is usually brewed gongfu style with water at or near the boil, about 95 to 100°C, and about 5 to 8 grams of leaf in a 100 to 120 ml gaiwan, a third to a half full. A quick rinse, poured off at once, is common. Steeps start short, about 5 to 20 seconds, and grow a few seconds longer each round, and good rock tea gives seven steeps or more. In a larger pot, use about 2 to 5 grams for 250 to 350 ml and steep two to three minutes."},"notice":{"layer":"notice","styleName":"Wuyi rock tea","text":"Roast and stone fruit, a mineral, rocky texture and a long, sweet, mouth-watering finish. Light roast is bright and floral, medium roast fruity and rounded, full roast charcoal, wood and roasted nuts. Da Hong Pao is often floral, Rougui spicy with cinnamon, young Shui Xian sweet and smooth, and old-bush Shui Xian woody and mossy."},"missing":[]},
  "cb7efd7b-9da6-4dc8-be76-3c7e69bdb02e": {"productId":"cb7efd7b-9da6-4dc8-be76-3c7e69bdb02e","paragraphs":[{"layer":"named","text":"Y562 is the export code for a loose [ripe pu’er](shou:definition) from Yunnan, which drinkers nicknamed the [“little black box”](y562:little-black-box) after its carton. The Jixing mark on the front shows a tiger coming downhill. The box was made to carry the province’s [own brand](y562:export-trade). Much of Yunnan’s loose pu’er once travelled in bulk, and in Japan importers repacked it under their own labels. In 1980 Yunnan brought packaging and tea export designers together to change that, so Y562 carried Chinese lettering on the front and “Superior Yunnan Pu-erh Tea” on the back."},{"layer":"named","text":"Tang Zheng drew the tiger from an openwork jade pendant, and Yin Huize framed the lettering with patterns taken from Chinese lacquerware. The two took cartons painted by hand to the spring [Canton Fair](y562:designers), and buyers ordered from those samples. Pu’er magazine describes the [original blend](y562:original-blend) as grades five and six of ripe tea from Menghai Tea Factory. Its yellow box companion, Y671, used grades six and seven from Kunming Tea Factory."},{"layer":"age","text":"This box dates from 1993, twenty years after Yunnan’s state factories brought the [wet pile](shou:wet-piling) into production, which places it in the style’s third decade. At thirty-three years it counts as [aged ripe pu’er](shou:age-aged). The leaf keeps changing with the air and moisture around it, so its storage has shaped it as much as its age."}],"brewing":{"layer":"brewing","text":"Ripe pu’er takes boiling water: fermented, tightly packed leaf needs full heat to open, and it does not scald the way green tea can. A common start is about 7 grams to 100 ml and one quick rinse, which wakes the leaf and carries off dust and any pile smell. Then short steeps that lengthen as the leaf opens, so the cup stays clear rather than heavy; it gives eight or more good cups."},"notice":{"layer":"notice","styleName":"aged ripe pu’er","text":"A smooth, deep cup with woody, date-like or medicinal notes, which the trade calls aged aroma."},"missing":[]},
  "cba00fb7-dd94-411f-b807-eee6bc1270a1": {"productId":"cba00fb7-dd94-411f-b807-eee6bc1270a1","paragraphs":[{"layer":"type","text":"This is [Tieguanyin](tieguanyin:definition), the [oolong](oolong:definition) that shares its name with the cultivar it is made from, grown in [Anxi](anxi:where-it-is), a county of hills and ridges in southern Fujian, inland from Xiamen. The leaf was rolled into tight balls by [wrapping it in cloth](tieguanyin:making), pressing it and drying it a little, again and again, each round drawing it tighter. It was made in 1990, just as the [Tieguanyin boom](anxi:history) was about to change a county that had been among the poorer in the province."},{"layer":"age","text":"At thirty-six years it falls in the third kind the trade sorts Tieguanyin into, [chenxiang, or old Tie](tieguanyin:styles): tea kept for years, not drunk fresh. The [light style](tieguanyin:ageing) goes stale quickly, so the heavier roasted kind is the one usually put away, and it is rested until the fire of the roast has settled."}],"brewing":{"layer":"brewing","text":"Tieguanyin is usually brewed gongfu style with water at or near the boil, about 95 to 100°C; the light green style is often taken a little cooler, about 85 to 95°C. Use about 4 to 8 grams of leaf in a 100 to 150 ml gaiwan or pot, about a third full. A quick rinse, poured off at once, is common. Steeps start short, about 10 to 30 seconds, and grow a few seconds longer each round, and a good Tieguanyin gives about six to eight. In a larger pot, use about 2.5 to 5 grams for 240 to 350 ml and steep two to three minutes."},"notice":{"layer":"notice","styleName":"aged Tieguanyin","text":"A smoother, rounder, softer cup with the fire gone, a liquor turned orange-red or reddish-brown, and often a soft fruity sourness."},"missing":[]},
  "cdadaad5-cf39-4a83-b578-b80223f55829": {"productId":"cdadaad5-cf39-4a83-b578-b80223f55829","paragraphs":[{"layer":"place","text":"[Muzha](muzha:where-it-is) is a hill district on the southeast edge of Taipei, in Wenshan District, where the tea grows on low slopes of a few hundred metres. Fujian settlers brought Tieguanyin here from [Anxi](muzha:history) in the late nineteenth century. The trade most often credits the tea master Zhang Naimiao, who planted it in the Zhanghu part of Muzha in 1895. The [traditional Muzha style](taiwan-oolong:muzha) is a more oxidised oolong, roasted over charcoal, its leaf wrapped in cloth and rolled again and again. On a label, Muzha names [a place and a way of making](muzha:on-a-label). It does not prove which plant the leaf came from."},{"layer":"age","text":"This tea dates from 1972, which makes it fifty-four years old. Taiwan has a tradition of keeping oolong for years, called [lao cha, old tea](taiwan-oolong:ageing). Leaf chosen for keeping starts well roasted and dry. It is roasted again at low heat from time to time, because over the years it takes in moisture that has to be driven out. No standard says when an oolong becomes old. Those who give a figure put it between ten and thirty years, and this tea is well past the longer of the two."}],"brewing":{"layer":"brewing","text":"Ball-rolled Taiwan oolong takes hot water, about 90 to 100°C, a fairly generous amount of leaf and short steeps; the balls open slowly and give many infusions. Roasted Dong Ding takes water from about 95°C to a full boil. Aged oolong takes very hot water, in a pot that holds its heat, clay above all. Oriental Beauty is the exception and takes cooler water, about 80 to 95°C."},"notice":{"layer":"notice","styleName":"aged Taiwan oolong","text":"A smooth, mellow, thick cup with little astringency, often plum or prune, sometimes something like medicinal herbs or ginseng, and an amber to red-brown liquor."},"missing":[]},
  "cf2eda17-a788-4f83-8800-37fcd8adb818": {"productId":"cf2eda17-a788-4f83-8800-37fcd8adb818","paragraphs":[{"layer":"lot","text":"A [tuo](sheng:pressing) of [raw pu’er](sheng:identity) pressed at the Menghai factory in 1998 and graded Jia Ji, Grade A, for leaf above the factory’s standard production. Menghai was one of the [state factories](sheng:history) that made pu’er to set recipes after 1949. The tuo is a small bowl shape, first pressed so tea packed well for the old trade routes, and a small piece like this ages faster than a large, tight cake."},{"layer":"age","text":"The shop’s notes record it as aged in warm storage. Heat and humidity decide how fast raw pu’er changes, so a [warm store](sheng:storage) moves it along quickly. The trade does not agree where [aged raw pu’er](sheng:ageing) begins: some count from ten years, many wait for twenty or more. This tuo is past both marks, and the notes place it between young sheng and fully aged."}],"brewing":{"layer":"brewing","text":"Pry the leaf off a cake or brick in chunks with a pick or knife, from the surface and toward the centre, rather than crumbling it. A mix of larger pieces and smaller ones brews evenly. Young raw pu’er takes water a little off the boil, about 85 to 95°C, because hotter water draws out more of its bitterness; an aged one takes 95°C to boiling. A common start is about 7 grams to 100 ml and a quick rinse of a few seconds, then a first steep of ten to fifteen seconds, adding a few seconds each round. A good raw tea gives eight to ten cups or more."},"notice":{"layer":"notice","styleName":"aged Sheng Pu’er","text":"A smoother, thicker, sweeter cup with woody, herbal and camphor notes and something of dried dates or dark fruit."},"missing":[]},
  "cf59e091-f60d-4015-8034-bb5faae270f5": {"productId":"cf59e091-f60d-4015-8034-bb5faae270f5","paragraphs":[{"layer":"type","text":"[Liu An basket tea](liu-an:definition) is a [dark tea](dark:definition) from Anhui, a leaf left to change slowly after it is made. Despite the name, it is made in [Qimen County](anhui:places-inside) in the south of the province rather than in the city of Lu'an, from the same small-leaf bush that gives Keemun. Its making ends with steps of its own: the fired leaf is spread outdoors for one [night of dew](liu-an:making), steamed soft and packed into bamboo baskets lined with leaf, then rested for years before it is sold."},{"layer":"age","text":"This leaf dates from 1990. Making had stopped in the 1930s and 1940s, when war cut the [southern trade](liu-an:southern-trade) to Guangdong, Hong Kong and Macau. It came back after tea people from Hong Kong sent an aged basket to Anhui in 1983 and asked for it to be made again, and commercial making returned in the early 1990s, so this tea comes from the first years of that return. At thirty-six years it has had the long keeping the style is [made for](liu-an:ageing)."}],"brewing":{"layer":"brewing","text":"Use water at or near the boil, rinse the leaf quickly, and keep the steeps short, each a little longer than the last, in a gaiwan or clay pot; doses run from about 3 to 8 grams for 100 ml, for six to ten or more steeps. A small piece of the basket's bamboo leaf is often brewed with it. Aged tea can also be simmered in a larger pot, about 1 gram to 200 to 300 ml, for a few minutes or longer."},"notice":{"layer":"notice","styleName":"aged Liu An","text":"A redder, browner liquor, the smoke gone, and the cup moving toward medicinal, woody and camphor notes, often with betel nut."},"missing":[]},
  "d139d5b8-87df-44fe-b848-619eef96c8c7": {"productId":"d139d5b8-87df-44fe-b848-619eef96c8c7","paragraphs":[{"layer":"lot","text":"A cake of [raw pu’er](sheng:identity) made from purple-leaf tea grown in Lincang, Yunnan. The leaf was [dried in the sun](sheng:making) as maocha, then compressed into this cake."},{"layer":"type","text":"Because the leaf is fried in the wok but never hot-air dried afterwards, some of its own activity survives, and that is what lets a cake keep changing for years. How fast it moves depends on where it is kept: warm, humid stores change raw pu’er quickly, while cool, dry ones slow it and keep it brighter, so [storage](sheng:storage) becomes part of each cake’s history."}],"brewing":{"layer":"brewing","text":"Pry the leaf off a cake or brick in chunks with a pick or knife, from the surface and toward the centre, rather than crumbling it. A mix of larger pieces and smaller ones brews evenly. Young raw pu’er takes water a little off the boil, about 85 to 95°C, because hotter water draws out more of its bitterness; an aged one takes 95°C to boiling. A common start is about 7 grams to 100 ml and a quick rinse of a few seconds, then a first steep of ten to fifteen seconds, adding a few seconds each round. A good raw tea gives eight to ten cups or more."},"notice":{"layer":"notice","styleName":"aged Sheng Pu’er","text":"A smoother, thicker, sweeter cup with woody, herbal and camphor notes and something of dried dates or dark fruit."},"missing":[]},
  "d2e3fae9-47b7-4866-b683-c0c088c423a6": {"productId":"d2e3fae9-47b7-4866-b683-c0c088c423a6","paragraphs":[{"layer":"lot","text":"Old Rainbow is a loose [raw pu’er](sheng:identity) from Yunnan, the counterpart to the shop's New Rainbow. The village or mountain behind the leaf is not known."},{"layer":"type","text":"The leaf was made in the raw way. Large-leaf tea is picked, withered and fried in a wok, then rolled and dried in the sun, giving [maocha](sheng:making). It is never hot-air dried, so some of the leaf's own activity survives, and that is why the tea keeps [changing through storage](sheng:aging), year after year. This lot was [left loose](sheng:processing) rather than pressed."}],"brewing":{"layer":"brewing","text":"Young raw pu’er takes water a little off the boil, about 85 to 95°C, because hotter water draws out more of its bitterness; an aged one takes 95°C to boiling. A common start is about 7 grams to 100 ml and a quick rinse of a few seconds, then a first steep of ten to fifteen seconds, adding a few seconds each round. A good raw tea gives eight to ten cups or more."},"notice":{"layer":"notice","styleName":"Sheng Pu’er","text":"In young raw pu’er, a bitter, drying bite that turns into a returning sweetness, a feel in the throat that makes the mouth water, and fresh, floral or fruity notes such as apricot or plum. Tea kept in humid storage can carry a damp, earthy storage taste."},"missing":[]},
  "d3d322e3-be1f-4013-bb3b-960fd554e1e8": {"productId":"d3d322e3-be1f-4013-bb3b-960fd554e1e8","paragraphs":[{"layer":"place","text":"This tea comes from [Hsinchu](hsinchu:where-it-is), a hill county in the north west of Taiwan, where the style grows on low to middling ground rather than on the high mountains of the island's centre. Tea here is largely a [Hakka](hsinchu:hakka) trade, and many farms have passed down through families since the Japanese period. The record names the county and not a township; within it, the trade most often names [Emei and Beipu](hsinchu:tea-townships)."},{"layer":"type","text":"[Oriental Beauty](taiwan-oolong:oriental-beauty) depends on a [small green leafhopper](hsinchu:summer-leafhopper) that feeds on the young shoots in summer. Its bite starts the leaf's change while it is still on the bush, so growers keep insecticide off these gardens. The bud and the next two leaves are picked by hand. The leaf is then [oxidised](oolong:definition) much further than other Taiwan oolong, close to red tea, before it is dried. In Hsinchu it also has an older folk name, [pengfeng cha](hsinchu:oriental-beauty-names), braggart's tea."}],"brewing":{"layer":"brewing","text":"Ball-rolled Taiwan oolong takes hot water, about 90 to 100°C, a fairly generous amount of leaf and short steeps; the balls open slowly and give many infusions. Roasted Dong Ding takes water from about 95°C to a full boil. Aged oolong takes very hot water, in a pot that holds its heat, clay above all. Oriental Beauty is the exception and takes cooler water, about 80 to 95°C."},"notice":{"layer":"notice","styleName":"Taiwan oolong","text":"In light high mountain tea: a sweet, floral cup, often creamy or buttery, with little bitterness and a long sweet aftertaste. In roasted Dong Ding: caramel, ripe fruit, nuts and a toasted aroma. In Baozhong: floral notes and a clear, bright liquor. In Oriental Beauty: ripe fruit and honey, with little bitterness."},"missing":[]},
  "d7e54fa3-7518-4400-8e6d-a5dee9f29b4f": {"productId":"d7e54fa3-7518-4400-8e6d-a5dee9f29b4f","paragraphs":[{"layer":"lot","text":"A cake of [raw pu’er](sheng:identity) from Yunnan, pressed in 1980. Nobody recorded the garden its leaf came from. It was made as the 1980s began, the decade when collectors, led at first by Taiwan, started looking for [aged raw pu’er](sheng:history-modern)."},{"layer":"type","text":"Unlike shou, sheng is never put through [rapid fermentation](sheng:aging). It changes slowly in storage instead, so where a cake was kept is part of its history. [Heat and humidity](sheng:storage) set the pace, because the change comes partly from slow oxidation and partly from the work of microbes. The trade disagrees about when [aged](sheng:ageing) begins: some say ten years, many wait for twenty. At forty-six years, this cake is past either mark."}],"brewing":{"layer":"brewing","text":"Pry the leaf off a cake or brick in chunks with a pick or knife, from the surface and toward the centre, rather than crumbling it. A mix of larger pieces and smaller ones brews evenly. Young raw pu’er takes water a little off the boil, about 85 to 95°C, because hotter water draws out more of its bitterness; an aged one takes 95°C to boiling. A common start is about 7 grams to 100 ml and a quick rinse of a few seconds, then a first steep of ten to fifteen seconds, adding a few seconds each round. A good raw tea gives eight to ten cups or more."},"notice":{"layer":"notice","styleName":"aged Sheng Pu’er","text":"A smoother, thicker, sweeter cup with woody, herbal and camphor notes and something of dried dates or dark fruit."},"missing":[]},
  "d8b6bcc0-e5d1-4ed1-8cab-67b3bd62d0dc": {"productId":"d8b6bcc0-e5d1-4ed1-8cab-67b3bd62d0dc","paragraphs":[{"layer":"lot","text":"A [ripe pu’er](shou:definition) from Yunnan, kept as loose leaf rather than pressed, and aged loose after it was made."},{"layer":"type","text":"Before the ageing began, the leaf went through the [wet pile](shou:wet-piling). Leaf dried in the sun is wetted and heaped so that heat, moisture and microbes can work on it. The microbes make their own heat, so the heap is covered to hold it in and turned about once a week to spread it and let in air, and it is kept below about 65°C so the leaf does not char. Yunnan’s state factories brought the method into production in 1973, to reach in weeks what raw pu’er reached only after years of waiting."}],"brewing":{"layer":"brewing","text":"Ripe pu’er takes boiling water: fermented, tightly packed leaf needs full heat to open, and it does not scald the way green tea can. A common start is about 7 grams to 100 ml and one quick rinse, which wakes the leaf and carries off dust and any pile smell. Then short steeps that lengthen as the leaf opens, so the cup stays clear rather than heavy; it gives eight or more good cups."},"notice":{"layer":"notice","styleName":"ripe pu’er","text":"A smooth, sweet cup with earthy or woody notes. A young ripe tea can carry a faint smell of the pile, which fades with airing or in the first steeps."},"missing":[]},
  "d91c484e-ff69-46f7-8822-0c0e3959dae9": {"productId":"d91c484e-ff69-46f7-8822-0c0e3959dae9","paragraphs":[{"layer":"lot","text":"A loose [raw pu’er](sheng:identity) from Yunnan, dated 1930 and now in powdered form. How it was first made is not recorded. It predates the [state factories](sheng:history): the private tea houses were folded into them only after 1949, when pu’er began to be made to standard recipes."},{"layer":"age","text":"At ninety-six years it is far past both the ten years some count as [aged raw pu’er](sheng:ageing) and the twenty or more that many wait for. Its form matters to how a tea changes. A tight cake ages slowly and loose leaf faster, because [pressing](sheng:pressing) sets the pace of ageing."}],"brewing":{"layer":"brewing","text":"Young raw pu’er takes water a little off the boil, about 85 to 95°C, because hotter water draws out more of its bitterness; an aged one takes 95°C to boiling. A common start is about 7 grams to 100 ml and a quick rinse of a few seconds, then a first steep of ten to fifteen seconds, adding a few seconds each round. A good raw tea gives eight to ten cups or more."},"notice":{"layer":"notice","styleName":"aged Sheng Pu’er","text":"A smoother, thicker, sweeter cup with woody, herbal and camphor notes and something of dried dates or dark fruit."},"missing":[]},
  "da83f352-9402-437e-867e-412b6f0b5df8": {"productId":"da83f352-9402-437e-867e-412b6f0b5df8","paragraphs":[{"layer":"place","text":"This is [Anhua dark tea](anhua-dark:definition), a protected origin name, from the mountain county of [Anhua](anhua:where-it-is) on the Zi river in north-central Hunan. The county sits at the northern foot of the Xuefeng mountains. Most of it is hills and steep valleys, ground where rice is hard to grow and tea does well. The leaf grows in warm, wet air, and the tea is piled and kept in that same air. That is why the trade ties [the finished tea to the place](anhua:why-people-value-it) and not only to the method."},{"layer":"type","text":"Every Anhua tea begins as [heimaocha](anhua-dark:making). Large Anhua leaf is fixed, rolled, piled, rolled again and dried. Like any [dark tea](dark:definition), it keeps changing after it is made, as warmth, moisture and microbes slowly darken and mellow the leaf."},{"layer":"age","text":"Made in 2024, this tea is two years into that change. Anhua tea is [kept for years](anhua-dark:ageing) and is said to improve, though no agreed number of years marks it as aged."}],"brewing":{"layer":"brewing","text":"In a small pot or gaiwan, use water at the boil and start with a steep of about 15 to 30 seconds, a little longer each round. Pressed and aged Anhua tea is also commonly simmered in a pot."},"notice":{"layer":"notice","styleName":"Anhua dark tea","text":"Pine smoke or pine resin above all, a sweet taste and aftertaste, and a mellow, thick, smooth cup; a liquor from yellow and orange to orange-red. Young tea is often smokier in the first infusions and a little bitter, sweetening as the infusions go on."},"missing":[]},
  "dac9d851-44ca-4789-b561-01bc3dc9a6ae": {"productId":"dac9d851-44ca-4789-b561-01bc3dc9a6ae","paragraphs":[{"layer":"type","text":"A small tuo of [ripe pu’er](shou:definition) made in 1998 from Yunnan leaf. Before it was pressed, the leaf went through the [wet pile](shou:wet-piling). It was heaped warm and damp and turned now and then to spread the heat and let air in. That places it in the style’s third decade, because the method reached production in 1973, twenty-five years earlier."},{"layer":"age","text":"At twenty-eight years it counts as [aged ripe pu’er](shou:age-aged) in the trade’s terms. The leaf keeps changing slowly with the air and moisture around it, so how a tuo like this was kept matters as much as how long."}],"brewing":{"layer":"brewing","text":"From a cake, brick or tuo, ease a piece off along the edge with a pick rather than snapping it. Whole leaves give up their flavour steadily; broken ones release it all at once and cloud the cup. Ripe pu’er takes boiling water: fermented, tightly packed leaf needs full heat to open, and it does not scald the way green tea can. A common start is about 7 grams to 100 ml and one quick rinse, which wakes the leaf and carries off dust and any pile smell. Then short steeps that lengthen as the leaf opens, so the cup stays clear rather than heavy; it gives eight or more good cups."},"notice":{"layer":"notice","styleName":"aged ripe pu’er","text":"A smooth, deep cup with woody, date-like or medicinal notes, which the trade calls aged aroma."},"missing":[]},
  "db223b1a-50c2-4eb0-bc82-f6903770be7b": {"productId":"db223b1a-50c2-4eb0-bc82-f6903770be7b","paragraphs":[{"layer":"type","text":"A [Kang brick](sichuan-dark:kangzhuan-jinjian) of [Sichuan border tea](sichuan-dark:definition) from Ya'an, made in 1980. The name describes the blend, not the place or the year. A Kangzhuan holds more leaf than red moss, the reddish stem and shoot pieces that come with the leaf, while a Jinjian holds more stem. Makers chose coarse, mature leaf because the brick had to last months on the road to the Tibetan highlands and then be boiled for hours."},{"layer":"age","text":"At forty-six years old, this is the kind of older brick the trade values more than a young one. Its liquor turns redder as the years pass, and how fast a [brick's ageing](sichuan-dark:ageing) goes depends on how it is stored."}],"brewing":{"layer":"brewing","text":"From a brick, cake or basket, ease the leaf off along the edge or from the top with a pick rather than snapping it. Whole pieces give up their flavour steadily; crumbs release it all at once and cloud the cup. Break a few pieces from the edge of the brick, rinse them with boiling water and pour that off at once. Then use boiling water and plenty of leaf. The leaf is coarse and gives up its flavour slowly, so people brew it two ways. Some steep it in short gongfu pours, a little longer each time. Others use long steeps while the pot is still hot, or simmer the leaf for several minutes in a pot, which is the traditional way on the plateau."},"notice":{"layer":"notice","styleName":"aged Sichuan border tea","text":"A redder, browner liquor, a rounder body and a medicinal edge, often with wood and a dark sweetness."},"missing":[]},
  "db8e5235-aaaa-4b95-8401-4e9dfdaaa8cf": {"productId":"db8e5235-aaaa-4b95-8401-4e9dfdaaa8cf","paragraphs":[{"layer":"type","text":"A loose [red tea](red:definition) from Taiwan, made in 1979. Red tea is the fully oxidised tea English calls black tea. On the island it goes back to the Japanese period, when it was first made at Yuchi near Sun Moon Lake, though the island is known above all for [oolong](taiwan:known-for). This label names only [Taiwan](taiwan:on-a-label). That says the leaf grew on the island and nothing more about which area or garden it came from."},{"layer":"age","text":"Red tea has no [tradition of ageing](red:ageing). It is made to be drunk within a year and a half to three years, while it keeps its first quality. At forty-seven years, this leaf has gone far past the usual life of the style."}],"brewing":{"layer":"brewing","text":"Red tea takes water near the boil, about 90 to 100°C; hotter water draws out its aroma and flavour more fully, but its bitterness faster too. In a pot or mug, use about a rounded spoon of leaf for each cup and steep three to five minutes, less for broken leaf and a little less, and a little cooler, for a light, delicate tea. Left too long, it turns bitter and drying, because time and heat pull more tannins from the leaf."},"notice":{"layer":"notice","styleName":"red tea","text":"A sweet cup, often with honey, floral or fruity notes, malt in many, and a brisk strength in the stronger teas. The liquor runs red, bright to deep."},"missing":[]},
  "dc8097d2-89dd-4f33-9a1a-326ba0dee424": {"productId":"dc8097d2-89dd-4f33-9a1a-326ba0dee424","paragraphs":[{"layer":"lot","text":"These are Yunnan tea buds picked in early spring while still tightly closed, foraged from wild trees rather than gathered from a tended garden. They were dried just as they came off the branch, with no heat applied to stop their change and no rolling."},{"layer":"type","text":"That places them in [white tea](white:definition), the style made with the fewest steps: the leaf is only withered and dried. Because it is never heated, rolled or bruised, each bud keeps its natural shape and the white down that gives the style its name. In [Yunnan white](yunnan-white:making) the leaf is finished by air rather than given the low final bake that Fujian white tea usually receives."}],"brewing":{"layer":"brewing","text":"Yunnan white is brewed gently, as a white tea is, in a gaiwan or small pot, and it gives many infusions; the leaf holds up well."},"notice":{"layer":"notice","styleName":"Yunnan white","text":"A honeyed, sweet cup, often richer and fuller than Fujian white, with little bitterness, sometimes fruit like apricot or melon and a hay or herbal note. Yabao is sweet and silky, often with pine or herbal notes."},"missing":[]},
  "dddd11d2-7357-4d91-86e8-52a99bb47c51": {"productId":"dddd11d2-7357-4d91-86e8-52a99bb47c51","paragraphs":[{"layer":"place","text":"Naka is a village in [Mengsong](menghai-county:mengsong-naka), one of Menghai County’s tea-growing areas. This tea is a ripe pu’er pressed into a cake."}],"missing":[]},
  "de14c4e4-2170-4a2f-9476-d4a1c29dcabc": {"productId":"de14c4e4-2170-4a2f-9476-d4a1c29dcabc","paragraphs":[{"layer":"grade","text":"This is [first grade](anhua-dark:grades) (一级) leaf from Anhua, picked in 2015 and kept loose. In Anhua the raw leaf is sorted into numbered grades, and each grade goes into the finished tea that suits it."},{"layer":"type","text":"Anhua County is a mountain county on the Zi river in north-central Hunan. Its [dark tea](anhua-dark:definition) is a protected origin product, so the name is tied to tea made in that place. Like every tea from the county, this one began as [heimaocha](anhua-dark:making), a raw tea of large Anhua leaf that is fixed, rolled, piled, rolled again and dried. The leaf then goes on changing slowly in warmth and moisture, which is why the trade calls [dark tea](dark:definition) post-fermented."},{"layer":"age","text":"Eleven years have passed since this leaf was made. No set number of years makes an Anhua tea [aged](anhua-dark:ageing). It is best kept clean, dry and aired, away from mould and other smells."}],"brewing":{"layer":"brewing","text":"In a small pot or gaiwan, use water at the boil and start with a steep of about 15 to 30 seconds, a little longer each round. Pressed and aged Anhua tea is also commonly simmered in a pot."},"notice":{"layer":"notice","styleName":"aged Anhua dark tea","text":"A redder liquor, a sweeter, mellower cup, and sometimes a medicinal or herbal note."},"missing":[]},
  "dfb90ef0-fe35-4bc2-a1c5-17084f1f66d4": {"productId":"dfb90ef0-fe35-4bc2-a1c5-17084f1f66d4","paragraphs":[{"layer":"lot","text":"This ripe pu’er cake comes from the Yiwu tea area of Yunnan. Its recorded year is 2008."}],"missing":[]},
  "dfde3e28-c848-4116-ba2b-ea55590b0f1e": {"productId":"dfde3e28-c848-4116-ba2b-ea55590b0f1e","paragraphs":[{"layer":"type","text":"Rougui, cassia in Chinese, is a [Wuyi cultivar](yancha:rougui) that dates from the Qing dynasty and is now one of the most widely planted teas in the range. It is made as [rock tea](yancha:definition), with the leaf twisted into long, thin strips rather than rolled into balls."},{"layer":"place","text":"The leaf comes from the [Wuyi Mountains](wuyi-mountains:where-it-is), on the border of northern Fujian and Jiangxi. The mountains hold in warm air from the sea, so rain is heavy and fog is common, and the bushes grow in [thin, stony soil](wuyi-mountains:nature) on ledges and between rocks, where the ground drains fast. The label names no zone, so it does not say how close to the [true rock core](wuyi-mountains:zones) this tea grew."},{"layer":"lot","text":"This lot was given a heavy [charcoal roast](yancha:making) in stages over several sessions. That is how the craft works: rounds over charcoal with rests of weeks or months between them, rather than one pass, so the tea dries and keeps."}],"brewing":{"layer":"brewing","text":"Wuyi tea is usually brewed gongfu style with water at or near the boil, about 95 to 100°C, and about 5 to 8 grams of leaf in a 100 to 120 ml gaiwan, a third to a half full. A quick rinse, poured off at once, is common. Steeps start short, about 5 to 20 seconds, and grow a few seconds longer each round, and good rock tea gives seven steeps or more. In a larger pot, use about 2 to 5 grams for 250 to 350 ml and steep two to three minutes."},"notice":{"layer":"notice","styleName":"Wuyi rock tea","text":"Roast and stone fruit, a mineral, rocky texture and a long, sweet, mouth-watering finish. Light roast is bright and floral, medium roast fruity and rounded, full roast charcoal, wood and roasted nuts. Da Hong Pao is often floral, Rougui spicy with cinnamon, young Shui Xian sweet and smooth, and old-bush Shui Xian woody and mossy."},"missing":[]},
  "dff84849-ba07-4ccb-94b9-b94df9a4b2f1": {"productId":"dff84849-ba07-4ccb-94b9-b94df9a4b2f1","paragraphs":[{"layer":"place","text":"A [tuo](sheng:pressing) of [raw pu’er](sheng:identity) made in 1996 from leaf grown in [Menghai County](menghai-county:county-and-factory), Yunnan. Tea was first pressed into compact shapes like this small bowl so it could travel the old trade routes, and the shape still decides how it ages: a small tuo changes faster than a large, tight cake."},{"layer":"age","text":"It was made in the years when [collectors](sheng:history-modern), led at first by Taiwan, came looking for aged raw pu’er. At thirty years it is past both lines the trade draws for [aged](sheng:ageing) raw tea, ten years for some and twenty or more for many. Raw pu’er gets no quick fermentation, so it [changes slowly in storage](sheng:aging). How warm and humid its [stores](sheng:storage) were over those three decades is part of its history, as much as the years themselves."}],"brewing":{"layer":"brewing","text":"Pry the leaf off a cake or brick in chunks with a pick or knife, from the surface and toward the centre, rather than crumbling it. A mix of larger pieces and smaller ones brews evenly. Young raw pu’er takes water a little off the boil, about 85 to 95°C, because hotter water draws out more of its bitterness; an aged one takes 95°C to boiling. A common start is about 7 grams to 100 ml and a quick rinse of a few seconds, then a first steep of ten to fifteen seconds, adding a few seconds each round. A good raw tea gives eight to ten cups or more."},"notice":{"layer":"notice","styleName":"aged Sheng Pu’er","text":"A smoother, thicker, sweeter cup with woody, herbal and camphor notes and something of dried dates or dark fruit."},"missing":[]},
  "e01c590b-b8b4-4d44-93b2-3ecde1161e13": {"productId":"e01c590b-b8b4-4d44-93b2-3ecde1161e13","paragraphs":[{"layer":"type","text":"A [dark tea](dark:definition) from China, made in 1990 and kept loose rather than pressed. After the leaf was heated and rolled, it was left to change in warmth and moisture, where microbes and the leaf's own chemistry slowly darkened it. Most dark tea was pressed into bricks, cakes and logs so it could survive months on the road as [border tea](dark:why) to Tibet, Mongolia and the north west, but some is still sold loose, as this one is."},{"layer":"age","text":"Dark tea is made to be kept, and the trade [values it more with age](dark:ageing). This one is thirty-six years old. How far it has changed depends on how it was stored. The trade does not agree on one way: some keep dark tea cool and dry for a slow, clean change, others warmer and more humid for a faster one."}],"brewing":{"layer":"brewing","text":"Dark tea takes boiling water. Its leaf is mature and dense, so it gives up its flavour slowly and is hard to overbrew. Rinse it first with boiling water and pour that off within seconds: the rinse wakes the leaf and washes off dust and any stale smell from storage, and an old tea may take a second rinse. In a small pot use plenty of leaf, about 7 grams to 120 ml, then steep very briefly at first and a little longer each time; a good dark tea gives many cups."},"notice":{"layer":"notice","styleName":"dark tea","text":"A smooth, mellow cup with low bitterness and a deep red colour, often sweet and woody or earthy, sometimes with herbal or medicinal notes. A young dark tea can still smell of the pile or of storage; an aged one is usually redder, sweeter and thicker."},"missing":[]},
  "e03fe436-ba3d-4af6-b78b-656fd228239a": {"productId":"e03fe436-ba3d-4af6-b78b-656fd228239a","paragraphs":[{"layer":"lot","text":"A [ripe pu’er](shou:definition) cake from Yunnan, made in the 1990s and sold as a loose cake. Its leaf went through the [wet pile](shou:wet-piling), a method that reached production in 1973, which places this cake within the style’s first three decades."},{"layer":"age","text":"At thirty-one years it sits well past the ten that the trade counts as [aged ripe pu’er](shou:age-aged). The leaf keeps changing with the air and moisture around it, so how a cake is kept matters as much as its age."}],"brewing":{"layer":"brewing","text":"From a cake, brick or tuo, ease a piece off along the edge with a pick rather than snapping it. Whole leaves give up their flavour steadily; broken ones release it all at once and cloud the cup. Ripe pu’er takes boiling water: fermented, tightly packed leaf needs full heat to open, and it does not scald the way green tea can. A common start is about 7 grams to 100 ml and one quick rinse, which wakes the leaf and carries off dust and any pile smell. Then short steeps that lengthen as the leaf opens, so the cup stays clear rather than heavy; it gives eight or more good cups."},"notice":{"layer":"notice","styleName":"aged ripe pu’er","text":"A smooth, deep cup with woody, date-like or medicinal notes, which the trade calls aged aroma."},"missing":[]},
  "e1e3373c-dde0-41a2-9e41-99dc2ecbf0fb": {"productId":"e1e3373c-dde0-41a2-9e41-99dc2ecbf0fb","paragraphs":[{"layer":"lot","text":"This lot began as a 1958 batch of [raw pu’er](sheng:identity), the branch of the tea that is never given shou’s rapid fermentation and instead [changes slowly in storage](sheng:aging). Over the decades its pressed cakes shed loose leaves and small pieces at their edges. Someone swept those fragments together year after year until there were enough to sell, so the tea exists only because the sweepings were kept."},{"layer":"lot","text":"The leaf grew in Yunnan and aged in a Hong Kong warehouse, the trade’s [traditional storage](sheng:storage). Raw pu’er changes partly through slow oxidation and partly through the work of microbes, so warm, humid air moves it along faster than a dry, cool store would. In the twentieth century Hong Kong became the tea’s [great drinking market](sheng:history), and its merchants kept pu’er humid for that reason."},{"layer":"age","text":"At sixty-eight years it sits far past any line the trade draws for [aged raw pu’er](sheng:ageing), whether that line is ten years or twenty. Its decades in Hong Kong belong to its history as much as the leaf does."}],"brewing":{"layer":"brewing","text":"Young raw pu’er takes water a little off the boil, about 85 to 95°C, because hotter water draws out more of its bitterness; an aged one takes 95°C to boiling. A common start is about 7 grams to 100 ml and a quick rinse of a few seconds, then a first steep of ten to fifteen seconds, adding a few seconds each round. A good raw tea gives eight to ten cups or more."},"notice":{"layer":"notice","styleName":"aged Sheng Pu’er","text":"A smoother, thicker, sweeter cup with woody, herbal and camphor notes and something of dried dates or dark fruit."},"missing":[]},
  "e2a754de-d2e9-474c-a5e9-b13a85b746ad": {"productId":"e2a754de-d2e9-474c-a5e9-b13a85b746ad","paragraphs":[{"layer":"lot","text":"A cake of [raw pu’er](sheng:identity) from Lincang in Yunnan, made in 2016 from purple-leaf tea. The leaf was [sun-dried](sheng:making) as maocha and then pressed into a cake. Because it is never hot-air dried, some of the leaf’s own activity survives, and with no fast fermentation of the kind shou receives, the cake has been [changing slowly in storage](sheng:aging) ever since."},{"layer":"age","text":"At ten years it sits where the trade begins to disagree: some count a raw pu’er as [aged](sheng:ageing) from ten years, while many wait for twenty or more. How far this cake has come depends on how it was pressed and kept, as well as on the years."}],"brewing":{"layer":"brewing","text":"Pry the leaf off a cake or brick in chunks with a pick or knife, from the surface and toward the centre, rather than crumbling it. A mix of larger pieces and smaller ones brews evenly. Young raw pu’er takes water a little off the boil, about 85 to 95°C, because hotter water draws out more of its bitterness; an aged one takes 95°C to boiling. A common start is about 7 grams to 100 ml and a quick rinse of a few seconds, then a first steep of ten to fifteen seconds, adding a few seconds each round. A good raw tea gives eight to ten cups or more."},"notice":{"layer":"notice","styleName":"aged Sheng Pu’er","text":"A smoother, thicker, sweeter cup with woody, herbal and camphor notes and something of dried dates or dark fruit."},"missing":[]},
  "e2d8139e-aa96-4e9f-a092-ac70368f06c5": {"productId":"e2d8139e-aa96-4e9f-a092-ac70368f06c5","paragraphs":[{"layer":"lot","text":"The record knows this tea only as the Orange Master Box. It names no village, no cultivar and no maker, and China is the only origin it gives."},{"layer":"type","text":"What can be said is the kind of tea it is. It is an [oolong](oolong:definition), a partly oxidised tea that sits between green tea and red. The leaf is [tossed in rounds](oolong:making) so its edges bruise and slowly change, then heated to stop that change where the maker chooses. How far this leaf was oxidised, and whether it was [roasted](oolong:oxidation-and-roast), are two separate choices, and neither is recorded for this box."}],"brewing":{"layer":"brewing","text":"Oolong is most often brewed gongfu style, in a small gaiwan or clay pot with plenty of leaf and short steeps, and it stands many rounds. A common start is about 4 to 6 grams to 100 ml, with a first steep of roughly 5 to 15 seconds and 5 to 10 seconds more each round. Light, green-style oolong takes water a little off the boil, about 90 to 95°C; heavily oxidised, roasted and aged oolong takes water at a full boil. Many people pour a quick first rinse to wake tightly rolled leaf. In a larger pot, use less leaf and steep for a few minutes."},"notice":{"layer":"notice","styleName":"oolong","text":"In light, green-style oolong: floral and orchid notes, a creamy or buttery feel and a sweet aftertaste that lingers. In roasted and darker oolong: toasted grain and caramel, wood, stone fruit and a mineral, rock-like character."},"missing":[]},
  "e339bc9f-3744-4cc1-a0c6-d914f35a0162": {"productId":"e339bc9f-3744-4cc1-a0c6-d914f35a0162","paragraphs":[{"layer":"age","text":"A rolled [Tieguanyin](tieguanyin:definition) from Anxi, made in 1995 and kept for thirty-one years since. It was made in the decade when the newer light, green style began to take over in Anxi. Tieguanyin held this long counts as a style of its own, which the trade calls chenxiang, or [old Tie](tieguanyin:styles). The light style goes stale fast, so the tea set aside for years is usually the heavier [charcoal roasted](tieguanyin:ageing) kind, kept sealed, dry, dark and cool, away from strong smells."},{"layer":"place","text":"[Anxi](anxi:where-it-is) is a county of Quanzhou in southern Fujian, on the southern side of the Daiyun mountains, and the trade names Xiping township there as the place this tea began. The county was still one of the poorer in the province until the 1990s, when the [Tieguanyin boom](anxi:history) changed that. The tea was rolled into its tight balls by [wrapping it in cloth](tieguanyin:making), pressing it and drying it a little, then wrapping it again, several times over, each round tightening the leaf."}],"brewing":{"layer":"brewing","text":"Tieguanyin is usually brewed gongfu style with water at or near the boil, about 95 to 100°C; the light green style is often taken a little cooler, about 85 to 95°C. Use about 4 to 8 grams of leaf in a 100 to 150 ml gaiwan or pot, about a third full. A quick rinse, poured off at once, is common. Steeps start short, about 10 to 30 seconds, and grow a few seconds longer each round, and a good Tieguanyin gives about six to eight. In a larger pot, use about 2.5 to 5 grams for 240 to 350 ml and steep two to three minutes."},"notice":{"layer":"notice","styleName":"aged Tieguanyin","text":"A smoother, rounder, softer cup with the fire gone, a liquor turned orange-red or reddish-brown, and often a soft fruity sourness."},"missing":[]},
  "e342e878-b5c8-4433-8a22-9af8265376c6": {"productId":"e342e878-b5c8-4433-8a22-9af8265376c6","paragraphs":[{"layer":"place","text":"This cake comes from [Wuliang Mountain](wuliang-mountain:where), a long range in west-central Yunnan rather than a single peak. It runs south from Nanjian in Dali, past Jingdong, Zhenyuan and Jinggu, and fades out toward Xishuangbanna. The leaf is from Jingdong County, one of the two counties most often named for the range's [old tea trees](wuliang-mountain:trees), which grow wild in the forest and as older plantings in village gardens."},{"layer":"type","text":"It was made into [ripe pu'er](shou:definition) and pressed in 2019. The leaf was wetted and heaped in a [fermenting pile](shou:wet-piling), covered to hold in the heat its own microbes make, and turned about once a week to let air in. The pile exists to give in weeks what raw pu'er reaches only after years of waiting, so a ripe cake is ready soon after it is made."},{"layer":"age","text":"At seven years the cake has entered the [settling years](shou:age-settling) of the style, the stretch between about five and ten years when what the pile left behind has usually aired away."}],"brewing":{"layer":"brewing","text":"From a cake, brick or tuo, ease a piece off along the edge with a pick rather than snapping it. Whole leaves give up their flavour steadily; broken ones release it all at once and cloud the cup. Ripe pu’er takes boiling water: fermented, tightly packed leaf needs full heat to open, and it does not scald the way green tea can. A common start is about 7 grams to 100 ml and one quick rinse, which wakes the leaf and carries off dust and any pile smell. Then short steeps that lengthen as the leaf opens, so the cup stays clear rather than heavy; it gives eight or more good cups."},"notice":{"layer":"notice","styleName":"ripe pu’er","text":"A smooth, sweet cup with earthy or woody notes. A young ripe tea can carry a faint smell of the pile, which fades with airing or in the first steeps."},"missing":[]},
  "e3a59d3d-c409-4db1-81b5-8d6176256aea": {"productId":"e3a59d3d-c409-4db1-81b5-8d6176256aea","paragraphs":[{"layer":"type","text":"A loose [Liu Bao](liu-bao:definition) from Guangxi, recorded as 1960. Liu Bao takes its name from the town of Liubao, and as a [dark tea](dark:definition) its leaf is piled after it is made, so that warmth, moisture and microbes darken and soften it before it is packed away to age. The year falls in the decades when the [river trade had already been cut](liu-bao:history) and production kept falling as the planned economy changed who could buy and sell tea."},{"layer":"age","text":"Sixty-six years on, it is far past the decade after which the trade counts a Liu Bao as [aged](liu-bao:age-aged), and how it was kept matters as much as how long. Liu Bao this old is mostly [old stock](liu-bao:old-stock) that sat in warehouses in Malaysia or Hong Kong after the mining trade ended. Such tea is hard to date, so the trade reads its age from the basket, the labels and the papers packed with it, and the place it was stored gives each lot its own character."}],"brewing":{"layer":"brewing","text":"Liu Bao takes very hot or boiling water, because its leaf is dense and gives up its depth slowly. Rinse it once or twice and pour the rinse away. Use about 5 to 8 grams to 100 ml, start with steeps of five to fifteen seconds and add a few seconds each round; a good Liu Bao gives ten cups or more."},"notice":{"layer":"notice","styleName":"aged Liu Bao","text":"A deep red, thick cup with woody, herbal and betel nut notes; tea several decades old is often described with ginseng and camphor."},"missing":[]},
  "e420493c-bd58-4ba2-a9c9-cf70ef13d0e7": {"productId":"e420493c-bd58-4ba2-a9c9-cf70ef13d0e7","paragraphs":[{"layer":"lot","text":"A cake of purple-leaf tea from Lincang, in Yunnan. The leaf was sun-dried into [maocha](sheng:making), the rough tea of the first making, and then compressed into cake form."},{"layer":"type","text":"As [raw pu’er](sheng:identity), it was never given the quick fermentation that makes shou. The leaf is fried to stop most of its enzymes but never hot-air dried, so some of that activity survives, and this is what lets the cake keep [changing in storage](sheng:aging) for years. [Pressing](sheng:pressing) began so tea could travel well on the old trade routes. It also sets how fast a tea ages: a tight, large cake changes slowly, and a loose or small one changes faster."}],"brewing":{"layer":"brewing","text":"Pry the leaf off a cake or brick in chunks with a pick or knife, from the surface and toward the centre, rather than crumbling it. A mix of larger pieces and smaller ones brews evenly. Young raw pu’er takes water a little off the boil, about 85 to 95°C, because hotter water draws out more of its bitterness; an aged one takes 95°C to boiling. A common start is about 7 grams to 100 ml and a quick rinse of a few seconds, then a first steep of ten to fifteen seconds, adding a few seconds each round. A good raw tea gives eight to ten cups or more."},"notice":{"layer":"notice","styleName":"aged Sheng Pu’er","text":"A smoother, thicker, sweeter cup with woody, herbal and camphor notes and something of dried dates or dark fruit."},"missing":[]},
  "e4531569-2424-48ec-8e24-3bca2550c661": {"productId":"e4531569-2424-48ec-8e24-3bca2550c661","paragraphs":[{"layer":"type","text":"A cake of [ripe pu’er](shou:definition): the leaf was fermented in a warm, damp heap before it was pressed. That way the tea can be drunk soon after it is made, while raw pu’er is usually left to age for years. In the [wet pile](shou:wet-piling), the heat comes from the microbes working on the leaf. The heap is covered to hold that heat in and turned about once a week to spread it and let air through. After one to two months the leaf is dried."},{"layer":"type","text":"The method [came to Yunnan in 1973](shou:piling-1973), when a team of seven from the Kunming, Menghai and Xiaguan factories went to Guangzhou to learn it. Kunming found that Guangzhou’s warm water failed in its cooler, drier air and succeeded with cold water the next year. By 1975 Menghai’s way of piling had settled into the ripe pu’er made today."}],"brewing":{"layer":"brewing","text":"From a cake, brick or tuo, ease a piece off along the edge with a pick rather than snapping it. Whole leaves give up their flavour steadily; broken ones release it all at once and cloud the cup. Ripe pu’er takes boiling water: fermented, tightly packed leaf needs full heat to open, and it does not scald the way green tea can. A common start is about 7 grams to 100 ml and one quick rinse, which wakes the leaf and carries off dust and any pile smell. Then short steeps that lengthen as the leaf opens, so the cup stays clear rather than heavy; it gives eight or more good cups."},"notice":{"layer":"notice","styleName":"ripe pu’er","text":"A smooth, sweet cup with earthy or woody notes. A young ripe tea can carry a faint smell of the pile, which fades with airing or in the first steeps."},"missing":[]},
  "e51918d3-cc6b-4bdb-ba65-8df3795f86ca": {"productId":"e51918d3-cc6b-4bdb-ba65-8df3795f86ca","paragraphs":[{"layer":"place","text":"A loose [oolong](oolong:definition) from Guangdong, made in the 1980s. The trade knows the province for one oolong above all, the [dancong](guangdong:phoenix-dancong) of Phoenix Mountain in Chaozhou. A label that names only Guangdong, though, does not say which mountain or village a tea comes from."},{"layer":"age","text":"At forty-one years, this is oolong that was kept rather than drunk fresh. Only well-made oolong is put aside like this, because [roasting](oolong:oxidation-and-roast) lowers the moisture so the leaf keeps. Damp is the danger over the years. Oolong held this long is usually [roasted again at low heat](oolong:ageing) from time to time to drive off what it has taken in, a skilled job that can cost some quality each round. The trade has no agreed age at which an oolong counts as aged."}],"brewing":{"layer":"brewing","text":"Oolong is most often brewed gongfu style, in a small gaiwan or clay pot with plenty of leaf and short steeps, and it stands many rounds. A common start is about 4 to 6 grams to 100 ml, with a first steep of roughly 5 to 15 seconds and 5 to 10 seconds more each round. Light, green-style oolong takes water a little off the boil, about 90 to 95°C; heavily oxidised, roasted and aged oolong takes water at a full boil. Many people pour a quick first rinse to wake tightly rolled leaf. In a larger pot, use less leaf and steep for a few minutes."},"notice":{"layer":"notice","styleName":"aged oolong","text":"A smooth, mellow and sweet cup, often with dried fruit or plum and wood, sometimes something herbal, little astringency, and an amber to red-brown liquor."},"missing":[]},
  "e57fa698-103d-422b-8231-75b8a9204c44": {"productId":"e57fa698-103d-422b-8231-75b8a9204c44","paragraphs":[{"layer":"type","text":"[Ya Shi Xiang](dancong:ya-shi-xiang) (鸭屎香), named for duck dung, is the market name for one line of [Phoenix Dancong](dancong:definition), the [oolong](oolong:definition) of Phoenix Mountain. The line is traced to Pingkengtou village. Three stories explain the name, and all are told only as stories: that it was chosen to keep thieves away from the bush, that it comes from the yellow local earth called duck dung soil, and that duck droppings lay on the bush. A second name, Yinhua Xiang, silver flower, was put forward in 2014, though many sellers keep the old one."},{"layer":"place","text":"Phoenix Mountain, [Fenghuang Shan](phoenix-mountain:where-it-is), is a range in Chao'an district of Chaozhou, in eastern Guangdong, with tea on its slopes up to roughly 1,100 metres. Cloud and mist sit on the upper slopes for much of the year and the nights are cool, so the bushes grow slowly. The higher the garden, the more a tea from it is expected to show what the trade calls [mountain rhyme](phoenix-mountain:mist-and-climate)."},{"layer":"age","text":"As with all Dancong, the leaf is withered in the sun, then [shaken and rested in rounds](dancong:making) to bruise its edges, fixed at high heat, rolled into long strips and roasted as it is refined. This is a 2026 tea. Freshly roasted Dancong is [rested for some months](dancong:ageing) before it is drunk, and it keeps sealed, dry, cool and out of the light."}],"brewing":{"layer":"brewing","text":"Brew it gongfu style in a small gaiwan or clay pot, with about 3 to 8 grams for 100 to 120 ml and hot water, about 88 to 100°C; Chinese accounts mostly say 95 to 100°C. A quick rinse is common. Steeps start at a few seconds and grow a few seconds each round, and a good Dancong gives about eight to fifteen. Too long, too hot or too much leaf and it turns bitter and astringent."},"notice":{"layer":"notice","styleName":"Phoenix Dancong","text":"Flowers above all, a sweetness that comes back after swallowing, a high scent that lasts, honey, often ripe fruit such as peach, and what the trade calls mountain rhyme, shan yun; a liquor from golden to orange-red or amber."},"missing":[]},
  "e5e7c9ec-d66b-48de-9197-272ffdb638e0": {"productId":"e5e7c9ec-d66b-48de-9197-272ffdb638e0","paragraphs":[{"layer":"lot","text":"Xiniu Tang (犀牛塘) means “Rhinoceros Pond.” This tea is a ripe pu’er pressed into a cake."}],"brewing":{"layer":"brewing","text":"From a cake, brick or tuo, ease a piece off along the edge with a pick rather than snapping it. Whole leaves give up their flavour steadily; broken ones release it all at once and cloud the cup. Ripe pu’er takes boiling water: fermented, tightly packed leaf needs full heat to open, and it does not scald the way green tea can. A common start is about 7 grams to 100 ml and one quick rinse, which wakes the leaf and carries off dust and any pile smell. Then short steeps that lengthen as the leaf opens, so the cup stays clear rather than heavy; it gives eight or more good cups."},"notice":{"layer":"notice","styleName":"ripe pu’er","text":"A smooth, sweet cup with earthy or woody notes. A young ripe tea can carry a faint smell of the pile, which fades with airing or in the first steeps."},"missing":[]},
  "e62c0616-4f3a-415c-8b82-03316a6cfb08": {"productId":"e62c0616-4f3a-415c-8b82-03316a6cfb08","paragraphs":[{"layer":"type","text":"A loose leaf [red tea](red:definition) from Yunnan, made in 2016. It is the fully oxidised tea that English calls black: once the leaf is broken, its own enzymes turn it from green to reddish brown. Red tea from this province is known as [Dian Hong](dian-hong:definition), made from Yunnan's large-leaf trees. The style dates from the war years: China was cut off from its eastern tea regions and needed a new red tea to sell abroad, so Feng Shaoqiu made a trial batch in Shunning, now Fengqing, in late 1938."},{"layer":"age","text":"At ten years old, this lot sits well outside the usual window. The trade drinks Yunnan red within its first one to three years and [keeps it for freshness](dian-hong:ageing) rather than for age, so a decade is well past what the style is kept for."}],"brewing":{"layer":"brewing","text":"Dian Hong takes hot water, roughly 90 to 100°C. A common start is about 5 grams to 100 ml, with short steeps that lengthen slowly as the leaf opens."},"notice":{"layer":"notice","styleName":"Dian Hong","text":"A full, sweet cup, often described as malty, with chocolate or cocoa and honey notes and sometimes something floral. The liquor runs golden to bright red, and a good grade has little bitterness."},"missing":[]},
  "e6bc9c2f-d8e1-4082-bc00-e46ac347fd3c": {"productId":"e6bc9c2f-d8e1-4082-bc00-e46ac347fd3c","paragraphs":[{"layer":"place","text":"A cake of [raw pu’er](sheng:identity) from 1998, its leaf grown in Menghai County in Yunnan. On a label, [Menghai](menghai-county:county-and-factory) can mean the county or the tea factory of the same name, which blends leaf from several mountains. Here it names the county where the leaf grew."},{"layer":"type","text":"The leaf was fried in a wok to [kill the green](sheng:making) but never dried with hot air afterwards. That leaves some of the leaf’s own activity alive, and that activity is what lets the tea keep changing in the cake for years."},{"layer":"age","text":"At twenty-eight years it is past both points where the trade says [aged](sheng:ageing) raw pu’er begins: ten years for some, twenty or more for many. Raw pu’er is not given shou’s rapid fermentation, so this cake has changed slowly in [storage](sheng:aging). How it was kept is as much a part of its history as its age."}],"brewing":{"layer":"brewing","text":"Pry the leaf off a cake or brick in chunks with a pick or knife, from the surface and toward the centre, rather than crumbling it. A mix of larger pieces and smaller ones brews evenly. Young raw pu’er takes water a little off the boil, about 85 to 95°C, because hotter water draws out more of its bitterness; an aged one takes 95°C to boiling. A common start is about 7 grams to 100 ml and a quick rinse of a few seconds, then a first steep of ten to fifteen seconds, adding a few seconds each round. A good raw tea gives eight to ten cups or more."},"notice":{"layer":"notice","styleName":"aged Sheng Pu’er","text":"A smoother, thicker, sweeter cup with woody, herbal and camphor notes and something of dried dates or dark fruit."},"missing":[]},
  "e6c6a2e0-a8ac-4ab3-a2f1-9b3e236ae5c3": {"productId":"e6c6a2e0-a8ac-4ab3-a2f1-9b3e236ae5c3","paragraphs":[{"layer":"age","text":"A loose [ripe pu’er](shou:definition) from Yunnan, made in 2009. At seventeen years it is well past the ten the trade counts as [aged ripe pu’er](shou:age-aged). The leaf goes on changing slowly with the air and moisture around it, which is why storage matters as much as the years."},{"layer":"type","text":"Like all ripe pu’er, this leaf went through the [wet pile](shou:wet-piling). It was wetted, heaped and covered so the heat of its own microbes could work on it, turned about once a week to let air in, and dried after one to two months. The pile was developed to give in weeks what Hong Kong and Guangdong drinkers knew from raw pu’er aged for years. Yunnan’s state factories brought it into production in 1973, thirty-six years before this tea was made."}],"brewing":{"layer":"brewing","text":"Ripe pu’er takes boiling water: fermented, tightly packed leaf needs full heat to open, and it does not scald the way green tea can. A common start is about 7 grams to 100 ml and one quick rinse, which wakes the leaf and carries off dust and any pile smell. Then short steeps that lengthen as the leaf opens, so the cup stays clear rather than heavy; it gives eight or more good cups."},"notice":{"layer":"notice","styleName":"aged ripe pu’er","text":"A smooth, deep cup with woody, date-like or medicinal notes, which the trade calls aged aroma."},"missing":[]},
  "e77d2550-f9d0-4965-850a-d2b2096fb71f": {"productId":"e77d2550-f9d0-4965-850a-d2b2096fb71f","paragraphs":[{"layer":"place","text":"Zhuangyuan Hong (状元红) is an oolong from the [Wuyi Mountains](wuyi-mountains:where-it-is), the range along the border of northern Fujian and Jiangxi, listed as a UNESCO World Heritage site in 1999. The bushes here grow on ledges and between rocks in the ravines, in thin soil that drains fast and under mist that settles on the slopes, and that ground is the reason the trade ties this tea so closely to the rock. [Oolong is traced to this area](fujian:history), and its making is said to have spread from here to Anxi, Guangdong and then Taiwan."},{"layer":"type","text":"Like all [Wuyi rock tea](yancha:definition), it is [partly oxidised](oolong:definition): withered in the sun, cooled indoors, shaken and rested, fixed in a hot pan or drum, then twisted into long strips rather than rolled into balls. What sets it apart is the [charcoal roast](yancha:making), given in several rounds with rests of weeks or months between them, which dries the leaf so it keeps. After roasting the tea is rested again before it is drunk, and [the heavier the roast](yancha:roast-levels), the longer that rest."}],"brewing":{"layer":"brewing","text":"Wuyi tea is usually brewed gongfu style with water at or near the boil, about 95 to 100°C, and about 5 to 8 grams of leaf in a 100 to 120 ml gaiwan, a third to a half full. A quick rinse, poured off at once, is common. Steeps start short, about 5 to 20 seconds, and grow a few seconds longer each round, and good rock tea gives seven steeps or more. In a larger pot, use about 2 to 5 grams for 250 to 350 ml and steep two to three minutes."},"notice":{"layer":"notice","styleName":"Wuyi rock tea","text":"Roast and stone fruit, a mineral, rocky texture and a long, sweet, mouth-watering finish. Light roast is bright and floral, medium roast fruity and rounded, full roast charcoal, wood and roasted nuts. Da Hong Pao is often floral, Rougui spicy with cinnamon, young Shui Xian sweet and smooth, and old-bush Shui Xian woody and mossy."},"missing":[]},
  "e949b585-5f07-411b-82fb-7da7355edc77": {"productId":"e949b585-5f07-411b-82fb-7da7355edc77","paragraphs":[{"layer":"lot","text":"A cake of [raw pu’er](sheng:identity) from Yiwu in Yunnan, made in 2004, which has rested since in Guangzhou’s tea trade. Its leaf was fried in a wok and dried in the sun but never [hot-air dried](sheng:making), so some of its own activity survived, and that is what lets a cake like this keep changing. Without shou’s fermenting pile, raw pu’er [changes slowly in storage](sheng:aging) instead, and because [heat and humidity](sheng:storage) set the pace, where a cake has been kept belongs to its history."},{"layer":"age","text":"At twenty-two years it has passed the twenty that many in the trade wait for before they call raw pu’er [aged](sheng:ageing), though some count from ten. How far it has come depends as much on that storage as on the years."}],"brewing":{"layer":"brewing","text":"Pry the leaf off a cake or brick in chunks with a pick or knife, from the surface and toward the centre, rather than crumbling it. A mix of larger pieces and smaller ones brews evenly. Young raw pu’er takes water a little off the boil, about 85 to 95°C, because hotter water draws out more of its bitterness; an aged one takes 95°C to boiling. A common start is about 7 grams to 100 ml and a quick rinse of a few seconds, then a first steep of ten to fifteen seconds, adding a few seconds each round. A good raw tea gives eight to ten cups or more."},"notice":{"layer":"notice","styleName":"aged Sheng Pu’er","text":"A smoother, thicker, sweeter cup with woody, herbal and camphor notes and something of dried dates or dark fruit."},"missing":[]},
  "ea0fc824-5e0f-4057-8d1a-0ea448aa0d99": {"productId":"ea0fc824-5e0f-4057-8d1a-0ea448aa0d99","paragraphs":[{"layer":"place","text":"This leaf grew in Menghai County, in Yunnan. The county's [tea mountains](menghai-county:peoples) are not one community: Bulang, Hani and Lahu villagers planted and still tend their own gardens, and who planted and who picks shapes each mountain's tea."},{"layer":"type","text":"It was made into [ripe pu’er](shou:definition), fermented in a warm, damp pile so that it is ready to drink soon after making instead of after years of ageing. In [wet piling](shou:wet-piling) the wetted leaf is heaped and covered to hold in the heat its own microbes make. It is turned about once a week to spread that heat and let air in, and kept below about 65°C, since hotter than that the leaf starts to char. After the pile the tea was shaped into balls."}],"brewing":{"layer":"brewing","text":"From a cake, brick or tuo, ease a piece off along the edge with a pick rather than snapping it. Whole leaves give up their flavour steadily; broken ones release it all at once and cloud the cup. Ripe pu’er takes boiling water: fermented, tightly packed leaf needs full heat to open, and it does not scald the way green tea can. A common start is about 7 grams to 100 ml and one quick rinse, which wakes the leaf and carries off dust and any pile smell. Then short steeps that lengthen as the leaf opens, so the cup stays clear rather than heavy; it gives eight or more good cups."},"notice":{"layer":"notice","styleName":"ripe pu’er","text":"A smooth, sweet cup with earthy or woody notes. A young ripe tea can carry a faint smell of the pile, which fades with airing or in the first steeps."},"missing":[]},
  "eb546627-c0fd-4486-b0ab-1263ab04a983": {"productId":"eb546627-c0fd-4486-b0ab-1263ab04a983","paragraphs":[{"layer":"place","text":"A cake of [ripe pu’er](shou:definition) made from leaf grown in Lincang, in Yunnan. Like all ripe pu’er, it was made to be ready to drink soon after it was made. Raw pu’er skips the pile and usually waits years."},{"layer":"type","text":"Before pressing, the sun-dried leaf went through [wet piling](shou:wet-piling). It was wetted and heaped so that heat, moisture and microbes could work on it. The microbes make the heat themselves, so the pile is covered to hold it in. It is turned about once a week to spread the heat and let in air, and kept below about 65°C, because above that the leaf starts to char. After one to two months the leaf is dried."}],"brewing":{"layer":"brewing","text":"From a cake, brick or tuo, ease a piece off along the edge with a pick rather than snapping it. Whole leaves give up their flavour steadily; broken ones release it all at once and cloud the cup. Ripe pu’er takes boiling water: fermented, tightly packed leaf needs full heat to open, and it does not scald the way green tea can. A common start is about 7 grams to 100 ml and one quick rinse, which wakes the leaf and carries off dust and any pile smell. Then short steeps that lengthen as the leaf opens, so the cup stays clear rather than heavy; it gives eight or more good cups."},"notice":{"layer":"notice","styleName":"ripe pu’er","text":"A smooth, sweet cup with earthy or woody notes. A young ripe tea can carry a faint smell of the pile, which fades with airing or in the first steeps."},"missing":[]},
  "ebdcf8c9-57e9-4e4b-bab0-683f1776792f": {"productId":"ebdcf8c9-57e9-4e4b-bab0-683f1776792f","paragraphs":[{"layer":"age","text":"A loose [red tea](red:definition) from Yunnan, made in 1997. Red tea from the province goes by the name [Dian Hong](dian-hong:definition), and the trade drinks it within its first one to three years, keeping it [for freshness rather than for age](dian-hong:ageing). At twenty-nine years, this tea is far older than that custom allows."},{"layer":"type","text":"The style began in wartime. With China cut off from its eastern tea regions, the country needed a new red tea to sell abroad, and a [trial batch](dian-hong:history) was made from Yunnan's large leaf in Fengqing in late 1938. For decades nearly all of it was shipped overseas, and it was sold widely at home only from the 1980s."}],"brewing":{"layer":"brewing","text":"Dian Hong takes hot water, roughly 90 to 100°C. A common start is about 5 grams to 100 ml, with short steeps that lengthen slowly as the leaf opens."},"notice":{"layer":"notice","styleName":"Dian Hong","text":"A full, sweet cup, often described as malty, with chocolate or cocoa and honey notes and sometimes something floral. The liquor runs golden to bright red, and a good grade has little bitterness."},"missing":[]},
  "f33d6d62-3f6d-49a8-9c19-31cf2236956b": {"productId":"f33d6d62-3f6d-49a8-9c19-31cf2236956b","paragraphs":[{"layer":"age","text":"A rolled [Taiwan oolong](taiwan-oolong:definition) from 1980, kept for forty-six years in the island's tradition of [lao cha](taiwan-oolong:ageing), old tea. Leaf chosen for keeping starts out well roasted and dry. It is roasted again at low heat from time to time to drive out the moisture it takes in, and kept cool, dark and sealed between roastings. No standard says when an oolong becomes old. Those who give a figure put it between ten and thirty years, and this tea is sixteen years past the longest of them."},{"layer":"place","text":"The label names only [Taiwan](taiwan:on-a-label). That places the leaf on the island and says nothing more: no mountain, no township, no cultivar. What it does carry is the island's own craft. [Oolong](oolong:definition) is the partly oxidised tea between green and red, and the island's trade is built on [rolled, bead-shaped oolong](taiwan:known-for) like this one."}],"brewing":{"layer":"brewing","text":"Ball-rolled Taiwan oolong takes hot water, about 90 to 100°C, a fairly generous amount of leaf and short steeps; the balls open slowly and give many infusions. Roasted Dong Ding takes water from about 95°C to a full boil. Aged oolong takes very hot water, in a pot that holds its heat, clay above all. Oriental Beauty is the exception and takes cooler water, about 80 to 95°C."},"notice":{"layer":"notice","styleName":"aged Taiwan oolong","text":"A smooth, mellow, thick cup with little astringency, often plum or prune, sometimes something like medicinal herbs or ginseng, and an amber to red-brown liquor."},"missing":[]},
  "f40e5962-395f-4959-a089-a203ec0683ca": {"productId":"f40e5962-395f-4959-a089-a203ec0683ca","paragraphs":[{"layer":"type","text":"Loose [raw pu’er](sheng:identity) made in 1976 from leaf grown in Menghai County, Yunnan. The county named on a label is a different claim from [Menghai Tea Factory](menghai-county:county-and-factory), which blends leaf from several of the county’s mountains. The leaf was fried in a wok to [kill the green](sheng:making), rolled and dried in the sun into maocha, then [left loose](sheng:processing) rather than pressed. It is never dried with hot air afterwards, so some of the leaf’s own activity survives, and that is what lets it keep changing for years."},{"layer":"age","text":"At fifty years it sits well past the point where the trade starts calling raw pu’er [aged](sheng:ageing): some set that at ten years, and many wait for twenty or more. Raw pu’er does not get shou’s quick fermentation, so it changes only [through storage](sheng:aging), and [heat and humidity](sheng:storage) decide how fast. Its five decades of keeping are part of its history as much as its age."}],"brewing":{"layer":"brewing","text":"Young raw pu’er takes water a little off the boil, about 85 to 95°C, because hotter water draws out more of its bitterness; an aged one takes 95°C to boiling. A common start is about 7 grams to 100 ml and a quick rinse of a few seconds, then a first steep of ten to fifteen seconds, adding a few seconds each round. A good raw tea gives eight to ten cups or more."},"notice":{"layer":"notice","styleName":"aged Sheng Pu’er","text":"A smoother, thicker, sweeter cup with woody, herbal and camphor notes and something of dried dates or dark fruit."},"missing":[]},
  "f6e2882a-bf37-490e-8625-91146fe98bfb": {"productId":"f6e2882a-bf37-490e-8625-91146fe98bfb","paragraphs":[{"layer":"lot","text":"A cake of [ripe pu’er](shou:definition) from the 1990s that was given a gold award. Its Yunnan leaf was fermented in a [wet pile](shou:wet-piling), wetted, heaped and turned so that heat, moisture and microbes could work on it, about two decades after Yunnan’s factories brought the method into production in 1973."},{"layer":"age","text":"At thirty-one years it sits well within what the trade counts as [aged ripe pu’er](shou:age-aged). The leaf goes on changing slowly with the air and moisture around it, which is why the way it has been kept matters as much as the years."}],"brewing":{"layer":"brewing","text":"From a cake, brick or tuo, ease a piece off along the edge with a pick rather than snapping it. Whole leaves give up their flavour steadily; broken ones release it all at once and cloud the cup. Ripe pu’er takes boiling water: fermented, tightly packed leaf needs full heat to open, and it does not scald the way green tea can. A common start is about 7 grams to 100 ml and one quick rinse, which wakes the leaf and carries off dust and any pile smell. Then short steeps that lengthen as the leaf opens, so the cup stays clear rather than heavy; it gives eight or more good cups."},"notice":{"layer":"notice","styleName":"aged ripe pu’er","text":"A smooth, deep cup with woody, date-like or medicinal notes, which the trade calls aged aroma."},"missing":[]},
  "f76dc835-bd7c-4193-a274-a9ac35e38c24": {"productId":"f76dc835-bd7c-4193-a274-a9ac35e38c24","paragraphs":[{"layer":"type","text":"Shenhua Native Red is a loose [red tea](red:definition) from China, the tea English calls black. The Chinese name follows the colour of the brewed cup, while the English one follows the dark dry leaf."},{"layer":"type","text":"It is made in four steps, each with a reason. The fresh leaf is [withered](red:making) until it goes soft enough to work, then rolled and bruised so its juices meet its own enzymes. It is left in warm, damp air while it turns from green to reddish brown, the change the Chinese trade calls fermentation. Drying with hot air ends that change and keeps the leaf stable."}],"brewing":{"layer":"brewing","text":"Red tea takes water near the boil, about 90 to 100°C; hotter water draws out its aroma and flavour more fully, but its bitterness faster too. In a pot or mug, use about a rounded spoon of leaf for each cup and steep three to five minutes, less for broken leaf and a little less, and a little cooler, for a light, delicate tea. Left too long, it turns bitter and drying, because time and heat pull more tannins from the leaf."},"notice":{"layer":"notice","styleName":"red tea","text":"A sweet cup, often with honey, floral or fruity notes, malt in many, and a brisk strength in the stronger teas. The liquor runs red, bright to deep."},"missing":[]},
  "f852497c-322b-4242-a72d-3c890127a4c3": {"productId":"f852497c-322b-4242-a72d-3c890127a4c3","paragraphs":[{"layer":"place","text":"This tea was grown in [Nantou](nantou:where-it-is), the county in the middle of Taiwan and the only one that does not touch the sea. It is the island's [biggest tea county](nantou:why-people-value-it), with more than half of its plantings, and within its borders the land climbs from low hills to cold mountain gardens. The record names the county and no township, and here it is the township that tells a roasted tea from a light [high mountain](nantou:altitude-bands) one."},{"layer":"age","text":"The leaf is from 2024, so it is two years old. Taiwan has a tradition of keeping oolong for years as [lao cha](taiwan-oolong:ageing), old tea. No standard says when an oolong becomes old, but those who give a figure put it between ten and thirty years, so this is a young tea."},{"layer":"type","text":"It is a rolled [oolong](oolong:definition), the partly oxidised tea that stands between green tea and red tea. Leaf rolled into balls is the common shape of [Taiwan oolong](taiwan-oolong:definition), whose plants and craft came over from Fujian."}],"brewing":{"layer":"brewing","text":"Ball-rolled Taiwan oolong takes hot water, about 90 to 100°C, a fairly generous amount of leaf and short steeps; the balls open slowly and give many infusions. Roasted Dong Ding takes water from about 95°C to a full boil. Aged oolong takes very hot water, in a pot that holds its heat, clay above all. Oriental Beauty is the exception and takes cooler water, about 80 to 95°C."},"notice":{"layer":"notice","styleName":"Taiwan oolong","text":"In light high mountain tea: a sweet, floral cup, often creamy or buttery, with little bitterness and a long sweet aftertaste. In roasted Dong Ding: caramel, ripe fruit, nuts and a toasted aroma. In Baozhong: floral notes and a clear, bright liquor. In Oriental Beauty: ripe fruit and honey, with little bitterness."},"missing":[]},
  "f8664316-b7de-4848-84cd-d3555884d842": {"productId":"f8664316-b7de-4848-84cd-d3555884d842","paragraphs":[{"layer":"place","text":"This oolong comes from [Alishan](alishan:where-it-is), the mountain tea area of Chiayi County in the southwest of central Taiwan. Its gardens sit on the western and southern slopes, mostly at about 1,000 to 1,600 metres, and they spread across [three townships](alishan:sub-areas): lower and middle ground in Meishan to the north, Zhuqi with Shizhuo and Fenqihu at the centre, and the higher gardens of Alishan Township along the mountain road. Cloud and fog cover the slopes for much of the day, the sun comes through filtered and the nights are cool, so the leaf grows slowly. The [name on a label](alishan:on-a-label) marks the mountain area as a whole, not one township, garden or height."},{"layer":"type","text":"It belongs to [high mountain tea](taiwan-oolong:high-mountain), gao shan cha, a name for where a tea grew rather than a cultivar or a recipe: gardens at about 1,000 metres and higher. This one is rolled, the usual form of the style, which is most often lightly oxidised and left unroasted or only lightly roasted. It is a [partly oxidised](oolong:definition) tea, and the plants and the craft of making it reached [Taiwan](taiwan-oolong:definition) with settlers from Fujian."}],"brewing":{"layer":"brewing","text":"Ball-rolled Taiwan oolong takes hot water, about 90 to 100°C, a fairly generous amount of leaf and short steeps; the balls open slowly and give many infusions. Roasted Dong Ding takes water from about 95°C to a full boil. Aged oolong takes very hot water, in a pot that holds its heat, clay above all. Oriental Beauty is the exception and takes cooler water, about 80 to 95°C."},"notice":{"layer":"notice","styleName":"Taiwan oolong","text":"In light high mountain tea: a sweet, floral cup, often creamy or buttery, with little bitterness and a long sweet aftertaste. In roasted Dong Ding: caramel, ripe fruit, nuts and a toasted aroma. In Baozhong: floral notes and a clear, bright liquor. In Oriental Beauty: ripe fruit and honey, with little bitterness."},"missing":[]},
  "f8be36d6-f3c9-4e8d-a615-f9fd5c7a0e05": {"productId":"f8be36d6-f3c9-4e8d-a615-f9fd5c7a0e05","paragraphs":[{"layer":"grade","text":"This is loose [ripe pu’er](shou:definition) of the [Gong Ting](gong-ting:definition) grade, sorted out of a batch for its small leaf and high share of buds. In the market the grade sits one step above special grade. [Dry leaf of this grade](gong-ting:appearance) is tight and straight, with golden down on the buds and no stray stems, and so little of any batch qualifies that the grade is always scarce."},{"layer":"place","text":"The leaf comes from Menghai County. On a label, [Menghai](menghai-county:county-and-factory) can mean the county or the Menghai Tea Factory, which blends leaf from several of the county's mountains. Here the name says where the leaf grew."},{"layer":"type","text":"It was made by [wet piling](shou:wet-piling): the leaf was wetted and heaped so that heat, moisture and microbes could work on it, covered to hold in the heat the microbes make, and turned to spread it and let air in. That is why it is ready to drink now rather than after years of ageing."}],"brewing":{"layer":"brewing","text":"Ripe pu’er takes boiling water: fermented, tightly packed leaf needs full heat to open, and it does not scald the way green tea can. A common start is about 7 grams to 100 ml and one quick rinse, which wakes the leaf and carries off dust and any pile smell. Then short steeps that lengthen as the leaf opens, so the cup stays clear rather than heavy; it gives eight or more good cups."},"notice":{"layer":"notice","styleName":"ripe pu’er","text":"A smooth, sweet cup with earthy or woody notes. A young ripe tea can carry a faint smell of the pile, which fades with airing or in the first steeps."},"missing":[]},
  "f8eb9207-8abe-4fd7-aaea-58c1b0ee50f8": {"productId":"f8eb9207-8abe-4fd7-aaea-58c1b0ee50f8","paragraphs":[{"layer":"named","text":"Small Yellow Mark is a label from the late 1960s and 1970s, when China’s large [state factories](sheng:history) pressed pu’er cakes with coloured characters stamped on the wrapper. Collectors call this the mark grade era (Yin Ji Cha), and Yellow Mark is one of the last names from it and one of the widely recognized ones."},{"layer":"lot","text":"This lot is broken pieces from such cakes, which is how a drinker can try a name usually only read about."},{"layer":"age","text":"The leaf is Yunnan [raw pu’er](sheng:identity), made in the 1970s. The trade does not agree where [aged](sheng:ageing) begins, some saying ten years and many waiting for twenty, so this tea is well past either line. Sheng is never given shou’s rapid fermentation, so its change has come slowly, year by year, and the [storage](sheng:aging) it passed through is part of its history."}],"brewing":{"layer":"brewing","text":"Young raw pu’er takes water a little off the boil, about 85 to 95°C, because hotter water draws out more of its bitterness; an aged one takes 95°C to boiling. A common start is about 7 grams to 100 ml and a quick rinse of a few seconds, then a first steep of ten to fifteen seconds, adding a few seconds each round. A good raw tea gives eight to ten cups or more."},"notice":{"layer":"notice","styleName":"aged Sheng Pu’er","text":"A smoother, thicker, sweeter cup with woody, herbal and camphor notes and something of dried dates or dark fruit."},"missing":[]},
  "f956eb25-cdc3-4cf3-8a15-86a9e731b3f7": {"productId":"f956eb25-cdc3-4cf3-8a15-86a9e731b3f7","paragraphs":[{"layer":"place","text":"This oolong was grown in [Nantou](nantou:where-it-is), the county in the middle of Taiwan and the only one that does not touch the sea. It holds more than half of the island's tea plantings, and its tea country is [divided by height](nantou:altitude-bands), from low hills to cool, misty gardens above about a thousand metres. The county name alone does not say which of those belts a tea grew in."},{"layer":"type","text":"The leaf was made as [GABA oolong](gaba:definition), which names a way of making tea, not a plant or a place. The fresh leaf is held for some hours [without oxygen](gaba:making), and Taiwan's method alternates those rounds with rounds in air. With no oxygen, the leaf turns its glutamic acid into GABA and cannot break it down again, so the GABA builds up. After that it is made like any [oolong](oolong:definition): withered and tossed, fixed, rolled and dried. The method was [found in Japan](gaba:history) in 1987, and Taiwan's tea research station adapted it to oolong."},{"layer":"age","text":"At two years it is a young tea. In Taiwan's tradition of keeping [old tea](taiwan-oolong:ageing), those who give a figure for when an oolong becomes old put it between ten and thirty years."}],"brewing":{"layer":"brewing","text":"In a cup or pot, steep it for about two to five minutes. It is forgiving of small changes in water temperature and steeping time. It can also be cold-brewed, steeped for some hours in the fridge."},"notice":{"layer":"notice","styleName":"gABA oolong","text":"Ripe, dried or stewed fruit such as apricot, honeyed sweetness, a smooth, round body, and little bitterness or astringency; often brown sugar or roasted grain, sometimes wood or spice, and a light fruity sourness."},"missing":[]},
  "fa5467b1-d6e2-4d34-b7c8-6c620f9141c5": {"productId":"fa5467b1-d6e2-4d34-b7c8-6c620f9141c5","paragraphs":[{"layer":"place","text":"A loose [green tea](green:definition) grown on [Taiwan](taiwan:on-a-label) in 1950. The label names only the island, not a mountain or township, so the place stops there. Taiwan's tea came from Fujian, and its trade is built on [oolong](taiwan:known-for), but green tea is made there too."},{"layer":"type","text":"The leaf was never allowed to oxidise. Soon after picking it was [fixed](green:making) with heat to stop its own enzymes before they could turn it brown, then rolled and dried so it would keep."},{"layer":"age","text":"Seventy-six years is far past the year or two that green tea is usually kept. The sources describe no tradition of [ageing green tea](green:ageing), and the type promises nothing over time, so how this tea was kept counts for more than its years."}],"brewing":{"layer":"brewing","text":"Green tea takes water well below the boil, about 80°C, a little cooler for the youngest leaf and a little warmer for older, larger leaf. Boiling water draws out bitterness and dries the cup. A common start is about 2 grams of leaf to 100 ml, in a glass or a small gaiwan, with short steeps of half a minute to two minutes, and the same leaf can be brewed a few times."},"notice":{"layer":"notice","styleName":"green tea","text":"A fresh, clean cup that many call crisp, with a sweet, soft finish, and a pale green to yellow-green liquor. The smell runs from fresh leaf to flowers, and steamed teas lean grassy or seaweed-like. Too much heat or too long a steep turns the cup bitter and drying."},"missing":[]},
  "fb92f73e-a1f2-4740-bb14-110726deae71": {"productId":"fb92f73e-a1f2-4740-bb14-110726deae71","paragraphs":[{"layer":"place","text":"This leaf comes from the [Wuyi Mountains](wuyi-mountains:where-it-is), the range along the border of northern Fujian and Jiangxi. UNESCO listed it as a World Heritage site in 1999, and much of it is protected forest. Its different ground makes two very different teas: [rock oolong](wuyi-mountains:two-teas) from the stony valleys lower down, and red tea from the high northern edge around Tongmu. Tea shipped from these mountains to Europe in the seventeenth and eighteenth centuries was sold as [Bohea](fujian:history), a spelling of the local way of saying Wuyi."},{"layer":"type","text":"[Zhengshan Xiaozhong](lapsang:definition), true mountain small kind, is the red tea of Tongmu. Zhengshan names that core, and tea made the same way outside it is called waishan, outer mountain. Abroad it is known as Lapsang Souchong, a name taken from the Fuzhou dialect. It is called the [oldest red tea](lapsang:history), though the dates given for it differ. [Red tea](red:definition) is what English calls black tea: the leaf is fully oxidised, and the Chinese name follows the red colour of the brewed cup."},{"layer":"type","text":"The leaf is withered, rolled and left to oxidise until it turns reddish brown to copper. It then goes through a hot pan, [guo hong guo](lapsang:making), which stops the oxidation fast, and is rolled again while hot to shape the strip. In the traditional way it is dried over a fire of local pine in a [qinglou](lapsang:smoke), a wooden house of several floors with the fire at the bottom and the leaf on bamboo mats above, so the heat and smoke rise through it. The strongly smoked style was made for export. In China the name also covers gentler and unsmoked tea."}],"brewing":{"layer":"brewing","text":"In a cup or pot, use about 3 grams for 240 ml, with water at 90 to 100°C, and steep about two to five minutes, usually around three. Gongfu style, use about 5 grams in a 100 to 110 ml gaiwan or pot, with short steeps that grow a little longer each round. Too hot or too long and the smoke turns harsh and bitter and covers the tea."},"notice":{"layer":"notice","styleName":"Lapsang Souchong","text":"In the smoked tea: pine and pine resin, longan or dried longan, campfire or woodsmoke, dried fruit and a sweet aftertaste. In the unsmoked tea: honey, longan and fruit or flowers."},"missing":[]},
  "fc0428e2-af14-4ae3-b32d-75d8f0dc2154": {"productId":"fc0428e2-af14-4ae3-b32d-75d8f0dc2154","paragraphs":[{"layer":"lot","text":"A cake of [raw pu’er](sheng:identity) from Yunnan, made in 2007 from sun-dried maocha and listed in the shop as humid-stored, the practice the trade calls [shi cang, or humid storage](sheng:storage). Raw pu’er changes partly through slow oxidation and partly through the work of microbes. Warmth and moisture speed both, so a humid store reaches in fewer years what a dry, cool one takes far longer to reach. In the twentieth century, merchants in Hong Kong, then pu’er’s great drinking market, kept their tea this way [to hasten its change](sheng:history). The trade still does not agree whether humid storage is a flaw or a style of its own."},{"layer":"age","text":"At nineteen years, this cake sits where the trade begins to argue about [aged raw pu’er](sheng:ageing). Some count from ten years, while many wait for twenty or more. Because raw pu’er is never put through shou’s rapid fermentation, its [storage belongs to its history](sheng:aging). A humid store is not a promise of quality."}],"brewing":{"layer":"brewing","text":"Pry the leaf off a cake or brick in chunks with a pick or knife, from the surface and toward the centre, rather than crumbling it. A mix of larger pieces and smaller ones brews evenly. Young raw pu’er takes water a little off the boil, about 85 to 95°C, because hotter water draws out more of its bitterness; an aged one takes 95°C to boiling. A common start is about 7 grams to 100 ml and a quick rinse of a few seconds, then a first steep of ten to fifteen seconds, adding a few seconds each round. A good raw tea gives eight to ten cups or more."},"notice":{"layer":"notice","styleName":"aged Sheng Pu’er","text":"A smoother, thicker, sweeter cup with woody, herbal and camphor notes and something of dried dates or dark fruit."},"missing":[]},
  "fc255a0a-e27d-4f0f-b36a-81c4331a3d3e": {"productId":"fc255a0a-e27d-4f0f-b36a-81c4331a3d3e","paragraphs":[{"layer":"type","text":"Wisdom is a [raw pu’er](sheng:identity) from Yunnan, sold loose rather than pressed. It began as leaf from the province’s large-leaf tea trees: picked, withered, then fried in a wok to [kill the green](sheng:making), rolled and dried in the sun. The leaf is never hot-air dried afterwards, so some of its own enzyme activity survives the heat, and that is what lets the tea keep changing for years."},{"layer":"type","text":"Raw pu’er may be pressed into cakes or [left loose](sheng:processing), and this tea was kept as leaf. It was never given the quick fermentation of shou, so it [changes slowly in storage](sheng:aging), and the conditions it is kept in become part of its history."}],"brewing":{"layer":"brewing","text":"Young raw pu’er takes water a little off the boil, about 85 to 95°C, because hotter water draws out more of its bitterness; an aged one takes 95°C to boiling. A common start is about 7 grams to 100 ml and a quick rinse of a few seconds, then a first steep of ten to fifteen seconds, adding a few seconds each round. A good raw tea gives eight to ten cups or more."},"notice":{"layer":"notice","styleName":"Sheng Pu’er","text":"In young raw pu’er, a bitter, drying bite that turns into a returning sweetness, a feel in the throat that makes the mouth water, and fresh, floral or fruity notes such as apricot or plum. Tea kept in humid storage can carry a damp, earthy storage taste."},"missing":[]},
  "fed37e7f-fb67-4422-a888-27f5cca1f022": {"productId":"fed37e7f-fb67-4422-a888-27f5cca1f022","paragraphs":[{"layer":"lot","text":"Inspiration is a [raw pu’er](sheng:identity) from Yunnan, sold as loose leaf rather than pressed. Nobody recorded the mountain it grew on or the year it was picked, so this page names neither."},{"layer":"type","text":"Raw pu’er starts as leaf from Yunnan’s large-leaf trees. The leaf is fried in a wok to [kill the green](sheng:making), then dried in the sun rather than by hot air, so some of its own activity survives. Kept loose, this tea stays close to [maocha](sheng:processing), the rough tea that other makers press into cakes. That surviving activity is why raw pu’er [keeps changing in storage](sheng:aging) over the years, and why where a tea has been kept becomes part of its history."}],"brewing":{"layer":"brewing","text":"Young raw pu’er takes water a little off the boil, about 85 to 95°C, because hotter water draws out more of its bitterness; an aged one takes 95°C to boiling. A common start is about 7 grams to 100 ml and a quick rinse of a few seconds, then a first steep of ten to fifteen seconds, adding a few seconds each round. A good raw tea gives eight to ten cups or more."},"notice":{"layer":"notice","styleName":"Sheng Pu’er","text":"In young raw pu’er, a bitter, drying bite that turns into a returning sweetness, a feel in the throat that makes the mouth water, and fresh, floral or fruity notes such as apricot or plum. Tea kept in humid storage can carry a damp, earthy storage taste."},"missing":[]},
  "ff4e1549-98ee-4498-be19-f80730c38ece": {"productId":"ff4e1549-98ee-4498-be19-f80730c38ece","paragraphs":[{"layer":"type","text":"A loose [Yunnan white](yunnan-white:definition), made from the province's large leaf tea plants rather than the small and medium leaf bush cultivars of Fujian, where most [white tea](white:definition) is still made."},{"layer":"type","text":"It follows the white tea way: the leaf is [withered and then dried](yunnan-white:making), never heated to stop its change and never rolled. In Yunnan the wither is done indoors or in shade, out of the midday sun, and the leaf dries by air, without the final low bake that Fujian white tea usually gets. As a style it is [recent in the market](yunnan-white:history). Its trade has grown only in recent years, though local practice may be older."}],"brewing":{"layer":"brewing","text":"Yunnan white is brewed gently, as a white tea is, in a gaiwan or small pot, and it gives many infusions; the leaf holds up well."},"notice":{"layer":"notice","styleName":"Yunnan white","text":"A honeyed, sweet cup, often richer and fuller than Fujian white, with little bitterness, sometimes fruit like apricot or melon and a hay or herbal note. Yabao is sweet and silky, often with pine or herbal notes."},"missing":[]},
};
